/* 平成13年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h13.committeeSessions.push(...[{"id":"h13-20010925-5","meetingId":"h13-cm09","date":"2001年9月25日","dateIso":"2001-09-25","committee":"総務委員会","time":"午前１０時０４分～午後５時２６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"行います。なお、議案等の審査順につきましては、説明理事者の調整をほかの常任委員会とした上で予定表のとおりとしたものであります。 それでは、まず","agenda":"行います。なお、議案等の審査順につきましては、説明理事者の調整をほかの常任委員会とした上で予定表のとおりとしたものであります。 それでは、まず","exchanges":[{"speaker":"三上委員","kind":"質問","question":"そういう部分の文言の整理、国の流れというのは、今、どういうふうになっているんでしょうね。そこらあたりを教えてください。","respondent":"太川総務課長","answer":"ただし実質上、横書きで動いているものもあります。全体として、国の動きは、量的に膨大すぎて、まだそこまで行っていないという話は聞いてあります。基本的には、自治体のほうが先行していると考えています。","voiceIndex":9,"id":"exchange-001"},{"speaker":"三上委員","kind":"質問","question":"私どもはいろいろな形で情報を整理するときに、むしろものすごく逆に整理しづらいです。そういう部分が進まないんであれば、私は、まだ横書きにする必要は何もないという考え方もいけるんじゃないかと思うわけです。だから、それに当たって、区長会あたりもどういうふうに動こうとされているのか、どうなんでしょうかね。","respondent":"太川総務課長","answer":"いずれ、少しずつ自治体の中でもこういう動きが出てきた段階で、私どもも、今、庁内イントラが始まりまして、インターネットで国の情報を大変便利に使ってありますので、そういう意味では、今、委員のご指摘のとおり、版はＡ４にほぼ確定してはまいりましたけれども。","voiceIndex":11,"id":"exchange-002"},{"speaker":"三上委員","kind":"意見","question":"そういった意味で、しっかりほかのところにも呼びかけいくように、いろいろな機会を使ってお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-003"},{"speaker":"北野委員","kind":"質問","question":"それは、１年間に１回書き換えて、各会派に設置するというお話を伺ってはいるんですが、あれはＡ４版にして、毎年１冊置くときに、いちいち印刷し直すんではなくて、差し替えできるような形のほうが有効ではないかなと思うんですけれども、どうなんでしょうか。","respondent":"太川総務課長","answer":"余計なあれですが、経費的な部分につきましても、今までの金額からいきますと３分の２以下で、新しい情報４回の入れ替えができるというメリットがありますので、そういうものを私どもとしては考えております。","voiceIndex":14,"id":"exchange-004"},{"speaker":"北野委員","kind":"質問","question":"庁内のパソコンに入って、すごくいいんですけれども、年１回印刷をして、各会派に控えとして置いておく例規集を、毎年印刷していくんではなくて、交換する部分だけ差し替えていったほうが経費的にもいいんではないかなということで、ちょっとお伺いさせていただいたんです。その点については、どうなんでしょうか。","respondent":"太川総務課長","answer":"今回、いわゆるパソコン上に入れましたものをプリントアウトすることによって１冊つくるということになりますから、経費的には全然違ってくるということを、一応、ご理解いただきたいと思います。","voiceIndex":16,"id":"exchange-005"},{"speaker":"北野委員","kind":"意見","question":"わかりました。今回は、条例と規則ということですけれども、品川区には要綱とか、要領とかいっぱいありますよね。ゆくゆくは、それもやはり目に見えるような形で、ホームページの中に入れていく必要があるんじゃないかと思いますけど、それについてお考えを。","respondent":"太川総務課長","answer":"要綱、要領につきましては、基本的に決して非公開のものでも何でもございませんので、それはある程度、時期、全体の流れの中で、私どもとしてもやっぱり考えていくべきものとは思ってあります。","voiceIndex":18,"id":"exchange-006"},{"speaker":"北野委員","kind":"質問・要望","question":"条例の部分は私たちの目にとまるんですが、要領とか、要綱の部分というのは、事業内容によっては変わらないでいくものと、やっぱり使い勝手が悪くなると変えてしまったりとか、目に見えないところがあるので、事業には必ずつくわけですから、区民の方に対しても、技術的に載せられる時期が来たら、一日も早く載せていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"今の北野委員のお話と若干関連するんですが、今回の縦書きを横書きにする対象の条例が、今条例の施行前に公布されたすべての条例ということになっておりますが、施行前に公布されたすべての条例を対象にする意味というんでしょうか、どのような対応をされるのかということで、ちょっとお伺いしたいんです。縦書きのすべてのものをまた横書きに直して、また各職員の方々に再交付するということなのか。","respondent":"太川総務課長","answer":"先ほどもちょっと申し上げましたけれども、いわゆる形式的にパソコン上の処理でまいりますので、縦の部分はそのままにしておいて、横の部分だけ対応しているということはありません。","voiceIndex":21,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"あわせて、経費的な面なんですけれども、主にシステムの変更上でかかってこようかと思いますが、システム上、あるいはその他、経費的なものでどれぐらいかかるものなのかだけ、お伺いします。","respondent":"太川総務課長","answer":"予算上、５２０万円組んです。それと、先ほどもちょっと申し上げましたけれども、四部冊ある例規を、年１回差し替えるのに１,３００万円ほどかかりますので、その辺から見ていただきますと、経費的には、大幅に減になっていると考えております。","voiceIndex":23,"id":"exchange-009"},{"speaker":"林（宏）委員","kind":"意見","question":"いいことは全部聞きましたけど、これをすることのデメリットというか、心配事というか、何かありませんか。それはそれでわかりやすくなってきたというのは事実なんだけども、一方で、歴史のことだとか、文化的なことだとかいうのが消されたというか、そういうのがあって、僕は今回、非常にそれと似て非なのか、似て似なのかわからないんですけど、そういうところが皆さんの議論の中でされたのかどうか。","respondent":"太川総務課長","answer":"直接は、委員、ご指摘のところの歴史、文化的なものが、これによってなくなっていくんではないかという観点での議論はしてございません。","voiceIndex":25,"id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問","question":"すごく寂しい。日本の役所だし、日本人の気持ちというのは、なくしてはいないんだろうけど、ビジネスライクに没頭しないで、議論ぐらいはしてほしいなという気がしてならないんです。それから、条例の文の中で一番最後の付則のところなんですけど、「この条例は、規則で定める日から……」となっていますが、なぜこうなったんですか。普通は、いつからと明記されるんだけど、この理由を聞かせてください。","respondent":"太川総務課長","answer":"これにつきましては、現在、今回の条例も含めまして、まだ施行期日が決まっていないものもありますので、そういう意味合いで、今回、提案されているもの全部を含めまして、いつというのが決定された後、施行するという形をとっていますので、こういう書き方をしています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、例えば、来年の４月１日からということになると、これも４月１日からということで、一番遅いのに合わせると理解してよろしいんですか。","respondent":"太川総務課長","answer":"そのとおりです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりました。じゃあ、もう１点だけ。具体的に、例えばこの条例で、一番右側に第７１号議案とありますが、これはアラビア数字になるのかなと思うんです。それから、第一条、第二条というのはアラビア数字になるんですか。「高橋久二」の「二」は漢字ですね。","respondent":"太川総務課長","answer":"第一がアラビア数字です。","voiceIndex":31,"id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"第一条、第二条の漢数字はアラビア数字になるんですね。はいいです。ここの説明文の中に決めてある内容は、よくわからないけど、日本語という学会がありますよね、そこで取り決められているところによって、こういうように、ア、イ、ウ、エ、オという順番で書かれると考えていいんですか。","respondent":"太川総務課長","answer":"順番ですか。","voiceIndex":33,"id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問","question":"違う、違う。アに六本木とか、九州というのは、こういうふうに書かれている。それから、イは、一般、一部、ウは云々かんぬんと書かれているけど、この取り決め、約束事というのは、日本語学会みたいなところで決められているものなんですか。","respondent":"太川総務課長","answer":"この取り決めと言えば取り決めですが、品川区の用字・用語例の訓令が昭和３６年に出ておりますけれども、それに基づいております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"「いろは」を「あいうえお」に、なぜ変えるんですか。アラビア数字はわかる、横になるから。「いろは」を「あいうえお」に変えた理由を聞かせてください。","respondent":"太川総務課長","answer":"これにつきましても、公文例および用字例です。昭和３６年に交付されております。","voiceIndex":37,"id":"exchange-016"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっと説明してほしいんだけど、縦書きは「いろは」で、横書きは「あいうえお」と決まっているんですか、それは。","respondent":"太川総務課長","answer":"そのとおりです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりました、決まっているんならしようがない。最後の最後にします。説明文というか、条例そのものもそうなんだけど、左横書きという言い方をされているんですけど、この説明文の上から４行目に「縦書きから横書きに改める」と書いてある。なぜ、ただ単なる「横書き」じゃいけないんですか。ここも、「横書き」で意味が通じるんですけど。昔の看板にはあったけど。","respondent":"太川総務課長","answer":"やはり、左から横書きにするということはきちっと決めなきゃいけないことです。今、言われたように、看板は、今も右のもありますので、ついては、左横書きです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"土井副委員長","kind":"質問","question":"一番大きいのは、一般的に横書きにするのは何数字というんですか、時計文字のあれね。次が、１、２、３、次が(1)、(2)とかになっていく。そしてまた、一番最後のところにきて、一般的には、日本的にはＡ、Ｂ、Ｃがないものですから、あ、い、うとなるのが多いように思うんです。ここで採用したのは、どういう形で決められているものを普遍的と考えてやったのかということを聞きたいんです。","respondent":"太川総務課長","answer":"これにつきましては、いわゆる私どものほうで、先ほどから言っております公文例および用字例で言っておりますけれども、公文上は、そのように決められているものです。","voiceIndex":48,"id":"exchange-019"},{"speaker":"土井副委員長","kind":"質問","question":"わかりました。そうじゃなくて、横にするんだったら、そういうものも含めて、全部クリアにするような法則、法令を、当たり前の形で、だれもが認める形でつくるべきじゃないですかと。そのためには、いわゆる日本語学会というのがあるのか、日本ナンバリング学会というのがあるのかどうは知らないけれども、そういう普遍的なものに依拠すべきじゃないかと思うものですから、伺っているんです。","respondent":"太川総務課長","answer":"大変失礼ですが、ナンバリングというのは、いわゆる１、２、３、４という意味ですか。そういう意味ですか。","voiceIndex":50,"id":"exchange-020"},{"speaker":"土井副委員長","kind":"意見","question":"大きい１、２、３、第１条とかありますね。それから、第何項、第何号というふうにどんどん下にいくわけですが、そのときに、統一的にやり方をしっかり決めていかなければならない。そういうやり方の順序立てをきちんと決めたものがどうなっていますかということです。","respondent":"太川総務課長","answer":"それにつきましては、今までの条例も全部含めてそうですけれども、いわゆる、先ほどから何度も申し上げておりますが、公文例、用字例の部分では、その辺につきましてはきちっと決められて、ルール立っているものと考えています。","voiceIndex":52,"id":"exchange-021"},{"speaker":"土井副委員長","kind":"質問","question":"要するに、そのルールは変えられないという意味ですね。そうじゃくて、現代の世の中に合うようにせっかく左横書きにするわけですから、そのときにあわせて、ナンバリングもきちんと、一般的にどこにいっても普通に通用するやり方というのがあるはずだ。それをどうなさっていますかと。","respondent":"太川総務課長","answer":"もし、仮に調整しなければ事態ということでありましたら、またそれはそこで考えなきゃいけませんが、現行の中で、そこのルール立てというのはできていると考えています。","voiceIndex":54,"id":"exchange-022"},{"speaker":"土井副委員長","kind":"意見","question":"それが、したがって、こういうおかしなことになるんじゃないかと。要するに第何条とかというのがあって、１、２、３があって、(1)、(2)、(3)があって、あ、い、うとなっていく、そういう流れを言っているんです。その流れが、どこか飛っじゃっているんじゃないかと言っているんです。","respondent":"市岡企画財政課長","answer":"先ほどから総務課長が申し上げている、品川区公文例および用字例という訓令がございまして、これは実は、国の用字例を参考に、品川区としても昭和３０年代に定めたものです。","voiceIndex":56,"id":"exchange-023"},{"speaker":"土井副委員長","kind":"意見","question":"もう１回だけ。先ほど、お話があったように、国のほうは縦書き、分量が多いからということで逃げているのかどうかわからないけれども、そういう状況ですね。そうすると、我々のほうで先に決めましょうというお話なんですよね。これから、何かありました段階等では、ぜひ、そういう議論にもしっかり参加していただければありがたいと思います。感想だけ述べておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-024"},{"speaker":"林（宏）委員","kind":"確認","question":"もう１回、すみません、確認だけさせておいてください。そうすると、「清掃一部事務組合の第一条による」という書き方をしたときは、第一条の「一」は漢字で書いて、品川区の条例を引き合いに出すときは、アラビア数字の「１」という書き方をしないと間違いとなってくるのかどうかという点を一つ。そうなってくると、今度、品川区内に出る文書はすべて横書きになると考えなきゃいけないんですか。","respondent":"太川総務課長、本間総務部長","answer":"ただし、それこそ先ほどの文化の話ではございませんが、やはり縦でやらざるを得ないものもありますので、その部分は、やはり例外として残さざるを得ないかなと考えています。じゃあ、すべて役所が発する文書が横書きになるかといいますと、例えば古来から一番あれなのが、区の表彰条例に基づく表彰状で、これは縦書きで、日本古来の文書の形式にのっとって区民の方を顕彰しているということで。","voiceIndex":59,"id":"exchange-025"}]},{"id":"topic-02","title":"の第８２号議案、特別区人事・厚生事務組合の共同処理する事務の変更および特別区人事及び厚生事務組合規約の変更","agenda":"の第８２号議案、特別区人事・厚生事務組合の共同処理する事務の変更および特別区人事及び厚生事務組合規約の変更","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"私、今回の質問で触れましたように特別区人事・厚生事務組合の役割というものは、人事・厚生、２３区の職員の待遇についても決めてもらうということが本心だろうと思うんですけれども、それも既に時代的に役割が終わりつつあるという認識を示しております。それと、負担の責任といいますか、どこがどれを負担するかということを説明願いたいと思います。","respondent":"太川総務課長","answer":"それで、東京都がその半分の２億１,０００万円、２３区が、残りの２分の１を２３分の１ずつ負担ということで、９００万円の支出になる、経費的には、そういうことです。","voiceIndex":67,"id":"exchange-026"},{"speaker":"塚本委員","kind":"意見","question":"それは、はっきり言って迷惑施設だから、ずっとやられちゃ困るという話で、一時的に受け入れて、１年過ぎましたから出て行ってくださいと。今の説明を受けても、建設のときの中央負担はこうで、運営についてはこうだという話も見えてきません。具体的にさっきの数字の部分で、施設と運営経費の按分のところをもう１回聞くのと、考え方のところで、助役のお考えを聞かせてください。","respondent":"太川総務課長、本間総務部長","answer":"それで、平均いたしまして、１区９００万円です。こういう共同事務の基本的な考え方という後段のご質問ですけれども、本会議上でも、区長からご答弁させていただきましたとおり、自立した自治体として、それぞれ独立した自治体が事務を担うというのは大原則だと思いますが。","voiceIndex":71,"id":"exchange-027"},{"speaker":"塚本委員","kind":"質問・要望","question":"ですから、広域的なのはわかるけど、なぜ東京都じゃないのかということ。いろいろないきさつがあって、むだなことをやっていたわけですね。それを踏まえれば、今のコンセプトでいいのかということを聞いているんです。特別区人事・厚生事務組合の法律論のところは、それで結構ですけれども、今の路上生活者に対応する施策については、もう一度お答えをいただきたいと思います。なぜ、東京都じゃないのか。","respondent":"濱野助役","answer":"今回のホームレスの問題というのは、この問題ともちろん同一ではありませんけれども、根っこが同じであるということ、あるいは、広域的な対応が必要であるということ、それから極めて福祉事務所なり、生活保護といったものとオーバーラップするものがあるというようなことで。","voiceIndex":74,"id":"exchange-028"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういうことをしないと、おかしなものがずっとこのまま当たり前の顔をして動いてくるということで、ぜひ、そういう経過を踏まえたものだという認識を、この場で新たに、ある程度共通のものになったと思いながら、事態に対応していただきたい。これでやめときます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"意見","question":"今のどちらが見るのかということはちょっと置いておいて、今回、新しくセンターを設置するところで、大田区が３００人、あと１００人程度が４カ所で、全部で７００人分かなと思うんですけれども、参考の５区のところを見ると、大体の合計がそれと同じような数字になっているようですが、平成１３年２月では、２３区の路上生活者が５,０００人ぐらいになっているという説明だったんですけども。","respondent":"黒田生活福祉課長","answer":"現在、自立支援センターが３カ所でき上がってあります。墨田区が年内の１２月か１月ぐらいの予定で、今、動いてありますけれども、自立支援センターが、渋谷区を含めて５カ所できますと、４００名程度です。","voiceIndex":77,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"私の質問の趣旨は、数が非常多い中で、今、回転とおっしゃったんですけど、やっぱり一番心配されるのは、冬をどういうふうに乗り切るかというのがあるかと思うんです。そこら辺のところは、どういうふうに考えているのかということ。実際には、今の不景気の中でかなりまた増えてくるんじゃないかと、私は想像しているんですけども、そこら辺のところはどんな感じで見ておられるのか、あわせてお願いします。","respondent":"黒田生活福祉課長","answer":"今年度につきましても、今、いる方が全員どうなるかということで、自立支援センターと一時保護センターで動いてはございまして、冬に間に合うようにオープンしますけれど、その方々以外にも、寒さに耐えられないお年寄りとか、障害をお持ちの方に対して、人数は少ないんですが。","voiceIndex":79,"id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほどおっしゃっていた回転率、いわゆる就職していく、自立していくという方向で指導されることになると思うんですけど、実際上、就職して一人立ちしていくのはどんな感じになっているのかというのを教えていただきたい。特に今ですと、就職が非常に厳しい中で、どういうふうな手立てなのか、何か強化策みたいものがあるのか、どうなのか。そこら辺のところは、どうでしょうか。","respondent":"黒田生活福祉課長","answer":"路上生活をしていた方が自立支援センターに入りまして、今年の８月末なんですが、就労による自立をされた方が４１.３％です。ただ、入所をしながら就職をして、働きながら自立のためのアパート代をご自分で稼いでいただく。","voiceIndex":81,"id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"大体わかりました。そこのところが、区の対応が機械的かなという感じも受けたものですから、かなり数が多くなってきますけれども、ぜひきめ細かい対応をしていただければと思います。交通災害のほうもいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと交通災害共済のほうで伺いたいんですけども、今度、これを廃止するということなんですけど、まず、「構成区の合意に基づく」ということになっていますけども、品川区としてはどういう対応をしてきたのかというのが一つ。実際に、これに入っている団体といいますか、利用しているところはどういうところが多いのか。そこのところを、ちょっとお聞かせいただきたいと思います。","respondent":"宮地区民課長","answer":"１点目の、「構成区の合意に基づく」ということで、品川区の態度ということだと思いますが、品川区としましては、いろいろ検討させていただきましたが、共同処理は廃止するという方向で結論を出しています。","voiceIndex":85,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"かなり減ってきているんで、なかなか事業として進めていくこと自体、いろいろ議論があろうかと思うんですけども、まず、やっぱりそういう意味じゃ、手軽に使えるというのがあったかと思うんです。実際に町会とか商店会の方々はかなり使っていたんですけども、こういうところの方々の意見というか、声というのは実際に聞いておられますか。","respondent":"宮地区民課長","answer":"これから皆さんにご審議いただく部分ですので、あまり大々的にお聞きすることはできないんですけれども、これまで使っていただいた感想とか、これがなくなってしまったらどうでしょうかとか、ほかにも入っているかどうかということで、何人かの方に伺ったところ。","voiceIndex":87,"id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問","question":"そういう中で、手軽に入れる保険だったものですから、私の聞いたところは全体じゃないんですけど、やっぱりそういう方もいるから、これは続けていってほしいという声もありましたから、これは紹介しておきます。実際問題、例えば２３区の中でも、品川区は廃止を主張されたということなんですけども、廃止を主張されない区も当然あるわけですよね。そこら辺のところは、どうでしょうか。","respondent":"宮地区民課長","answer":"最終的には、参加するところは数区になろうかと思いますが、それを対象に、民間の保険会社がある保険制度を検討しています。ただし、それにつきましてのスケールメリットとか、実際には、相当保険料もアップせざるを得ない。","voiceIndex":89,"id":"exchange-036"},{"speaker":"宮崎委員","kind":"意見","question":"１点。これを、区のほうとしてはやめる方向なんですけど、実際にやめた場合に、例えば町会、商店会の方で今まで利用されていた方への対応といいますか、それはどういうふうにされますか。","respondent":"宮地区民課長","answer":"個人的に入っていらっしゃる方には、今後、１０月末から１１月中旬にかけまして、お手紙を差し上げて、経過措置としてのいろいろな部分がありますので、その後、それも説明した内容の直接のお手紙を差し上げる予定です。","voiceIndex":91,"id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"要するに、区と都が一部事務組合に委託しているみたいなものじゃないですか。今、あそこができたら４億円だ、５億円だ、これができると３億円だとかいうような、細切れと言ったら、ちょっと言い方が失礼だけど、部分的にしか見えてないんですけど、これをしていくにはどのぐらいの事業費がかかってくるのかというのは、東京都と話しをしないんですか。","respondent":"市岡企画財政課長","answer":"とりあえず、今、各区への負担をお願いをされているのは、先ほど、総務課長、それから生活福祉課長が申し上げた段階です。","voiceIndex":93,"id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"一部事務組合というか、さっき言った、基礎的自治体が受け持つのと、いわゆる都道府県が受け持つのとの折り合いだと思うんですよね。中途半端じゃずるずるいくだけだと思うんですけど、どこまで財政的に品川区が出せるものか、これも全部が見えてないんだから、非常に難しいとは思うんですけど、その辺、東京都と話をしてみるべきじゃないかという気がするんですけど、いかがですか。","respondent":"黒田生活福祉課長","answer":"品川区でも、平成１３年度で、現在厚生施設がありますけれど、その費用も含めて、１億２,０００万円強のお金が出るということで、それ以上の費用負担はもうできないということで、意見を出しました。","voiceIndex":95,"id":"exchange-039"},{"speaker":"林（宏）委員","kind":"意見","question":"福祉厚生委員会関係のお話も混ざってきちゃうんで、それはそれでお願いをしておきますけど、財政的な部分、それから、いわゆる都と区の仕組みの中の部分で、やるものはきちんとお金を出して。自転車対策だって１億円をかけているんだから、やるときはどんとやる。塚本委員が冒頭に力強く言った、思惑が見え隠れしているというのが事実だなという気がしてならないです。お願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-040"},{"speaker":"北野委員","kind":"質問","question":"交通災害共済のことで、ちょっとお伺いしたいんですけれども、来年の４月１日廃止ということですけれど、これはたしか、事故に遭って、入っている間は補償がつきますよね。その年を外れたとしても、１年か２年の請求の期間があると思うんですけれども、廃止された後、その補償はどうなるのか、ちょっとお伺いしたいんです。","respondent":"宮地区民課長","answer":"加入している期間に事故に遭われた場合、それから請求期間というのが２年間あります。その間は、請求できますので、実際には、平成１３年度末にこの事業はなくなりますけれども、平成１３年度末に入った人は、１年間は加入を続けられるということになります。","voiceIndex":98,"id":"exchange-041"},{"speaker":"北野委員","kind":"意見","question":"わかりました。それは、加入するときに、ちゃんと説明していただいていることですよね。事故に遭わないことが一番なんですけれども、入った以上は、補償ということはぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-042"}]},{"id":"topic-03","title":"平成１３年請願第８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願","agenda":"平成１３年請願第８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"ご説明ありがとうございました。私立幼稚園の経営が大変厳しい環境にあることは、ご案内のとおりです。というのは、私立幼稚園がいろいろな延長保育、あるいは特殊事業、近年のいろいろな多様なニーズに対応しようということで、やはり人の手当てをどうやっていくかということ、これに歴然と公私の格差が出てきているということが実態じゃないかと思います。その辺の認識は一緒なのかどうか、教えてください。","respondent":"太川総務課長","answer":"来年度予算にすぐ反映できるかどうかは、ちょっとまだこれから検討しなきゃいけない部分ですけれども、その考え方といたしましては、私どもも、実情に合った部分での考え方を少し取り入れていくべきものと考えています。","voiceIndex":108,"id":"exchange-043"},{"speaker":"塚本委員","kind":"質問・要望","question":"大変力強いご答弁で、方向はそっちだと思います。実態は、私の感覚でものを言わせてもらうと、先生の給与は、公務員の６掛けか７掛けぐらいだろうと思います。それで、勤務時間も、かなり無理をしていらっしゃる。それになお、延長保育やいろいろなメニューをつくらなければ、公立と競争ができなくなるという妙な現象が起きておりますので、今のお答えを具体化することを強く要望します。","respondent":"太川総務課長","answer":"補助金全体のやり方について、見直していきたい。それにつきましては、実情に合った形を少し取り入れて考えていくべきときが来ているかなという意味ですので、よろしくお願いいたします。","voiceIndex":110,"id":"exchange-044"},{"speaker":"宮崎委員","kind":"意見","question":"今、課長の答弁の中身は、具体的にどういうことを考えておられるのか、説明できる範囲でいいんですが、もうちょっと詳しくお願いしたい。それからもう一つは、この請願の中に公私格差是正と書いてあるんですけど、資料のところで、実際に公私の格差がどのぐらいになっているかというのがよくわからないんですけども、そこら辺の説明をしていただければと思います。","respondent":"太川総務課長","answer":"具体的にどういうことかですが、基本的には、平たく言いますと、汗を流していただいているところといただいていないところの部分の見直しをきちっとしていかなきゃいけないという意味合いで、ちょっと言い方としてはきついかもしれませんが。","voiceIndex":112,"id":"exchange-045"},{"speaker":"宮崎委員","kind":"質問","question":"いわゆる、保護者負担の部分ということですね、そこの資料がなかったものですから、わかりました。努力して、大分近づいてきているということですね。わかりました。一番最初の入園奨励費のほうは、どうですか。","respondent":"太川総務課長","answer":"入園料補助金ですか。","voiceIndex":116,"id":"exchange-046"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"内容的には、お答えで、公私の格差が迫ってきているということですけど、保護者負担の部分もありますし、予算が絡む請願ですから、できればきょう決めていただきたい。扱えないんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"わかりました。私どものほうは、予算の絡みがありますので、絶対的なことも言いづらい立場にありますので、予算編成の中で、できる限り考えていただきたいというお願いを込めて、趣旨採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"私は一般質問でも申し上げたんですが、所得の考え方、とらえ方という中で、可処分所得というんでしょうか、どれだけ負担に耐えられるのかというところもあわせた考えた支援のあり方を考えていただきたいという思いも一方です。十分、区としての取り組みはしていただいているんですが、そういった観点も、ぜひあわせてご検討いただきたいという意を含めて、ぜひ採択をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-049"},{"speaker":"中島委員","kind":"質問","question":"むしろ、私立幼稚園に行かせているお母さんたちから、出産育児一時金じゃないけれど、どうせ出るなら春に出してほしいという声も聞いているぐらいですから、決して春に幼稚園に通わせているんではなくて、幼稚園ということで、子どもの教育のために選んでいることだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-050"},{"speaker":"北野委員","kind":"質問・要望","question":"私も紹介議員になっているということで、ぜひ、採択していただきたいと思います。予算の絡みはありますけれども、やはり私立園側の自助努力ということもありますけど、保育園、公立の幼稚園を含めて、保護者がどういう園に行かせたいかとか、いろいろなところで選択できるような何らかの支援は必要ではないかなと思っていますので、趣旨採択ではなくて、採択をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-051"},{"speaker":"土井副委員長","kind":"質問・要望","question":"というのは、別の形で後から来るものですから、月々が高いので、この格差がそれだけになっているということに対するご理解が不十分な感じがしないでもないんですね。ぜひそれらのことも、あわせてしていただきたいということもお願いをしながら、予算の都合があるのは当然ですので、その範囲の中で、やれるものはやっていただきたいということも含めて、趣旨採択ということでお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-052"},{"speaker":"林（宏）委員","kind":"意見","question":"私たちは趣旨採択をお願いしましたから、それで結構ですけど、本来は、採択をしたいという方がいらっしゃれば、採択からいかないと。この請願を出した方の本意は採択なんだから、少数だけどその人がいる限りは、やっぱり採択からいかないとならない。そうすると、不採択になる可能性がある。何も説得はしていませんよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"私もあまり経験がないもので、間違った意見になってしまっているかもしれないんで、そのときはご指摘いただきたいんですが、まず、一番最初に採択かどうかの決を取っていただき、仮に少数であったならば、次に、趣旨採択についてイエスかノーかという聞き方が行えるのかどうか。そういうことは可能なんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-054"},{"speaker":"北野委員","kind":"質問・要望","question":"やはり、これは予算を伴うということで、さっきも発言させていただきましたけれども、方向性としては、皆さん同じ考えだと思いますので、ぜひ、努力をしていただきたいということで、私は趣旨採択ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"私も、限りなく採択を主張しますが、予算編成権、執行権は区長側にありますし、裏付けとなるものが、ぜひ実現ををしていただきたいという願意も含めて、趣旨採択に同意いたしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-056"}]},{"id":"topic-04","title":"第７０号議案、平成１３年度品川区一般会計補正予算","agenda":"第７０号議案、平成１３年度品川区一般会計補正予算","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"これはしていいのかどうかわからないのだけれど、予算委員会に出られないのでいいのかなと思いつつ、総務委員会なのでお聞きします。一つは、基金に積み立てるリサイクル基金なんですけど、一般財源になっているんですよね。ずっと疑問に思っていたんで、きょう説明をされて、そういう手法しかないのか、そのときにわかりやすい処理をすることはできないんですかね。","respondent":"市岡企画財政課長","answer":"そうすると、もしこれが平成１３年度に入ってからですと、今回、歳入のほうは指定寄附金で組んで、歳出は基金積立金で組んで、見合いではっきりしたんですが、実は、この１０万円は、先ほど繰越金をちょっとご説明申し上げましたけど、あの中に紛れ込んでしまったんです。","voiceIndex":159,"id":"exchange-057"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりました。それから、少子化対策の基金が５００万円入っているんですね。これは、平成１３年度で終わるようになっているとすれば、その基金の残額、つまり、あと幾らぐらい使えるのか、教えていただけますか。","respondent":"市岡企画財政課長","answer":"もし４７０万円ぴったりの予算を組んでしまいますと、基金に残が生じて、これは返さなきゃいけないので、細かいですけども、落差見込みでぎりぎり組んでおきまして、もしあてが外れれば、一般財源を何千円か何万円か出さなきゃいけないかもしれないんですが。","voiceIndex":161,"id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問・要望","question":"歳入のところで、先ほど説明があった、１０ページで公営住宅等供給促進緊急助成事業なんですけども、これについて具体的にどういう内容なのか、どういう背景で出てきたのか、そこら辺の説明をいただきたいと思います。","respondent":"市岡企画財政課長","answer":"というのは、国のほうも公共事業について、いろいろ見直しをしておりまして、現在の内閣でも、都市再生の新しい公共事業の模索をやっておりますので、いろいろな諸般の状況を考えますと、今回もらわなと、もうもらえない補助金だろうということで、先ほど。","voiceIndex":171,"id":"exchange-059"},{"speaker":"宮崎委員","kind":"意見","question":"今年度が最後となると、先ほどの西大井のところは区営住宅と複合施設にするんですけど、例えばこういうところなんかは対象になるのか、ならないのか。そこのところは、どうでしょう。","respondent":"市岡企画財政課長","answer":"ただ、公営住宅の場合は、一定期間なんですが、もともと家賃に対する家賃対策の補助ですとか、今回、設計費の補助金がありますが、設計費、建設費というものの補助金が制度として確立しております。これは法律の補助ですので、こちらが優先されるという形になります。","voiceIndex":173,"id":"exchange-060"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうしますと、区営住宅はだめということなんですね。わかりました。教育費のほうで、人権尊重教育推進費というのが追加になっておりますが、たしか区内では２校が指定されていたかと思いますが、何か事業を拡大するのか、どういうふうな内容になるのか、ちょっとお知らせいただきたい。","respondent":"市岡企画財政課長","answer":"内容は、従前の引き継ぎです。","voiceIndex":175,"id":"exchange-061"},{"speaker":"三上委員","kind":"意見","question":"１９ページの仮称西大井六丁目複合施設の設計委託等について、予算計上されている。これがすべて載っていたのかどうか、たまたまちょっと見た新聞報道によると、これはプロポーザル方式でやるということが載っていたんですけど、そのような形でやられるのかどうかというのに興味を持っているんですけど。","respondent":"市岡企画財政課長","answer":"ただ、今回のは建設費本体ではありませんで、まず自主設計をして、その辺のメリット、デメリットをよく検討したいと、所管では進めております。","voiceIndex":178,"id":"exchange-062"},{"speaker":"三上委員","kind":"質問・要望","question":"まだ決まってないということとして確認させていただきたい。このやり方というのは、果たして、今の時代に合っているのかどうか。営業の人たちがどんな思いで一つにチャレンジして、仕事として取れるのかということまで考えてもいいんじゃないかと思うけど、そこらあたりの、自治体としての考え方というのか、どういうふうに受けとめて考えていこうとされているのか、伺っておきたいなと思います。","respondent":"岡田施設課長","answer":"プロポーザル方式ですが、確かに、品川区のプロポーザル方式はお金を出しません。したがいまして、説明会のときにそういう趣旨の説明をしまして、もちろん、提案方式という形ですので、営業努力の中で、それに提案できる設計事務所で結構ですと、こういう形の説明をしています。","voiceIndex":180,"id":"exchange-063"},{"speaker":"三上委員","kind":"質問・要望","question":"考え方はわかりました。自治体の仕事をやっぱり取りたい、次の営業につながっていくとなると、やっぱり必死になってやっているわけですよね。だから、そこのところで、やっぱり契約の負担が軽くということで、結局、それができるところは限られてくることは、もう目に見えているわけです。結果的にどういうふうになるか、それはわかりませんけれども、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-064"},{"speaker":"北野委員","kind":"質問","question":"１点、質問なんですけども、国庫委託金で児童手当の事務費が２１６万７,０００円というのが入っているんですけども、これは、事務費のほうと、それから後の２５ページの職員費のところに分かれていますよね。それで、一般財源に入って相殺されている形なんですけども、それはどういう意味なのか、お伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"したがいまして、ある基準で事務費、消耗品や用紙類に充てた残りを、職員費に充てれば、それだけ区の一般財源が軽くなるということで、財源更正という言い方で、民生費、職員費のところに載せてあるものです。","voiceIndex":183,"id":"exchange-065"},{"speaker":"北野委員","kind":"質問","question":"事務費に充てている８４万４,０００円というのが、受託事務として、一応、事務の範囲の中では、この経費で賄えるということですか。それで残りの分を、職員費のほうで相殺したということですか。","respondent":"市岡企画財政課長","answer":"そういうご理解でよろしいかと思います。","voiceIndex":185,"id":"exchange-066"},{"speaker":"田中委員","kind":"質問","question":"大変ボリュームが多いんですが、時間の関係もあるので、１点だけに絞ってお伺いしたいんですが、西大井六丁目の複合施設に関してですが、今回、都から区へ移管してこのような事業を行うということですけれど、今までのケースとして、都から移管されるものには何らかの条件というんでしょうか、２０年間はその目的でとか、ほかの目的に転用してはならないとか等々の。","respondent":"市岡企画財政課長","answer":"順次まいりますが、１点目の、移管についての条件ですが、都と区の、これまでも都営住宅の区移管への要綱というのがございまして、この中では、２０年間この用途のとおり、公営住宅として使うということが条件になっております。","voiceIndex":187,"id":"exchange-067"},{"speaker":"宮崎委員","kind":"質問","question":"今の西大井六丁目のところは、現時点で何部屋あって、今度出てくるんでしょうか、区営住宅としては何部屋になるのか、この辺の計画はどうなんですか。","respondent":"市岡企画財政課長","answer":"現況から申し上げますと、都営住宅が４２戸あります。ここに区営住宅としては、４６戸建て替えで、つまり４戸増やすわけですが、その４戸は、先ほど申し上げたとおり、障害者向け住宅ということで、特定目的住宅で別に募集をするということになります。","voiceIndex":189,"id":"exchange-068"}]},{"id":"topic-05","title":"の第７６号議案 仮称母子生活支援施設等複合施設新築工事請負契約","agenda":"の第７６号議案 仮称母子生活支援施設等複合施設新築工事請負契約","exchanges":[{"speaker":"三上委員","kind":"質問・要望","question":"ですから、これについては、できるならば、そういった情報が仮にあった場合には、ご努力いただきたいと、これはお願いしておきたいと思っています。特に、この建物の建て替えに当たって、近所の皆さんに地元説明会をやって、何らかの要望とか、お願いだとかということがあったのかどうか、ちょっとお教えていただけませんか。","respondent":"岡田施設課長","answer":"説明会は、２回ほどやってあります。１回目は、基本計画ができたときに、計画概要の説明会をいたしました。それから、先日、工事説明会という形で、解体工事のほうは決まっておりますので、これを含めて説明会を行いました。","voiceIndex":197,"id":"exchange-069"},{"speaker":"三上委員","kind":"質問・要望","question":"あわせて、今、歩道部分については少しセットバックして広げたということがあるんですけど、ここの部分だけ広げると、公園のほうもちょっと通路を広げてもらいたいなと、所管じゃないからあれなんですけども、そういう声というのは当然出てきちゃうんですけど、そこらあたり、公園の改築とか、そういった公園改修の件がありましたら。","respondent":"岡田施設課長","answer":"したがいまして、隣の公園のほうも、最近、よく２項道路の話が出ておりますけれども、何らかの形で動かすときには、そういう機会をとらえて、やはり同じような広さにしていきたいというつもりで、これは開発指導のほうから指導を受けて設計したものです。","voiceIndex":199,"id":"exchange-070"},{"speaker":"北野委員","kind":"質問","question":"これが大体みんな同額のところの並んでいるというのは、どうしてなのかすごく疑問に思うんです。区として、建物を建てるときには、大体こういうものを使うとかいう決まりがあって、それでみんな構造は同じものとし、建物を建てるんだったらこれぐらいの金額というのが、目安として公示しないまでもわかるんですか。","respondent":"西島経理課長","answer":"したがいまして、きちっとある程度包み込んでいけば、そんなに大きな誤差が出てこないと考えています。","voiceIndex":201,"id":"exchange-071"},{"speaker":"北野委員","kind":"質問","question":"大体、使う建材というものは、やっぱり仕様書ではこういうものと決まっているものがあって、結局、その中から建設の方たちは選ぶんですか。","respondent":"岡田施設課長","answer":"したがいまして、それから外れたものは私どもの検査に引っかかりますので、使えないようなシステムになっております。これは、契約書に一緒に綴じ込まれますので、それに基づいて積算するなり、あるいは、現場の材料を選ぶというような形になってあります。","voiceIndex":203,"id":"exchange-072"},{"speaker":"北野委員","kind":"質問","question":"それで出てくるんですけれども、使われる範囲というのは何種類か決まっているから、こういうふうに金額的な誤差というのが出るんでしょうね。いいものが高いというわけではないと思いますけれども、入札をしたときに、区として選ぶ基準というのはどういうところなんでしょうか。","respondent":"西島経理課長","answer":"例えば人件費の問題だとか、あるいは、工事管理費の問題、あと当然、商売ですので、利潤をどれだけ取るかというところにかかわってくるわけですけど、その中で、幾らの金額にするかというのは、それぞれ入札参加者のほうで決めて応札してくるです。","voiceIndex":205,"id":"exchange-073"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっと、２点、確かめておきたいんです。１点目は、今までのひまわり荘ですと、たしか３１部屋だったと思うんですけども、今、空きがあったかなと思うんですけど、今度は、部屋数としては２０に大分減ってますよね。２０部屋で大丈夫というか、その辺の実情といいますか、ちょっと説明いただければと思います。","respondent":"谷田部児童課長","answer":"認可定員に対しまして、在所される世帯の数が下回りますと、厚生労働省のほうから、定員を改定しなさいというような指導もありますので、その辺の両方から見まして、今回、２０世帯として定員を設けたところです。","voiceIndex":207,"id":"exchange-074"},{"speaker":"宮崎委員","kind":"質問","question":"じゃあ、そうすると、大体のこの間は１５とか、そのぐらいで推移しているということなんですか。わかりました。それと、もう１点なんですけども、請負契約のところをざっと見ますと、今回も小川組東京支店ということになっていまして、よく見ると、東京支店とか、品川支店とか、東京営業所とかになっているんです。そこら辺のところは、どういうふうにお考えなのか。考え方を、ちょっとお願いします。","respondent":"西島経理課長","answer":"申しわけございません、株式会社小川組がどのぐらいかというのは、私は確認していませんけど、資本金から見ますと、１億３,６５０万円ですので、ゼネコンということではなくて、中と大のちょうど中間ぐらいの規模ではなかろうかと考えてます。","voiceIndex":209,"id":"exchange-075"},{"speaker":"宮崎委員","kind":"質問","question":"私はこれを見ると、言葉は悪いですけど、地元への参加、参入のために名目上事務所を置ているとか、そういうことはないのかどうかというところの判断というのは、どうされているんですか。","respondent":"西島経理課長","answer":"特に新規登録の場合は、新規登録を受けた後で、必ず調査に行って、区内業者だと認定をしてやっておりますので、その辺は、間違いないと考えています。","voiceIndex":211,"id":"exchange-076"},{"speaker":"塚本委員","kind":"質問","question":"間違いの指摘を、先にしておきたいと思います。１８ページ、５番目に高田・塩谷建設共同企業体、代表者横河云々と書いてありますけど、これは、３のところからそのまま移ってきちゃっているけど、印刷ミスじゃないですか。おそらく、高田何とか工業とかいう名前になるんだろうと思うんですけど。","respondent":"西島経理課長","answer":"失礼いたしました。ここは、高田工業の間違いです。","voiceIndex":221,"id":"exchange-077"},{"speaker":"林（宏）委員","kind":"質問","question":"こんなに資本金は大きいんですか。ダントツですよ。","respondent":"西島経理課長","answer":"正式名称は、もう一度、確認して報告します。申しわけありません。","voiceIndex":223,"id":"exchange-078"},{"speaker":"塚本委員","kind":"質問","question":"後でいいです。質問のほうをしますけれども、近年、ゼネコンが大変経営難でして、株価を見れば、額面割れするような企業もある。そのときに、完成保証の部分で、そこがどういうふうになっているか。一つだけだったら、それはまた別のところと契約して保証するというのはわかるんですけど、ＪＶを組んでますから、上がこけたときに、下はどういう影響をこうむるのかということについて、教えてください。","respondent":"西島経理課長","answer":"建築の場合、４億円以上の工事についてはＪＶを組むというでやってありますので、二十数億円という金額ですので、特に特例規定は設けてございません。それから、契約保証金の問題ですけれども。","voiceIndex":225,"id":"exchange-079"},{"speaker":"塚本委員","kind":"質問","question":"もとがつぶれる可能性がかなりあるということは、皆さん認識しているわけですね。今までどおり、こういうことはまずないというと、こっちも、自治体のほうもつぶれるわけがないしという感覚の中で、契約慣行が今までのとおりでいいのかというような質問の趣旨なんですよ。","respondent":"西島経理課長","answer":"そういう意味ですと、今までは契約保証金というのを取ってございまして、完成工事ができない場合には、そこから賠償する。あるいは履行ボンドという保険に入ってございまして、できない場合にはそこで補償するという取り扱いになってあります。","voiceIndex":229,"id":"exchange-080"},{"speaker":"塚本委員","kind":"質問","question":"ご存じですよね。これだけ大きくなって、経済情勢が変わってきているんですから、そこのところが今までどおりでいいか、保証金で賄えるのかどうか。もちろん、ぽしゃんになっちゃったということを心配しているんじゃなくて、そういう契約がしっかりしていて、速やかに健全なる企業が請け負って、こういう約束になっていましたから、私が仕事をさせてもらいますとなるかどうかということを聞いているんです。","respondent":"岡田施設課長","answer":"過去において、ＪＶではありませんでしたけれども、ＪＶの下のほうが、そういうことになったことがあります。そのときも、やはり同じような形で、できた部分については支払いをするけれども、できてない部分は後の人に受け継いでもらうというような形でやってあります。","voiceIndex":231,"id":"exchange-081"},{"speaker":"塚本委員","kind":"質問・要望","question":"それで心配なのは、ＪＶで工事をすることになっているときに、今までは、一番下がつぶれても上が面倒を見る体力があったから、そこのところは大丈夫だったんだけれども、上がつぶれたら、大きさが違うわけですから、その次々がもろに会社がすっとんでしまうというような事態も考えられるわけですよね。そこのところを仕組みをしっかりしてほしいということが願い。結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-082"},{"speaker":"田中委員","kind":"質問","question":"大きく２点お伺いしたいと思います。１点は、契約というものの考え方というか、とらえ方とか、そういう部分でお伺いしたいんです。それは、地方自治法で条例で決まっているということで、十分理解を示しているところなんですが、その上で、こういう契約というものの考え方、また一方、議会側とのかかわりにおいての考え方というのをまずちょっとお伺いしたいと思います。","respondent":"西島経理課長","answer":"道路の補修、あるいは改修という部分が出てまいりますと、それまでということになると、なかなか問題が出てまいろうかと考えています。現在のところは、そういう状況で進めているです。","voiceIndex":234,"id":"exchange-083"},{"speaker":"田中委員","kind":"質問・要望","question":"調整池の上にできることで、例えば川の水のにおいだとか、騒音だとか、湿気だとか、特に今回のケースは調整池の上にできる施設だという観点から、何か特別な配慮などがされた施設になるのかどうかを、ちょっと確認をさせていただきたい。","respondent":"岡田施設課長","answer":"今の構真柱は、後ほど建てる建物のこともある程度頭に入れてスパンを考えておりますので、そういう意味では、それほど大きなデメリットにはならないかなと考えています。","voiceIndex":236,"id":"exchange-084"},{"speaker":"田中委員","kind":"質問・要望","question":"まだ実際に現場を見てないので、何とも言えないんですが、例えば、水かさが上がって、池に水が大量に流れ込む際の音ですとか、振動とか、そういうものがあると、上に住む方々が、また一方で何らかの影響を受けるのかなと思いましたので、今から設計変更とかは難しいかもしれませんけれども、そういう池の上にできる施設だということを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-085"}]},{"id":"topic-06","title":"の第８１号議案、大崎駅東西自由通路延伸部分および乗換えこ線橋整備工事請負契約","agenda":"の第８１号議案、大崎駅東西自由通路延伸部分および乗換えこ線橋整備工事請負契約","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"これは、品川区の財産になるのか。ついでに、ホームの上にできる乗換えこ線橋についてもお願いします。だれの持ち物になって、維持管理はだれがして、事故があったときの責任はだれが持つのか。","respondent":"市岡企画財政課長","answer":"Ｆ型の乗換えこ線橋ですが、これはデッキ施設の一部ですので、経理関係はちょっと複雑なんですが、ＪＲの駅舎部分を一部臨海が使用権を持って管理する部分と、ＪＲがＪＲの資産として管理する部分とに分かれるかと思います。","voiceIndex":246,"id":"exchange-086"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、時間が経過していくと補修等が出てくる。それから、どういう形かよく見えないんだけど、窓ガラス状のものがあったりして掃除だとか、もろもろのランニングコストが品川区にかかる。この間の明石みたいな事故が起きたときに、どこがというのが出てくると思うんですけど、その辺はこれから協議するわけですか。人のお金でやるから、あまり強くは言えないのかもわからないけど。","respondent":"市岡企画財政課長","answer":"基本的には、まだ設置費用についてしか協議をしておりませんので、これからなんですが、所管のほうを通じて、将来、東西自由通路の便益を享受する東西の開発事業者にも一定のご負担を願いたいという協議を進めていくつもりでおります。","voiceIndex":248,"id":"exchange-087"},{"speaker":"林（宏）委員","kind":"意見","question":"非常に甘いと思うんです。それだけはお願いしておきたい。そんなことはないと思うんですけど、大崎駅は相当人が増えてきて、その辺もしっかりしておかないと、何が起きるかわからないので、ぜひお願いをしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":250,"id":"exchange-088"},{"speaker":"三上委員","kind":"質問","question":"ちょっと聞かせてもらいたいのは、随意契約で、契約先が東日本旅客鉄道株式会社ということになりますよね。きょうのタワーなんかを見てみると、鹿島とか、要するにゼネコンが工事を受けているという形になっていますよね。ＪＲ東日本が工事をやるということじゃなくて、結局、間に入って、どこかに仕事をやらせるという仕組みにならざるを得ないと受けとめているんですけども、それで間違いないですか。","respondent":"市岡企画財政課長","answer":"鉄道施設以外の工事については、管理上もいろいろ難しい問題がありまして、区がＪＲ東日本旅客鉄道株式会社に委託をしますけれども、具体的な工事のＪＲとしての発注先、あるいは工事の行程管理、この辺はＪＲが責任を持って行うということになりますので。","voiceIndex":251,"id":"exchange-089"},{"speaker":"三上委員","kind":"意見","question":"全くこの金額で工事をお願いするということになるのかどうか。そうなると、別に競争入札何社ということじゃなくなってしまう。ただ、どこか名乗りを上げてきたところにくじ引きで決めるという話でしかなくなっちゃうわけですけれども、結局、そういうことで、中間マージンは東日本旅客鉄道株式会社が取りますよという理解でいいんですね。","respondent":"市岡企画財政課長","answer":"中間マージンとまでは言えないと思うんですが、先ほど来、ご説明しているとおり、鉄道敷、しかも現実に車両が走っているところを施工するわけですから、技術的も、それから施工管理技術上も、相当専門的なノウハウが必要です。","voiceIndex":253,"id":"exchange-090"},{"speaker":"三上委員","kind":"質問","question":"そうすると、最終的にその金額がどうのこうのということは、品川区としてはちゃんと聞きますよということになっているんですか、ＪＲ東日本から。","respondent":"市岡企画財政課長","answer":"内訳の中で、管理費が幾ら、それから、個々の工事に相当する、例えば基礎工が幾らだとか、けたをかけますから、けたの工事費が幾らかとかいうことは、工事協定の中で、添付文書としてつくような形になっています。","voiceIndex":255,"id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1558#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":69404,"voices":263}},{"id":"h13-20010926-6","meetingId":"h13-cm09","date":"2001年9月26日","dateIso":"2001-09-26","committee":"区民委員会","time":"午前１０時０５分～午後２時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問","question":"こっちは区民委員会なものですから、委員会の関係で、この図そのものについては特にないんですけれども、地域センターがこっちに出てきますよね。今ある地域センターをその後どうされるのか。どういう構造になっているのかなと、多分質問が出たんじゃないかと思うんだけれども、この委員会ではわからないと思うんだけれども、ちょっと説明してください。","respondent":"長田地域活動課長","answer":"池の上の構造はということなんですけれども、私も技術屋ではないものですから余りはっきりしたことは申し上げられませんけれども、今まで設計等の会議に出させている中での説明では、池が何層かになっているようです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"石田副委員長","kind":"質問","question":"１点だけいいですか。これはこの所管じゃないかもしれないんだけれども、１点だけお聞きをしたい。東京都と契約をされていますよね。３０年間でしたっけ、借地という形だったと思うんだけれども、これはもう決着をついて、その後の交渉というのはできているのかどうか、そこを、どなたか。","respondent":"長田地域活動課長","answer":"ただ、この部分につきましては下が池ということで、扱いは複合河川ということになるようです。下が河川で、その上の地上権を品川区が取得をするです。この地上権につきましては、借地権と違いますので永久の地上権ということで保有ができるというふうに説明は聞いております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"堺委員","kind":"質問","question":"現在の大崎第一出張所がある、この未整備のところで、谷山橋というんですか、橋のたもとのところに。そういった場合にビルの１室か何かにありますよね。これはどうするんですか、この大崎第一出張所というのは。目黒川の谷山橋の手前。現在のですね。わからないので聞いているんですけれども、あのビル自体は品川区のビルじゃないんですか、あれはどこかのビルのフロアを出張所として借りているのですか。","respondent":"長田地域活動課長","answer":"現在の大崎第一地域センターのビルにつきましては、４階建てでございまして、これは土地も建物もすべて区の所有になってあります。","voiceIndex":11,"id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"そうすると、１度しか通ったことがないので、中に入っていないんだけれども、わかんないでごめんなさいね、４階のそういう建物全部が大崎第一出張所で使っていたんですか。","respondent":"長田地域活動課長","answer":"１階の部分が地域センターで事務を扱っていまして、２、３、４階がそれぞれ区民集会所として利用しているという状況です。","voiceIndex":13,"id":"exchange-004"},{"speaker":"堺委員","kind":"確認","question":"それと、現在の、当面、１階が事務室で、２、３、４階が集会所とおっしゃっていましたけれども、今回はそこをそっくり荏原市場の跡地に。集会所も三つに分かれますよね。現行より広くなったような気もするんですが、その辺ちょっと確認させてください。","respondent":"長田地域活動課長","answer":"集会所につきましてはすべて１階ということで計画をしましたのもそういう部分と、それからもう一つは、住宅を建てる場合につきましては、必ず集会所を義務づけられる部分がありまして。","voiceIndex":15,"id":"exchange-005"},{"speaker":"堺委員","kind":"質問","question":"そうすると、従来より新たにできる、４００平米近く増える。あるいは、外の人はどう入ってくるんでしょうか。要するに利用される方の動線というんですか、これはどういう感じになるわけですか。それから、その住宅の人たちはどんどんまた上へ行く。要するに、年配の方が利用される場合の動線で、交通事故に遭わないようにするための流れなんかはどういうふうに考えているのでしょうか。","respondent":"長田地域活動課長","answer":"アプローチの問題ですけれども、ちょっと適当な図がなくて恐縮なんですけれども、２ページが一番わかりやすいかと思うんですけれども、まず、Ａ地区のほうにつきましては、委員ご指摘のように、高速側からのアプローチということで、それから、目黒川からどちらからでも入れます。","voiceIndex":17,"id":"exchange-006"},{"speaker":"堺委員","kind":"確認","question":"今なぜお尋ねしたかというと、この３ページ目の地図を見た場合に、Ａ地区のほうがよくわからないんですね。北側通路がある。Ａ地区ならＡ地区駐車場出入り口というのがありますけれども、集会所の出入り口がどこだったのかなと思って、それでちょっとお尋ねしたんです。中では動きは可能だろうけれども、外から来た場合にどの道から入っていくか。それだけちょっと確認しておきます。","respondent":"長田地域活動課長","answer":"そこはもう自由に出入りができるという部分と、それから東側に幅員５ｍの道路がありますけれども、こちら側のほうからも入れますし、また目黒川側からも入れる、こういう形になってあります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"堺委員","kind":"質問","question":"集会室の関係についてはわかりました。大崎第一地域センター内の事務量を想定して、現在の大崎第一地域センターにおられる職員の方々が、そっくり移動、少なくて足りるかの職員体制になってくるのですか。あるいは現在の大崎第一地域センターにおられる職員の方だけで。人員的には増やさないという、そういう形で考えているのか、その辺を。","respondent":"長田地域活動課長","answer":"人数も１３人と多いわけですけれども、基本的には今人数を増やすというようなことは区全体としても大変厳しいものがあるということで、私どものほうも現状の人数で実施をしよう、このように考えてあります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"本田委員","kind":"意見","question":"一つだけ。複合施設なわけですよね。管理といいますか、メンテナンスといいますか、それぞれ公設民営のところもあるし、各事業部管轄が違いますので、この場合の地域センターのメンテナンスや管理と他のところと、どんなふうなメンテナンスになるのかなと思うんですが、どこか１カ所に委託をしてやると思うんですが、その辺を参考までに聞かせてください。","respondent":"長田地域活動課長","answer":"ただ、今回の場合は区の住宅だけでも５００戸規模、５００にちょっと足りませんけれども、５００戸規模出てくるという中で、今回の一般質問等にも出ていましたけれども、そういった部分を一括して民間を活用できないかという話もあります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"防災センターの管理というと、区の直営になるんですか、これからのこの部分。ですから、つまり地域センターだけを管理するのではないと思うんですけれども、ちょっとそこのところを。","respondent":"長田地域活動課長","answer":"基本的には、Ｃ地区の管理をする拠点というのは１階の防災センターであり、そこでＣ地区全体の管理はするよということに紛れはないと思います。","voiceIndex":25,"id":"exchange-010"},{"speaker":"本田委員","kind":"質問","question":"そうすると、これは質疑のあったとおりですけれども、どこかに全く振るんだと思いますけれども、一元化で地域センターも管理、メンテナンスもやっていくと。そういうふうに理解していていいんですか。","respondent":"長田地域活動課長","answer":"さっき答弁を忘れました。直営でやるつもりはございません。委託で管理はお願いをする予定です。それから、夜間の管理等も含めて一緒にやっていくような形で考えてあります。","voiceIndex":27,"id":"exchange-011"},{"speaker":"堺委員","kind":"質問・要望","question":"さっきお話の中で１点確認し忘れて申しわけないんですけれども、教えていただきたいのが、現在の大崎第一地域センターについての跡地についてですが、利用はまだ未定というお話ですが、これからどういうふうに使っていくかにもよるんでしょうけれども、あそこは今ご説明いただいたように、４階建てということですから、どっちにしてもエレベーターの設置が必要になってくると思います。今ないですよね。","respondent":"長田地域活動課長","answer":"ですから、その目的に応じた改修がなされるべきだろうというふうに思ってあります。","voiceIndex":29,"id":"exchange-012"},{"speaker":"原委員","kind":"質問","question":"今の建物の話なんですけれども、あれは、できてどのぐらいたつんですか。","respondent":"長田地域活動課長","answer":"建設年月日が昭和４９年７月２２日ということになってあります。","voiceIndex":31,"id":"exchange-013"},{"speaker":"原委員","kind":"意見","question":"この間、ちょっと家族で地域センターに行ったら、非常階段が使いにくいんです。だから、もし使うとすると、余計な話で申しわけないんですけれども、どこが使うかわかりませんけれども、大幅な改修をしないと、ちょっと難しいんじゃないのかなという気がするんです。だから、どこの課でどこの事業部が使うかは別としても、その辺は費用対効果をよく考えて検討してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-014"},{"speaker":"原委員","kind":"確認","question":"一つだけちょっと確認を。今回品川保健所とか保健センターも参加されましたですね。そういうことは、医療関係の部分もそこで補ってくれるということですよね。","respondent":"辻田防災課長","answer":"現在、医療関係の方々につきましては、総合防災訓練のほうで実施している形で、消防署の救急関係と一緒にやっているという、将来的には考えなければならない課題だと思いますけれども、今回は医療関係、医師会等との連携の中でこれを実施したのではない。","voiceIndex":40,"id":"exchange-015"},{"speaker":"原委員","kind":"意見","question":"ということは、医療も含めての訓練をしたということなのかどうか。","respondent":"辻田防災課長","answer":"具体的な治療の前に、まずトリアージ、この前、一般質問でもお答えしましたけれども、トリアージの訓練をするということを今回一つの目玉にいたしました。それから、包帯をするとか、診察をするとか、というような具体的な行動につきましては、今回は省略したです。","voiceIndex":42,"id":"exchange-016"},{"speaker":"本田委員","kind":"質問","question":"危機管理という点では、予想しないような事態というものが発生すると。危機管理という点では、新しいそういうもののとらえ方というのも自治体の中でも必要な時代になってきたのかなというふうに思っているんですが、そこの関係とか、システム関係とか、その辺は、今回９月５日ですから従来の訓練だと思いますけれども、そういう危機管理についての多彩な問題というのは、どんなふうにとらえられていましたか。","respondent":"辻田防災課長","answer":"ですから、実際に起きますと、地域防災計画とは関係なく、そのときに合った適切な対応というのが常に求められているので、その辺が一人ひとりの防災課職員、または区職員の危機管理の意識の一番のポイントではないのかなというふうに考えてあります。","voiceIndex":44,"id":"exchange-017"},{"speaker":"本田委員","kind":"意見","question":"交通機関に対する万一の事故とか、今度は沈埋トンネル問題とか取り上げてきますよね。けれども、そんなことから新たなそういう大変困った問題だなと、大変不安な問題ではありますけれども、区職員としてのこういう危機管理に対する対応というものがやはり検討するときがやってきたんだなと考えています。答弁は要りません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-018"},{"speaker":"金高委員","kind":"質問","question":"この間のニューヨークの惨事があったわけですけれども、あのときに、消防隊の人たちがマスクをしていたのをよくテレビで見たんですけれども、あのマスクというのはいわゆる粉じんとか、そういうにおいとか、あれは簡易マスクだと思うんですけれども、そういうのは例えば、今、本田委員のやりとりの危機管理とかという形において、例えば家が倒壊した直後、よく、古い家を動かすと。","respondent":"辻田防災課長","answer":"ただ、大規模にああいう形で発生しますと、簡易なマスク的なものから、こういう両方に、昔ありました防毒マスクみたいなものも含めて、ニューヨークでは相当売れたというようなことも聞きまして。","voiceIndex":47,"id":"exchange-019"},{"speaker":"金高委員","kind":"質問","question":"そういう中で、今の話ですと、なくても作業できるように、あるいは救助活動に従事していくというふうなことですけれども、例えば今現在、区のほうで万が一そういうのがある場合に、従事する職員の方々が装具を借りるというような状況で参加しているわけですけれども、ある程度の量がぽんと確保されていて、何かのときには、それをとりあえず簡易であっても、目と呼吸器ですね。","respondent":"辻田防災課長","answer":"ただ、決して高価なものではありませんし、そういうようなものをある程度これからは考えていくことが必要かなというふうに考えております。","voiceIndex":49,"id":"exchange-020"},{"speaker":"金高委員","kind":"質問","question":"昨日のちょっとテレビを見ていたら、核シェルターも掘り出したという話があったぐらいな状況なものですから、ささいなことであっても住民の方の不安を少しでも取り除くような方法がとれるかどうか、最後にそれだけ聞かせてください。","respondent":"辻田防災課長","answer":"ただ難しいのは、変にいろいろこちらのほうで勧めますと、不安をあおるというような部分もありますので、その辺は慎重にしていかなければならないかなです。ただ、情報提供につきましては、私どものほうでいつでも対応できるような体制を持ってやっていきたいと考えています。","voiceIndex":51,"id":"exchange-021"},{"speaker":"堺委員","kind":"質問","question":"そうしますと、この小学校が６校で、中学校が６校、これについては教育委員会の事務局を通じて、今度こういうのをやるんだけれども、参加してくれませんか、あるいはどこの学校に行っていいですかとか、その辺の調整というんですか、どういうきっかけというのかわかりませんが、突然行ったわけではなくて、事前の下打ち合わせがあって、場所が決まって、そこに派遣するということになると思うんですけれども。","respondent":"辻田防災課長","answer":"どこの学校に集まるかというのは、大体地域的な部分で、どこの職員がどこに集まると決めてあります。ですから、あなたはここに集まりますよということで知らせて、そしてそこに集まるような形で実施しております。","voiceIndex":55,"id":"exchange-022"},{"speaker":"堺委員","kind":"意見","question":"だから、学校に行った場合、例えば参集場所がどこに書いてある、校門はあいているか、あいていないのか、あるいは学校で学校長または教頭を中心として、学校の具体的な配置、備蓄品の有無、身の回り、あるいは現場に直接生徒を誘導するとかしないとか、そういうのは具体的な内容の訓練をやったのかどうかという、そこがもう一つ。","respondent":"辻田防災課長","answer":"それで、向こうに行きましたら、あらかじめ私どものほうは学校の校長先生、教頭先生に、来ましたらこういう形で対応していただきたいということでお願いしています。備蓄倉庫を確認、それから井戸であるとか便槽、そういうもののあり場所の確認をする。","voiceIndex":59,"id":"exchange-023"},{"speaker":"堺委員","kind":"確認","question":"そうすると、全体で１２校分散していて、指定されたときに指定された学校に行けるかどうか行って、終わると、また西大井広場に全員集合してきたということで、学校ではそれぞれの場所の確認というだけですね、当然今言っていることは。","respondent":"辻田防災課長","answer":"全部の学校すべてそういう形でやっておりますので、それを１回きちんとやりまして、その後また訓練を深めていくというような形で今後そういうような訓練も実施していきたいなと考えています。","voiceIndex":61,"id":"exchange-024"},{"speaker":"堺委員","kind":"質問","question":"最後に。そんなことないのかもしれませんが、そうすると、この職員が学校へ行って、大体１０時ぐらいまで今のお話ですとおられたようですから、その学校以外の地域の、避難所連絡会議のそういう人たちの責任者みたいな人たちにも来てもらって、そこでまた一緒に短時間でもミーティングできるという日常的な触れ合い、そんなのも可能ならどうかなと思ってきたんですけれども。その辺はざっくばらんに。","respondent":"辻田防災課長","answer":"今後、そういうようなことも入れながら訓練していきたいなというふうに考えております。大変申しわけないんですけれども、ちょっと忘れておりましたのは、参集職員は全部徒歩ないし自転車で集まることになっておりまして、それなりに時間がかかるわけですね。","voiceIndex":63,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"仮定の話なんですけれども、新米というか、わかりませんので、例えば区長が負傷、助役も負傷、防災課長も負傷で、６キロ圏内の幹部職員が全部負傷で、負傷していない幹部職員が電車が交通機関が寸断されていて来れませんとなった場合に、指揮系統というのは、ちゃんと確立されているんでしょうか。","respondent":"辻田防災課長","answer":"そういう中で、各部それぞれが部の役割をもって、訓練を実施しておりまして、それなので、決して万全とは言えない状況ですけれども、そういう悲惨な状況の中では、係長ないし職員が当面の対応をしなくちゃならないという、そういう認識は持ってあります。","voiceIndex":65,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"職員の皆さんの中にも家族がいらっしゃると思うんですけれども、家族も負傷している場合に、役所のほうに来るか、負傷した家族の面倒を見るか、どちらを優先させるのかという指導みたいなものはあるんですか。","respondent":"辻田防災課長","answer":"それは、特に地域防災計画には書かれていないと思いますけれども、いわゆる人道上の問題として、まず自分の身を守る、これが最初です。そうしなければ次の行動に移せませんので。それから、次に家族の安否を確認し、そして負傷者がいれば、それに対応する。","voiceIndex":67,"id":"exchange-027"},{"speaker":"石田副委員長","kind":"確認","question":"一つだけ確認で教えてください。先ほどトリアージを行ったというお話があったんだけれども、保健所、保健センター、医師が参加したと思うんですが、何名ぐらい医師が参加して、どのようなトリアージを行ったのか、それだけちょっと教えてください。","respondent":"辻田防災課長","answer":"保健所は５名の方ですけれども、医師としては、現場で実施したのは１名。〔「両方合わせて」と呼ぶ者あり〕そうです。それから、職員がそこに補助的な形で３人ばかりついたという形で実施をしております。","voiceIndex":69,"id":"exchange-028"},{"speaker":"石田副委員長","kind":"質問","question":"トリアージ対応はやったということで理解していいんですか。","respondent":"辻田防災課長","answer":"そうです。","voiceIndex":75,"id":"exchange-029"},{"speaker":"菊地委員","kind":"質問","question":"どちらについても中小零細企業には本当に助かるものだと思うんですけれども、年末対策事業資金についてお聞きしたいんですけれども、今、貸付で３４０件余りということなんですけれども、区が紹介された範囲、最終的に紹介された範囲と、ここで開きがあると思うんですけれども、ここでの区が紹介したときに審査をした部分と、実際に金融機関に行ったときの断られる理由というか。その辺がわかれば。","respondent":"市川産業振興課長","answer":"昨年の実績のあっせん件数ですが、４６０件、１９億４,０００万円のあっせんをしています。実績といたしましては、先ほど申し上げた３４０件、１３億３,０００万円、件数にしまして、実行率が約７４％、金額にいたしますと６９％という実行率になります。","voiceIndex":83,"id":"exchange-030"},{"speaker":"菊地委員","kind":"質問","question":"確かに厳しい状況の中で、実際には生活費になってしまったりとか、実際問題として、さらに今年に入って中小零細企業で言うとさらに厳しい状況が生まれているというのは、まちの中に入るとよく聞く話なんですけれども、据え置き期間の１２カ月というのをさらに延長するような形というのはとれないものなんでしょうか。","respondent":"市川産業振興課長","answer":"５００万円ぐらいの融資に当たりまして据え置き期間を延ばすことが、利用者の側に果たして全面的にいいことかどうかというのは、私どもの経験則からすると、二手に分かれてしまうんですね。","voiceIndex":85,"id":"exchange-031"},{"speaker":"原委員","kind":"質問・要望","question":"そんな意味では、昨年同様にかかわらず信用保証料の負担については、さらにいろんな形でお願いしたいと思います。それで、今まで何年か続けていた。保証額が総額どのくらいになっていて、例えば返済不能になっていて、それも回収できないというのが、要するにその現状をちょっと教えていただきたいと思います。どうなんですか。","respondent":"市川産業振興課長","answer":"今、申し上げた中で、平成１０年の４０億というのがこれまで区の実施した中で飛び抜けてすごい数字が出てしまったわけですけれども、これはちょうど当時信用保証の安定化保証枠という特別枠が信用保証制度で出た時期とちょうど符合一致しておりまして。","voiceIndex":87,"id":"exchange-032"},{"speaker":"原委員","kind":"質問・要望","question":"先ほどの数字だけをトータルしても、約８５億ぐらいのそれぞれの規模の中で、中小企業が一生懸命に返して努力されている。今後も引き続いて努力していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-033"},{"speaker":"本田委員","kind":"質問","question":"一つだけお尋ねします。この事業が昨年どういうふうに使われたかといいますか、実際にどういうふうに利用されたのか。ＰＲなんですけど品川の産業ニュース、今なかなか読みやすい編集をされていて大変好評でございましたけれども、これはどういう意図で区内の商工業者の方々のほうに郵送するようになっているのでしょうか。","respondent":"市川産業振興課長","answer":"各金融機関の窓口に、この緊急資金の個別のチラシを置かせていただきまして、その他の品川・荏原の青色申告会を通じて事業所にチラシを配布する、このような、なるべく各事業者の方に情報が届くようなＰＲを進めてまいったところです。","voiceIndex":90,"id":"exchange-034"},{"speaker":"本田委員","kind":"質問・要望","question":"先般、ちょっとある事業者から相談を受けたんですけれども、ある商店街の中で事務所を構えている、貿易関係の仕事をやっている方なんですけれども、この品川の産業ニュースを読みたいと思って、そこには入っていないんですね。ですから、積極的にそういう方にもニュースをお届けして、いろいろな情報を発信してご利用いただくという姿勢が必要だと思うんですけれども、どういうふうに思うんでしょうか。","respondent":"市川産業振興課長","answer":"なかなかそうは言ってもまだ漏れる事業所があることはよくございまして、お尋ねのような電話をいただいたときに、カードを新規作成をしていくような対応をとっておりますが、何かのちょっと不具合でそのような事態が起きたわけですので。","voiceIndex":92,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"協定金利が０.２％調整してくださったということに、あらためて敬意を表したいと思います。それで、質問なんですけれども、まず１点は、保証協会の事故率が少ないというのは、保証協会の代弁差益が少ないということなんでしょうか。それぞれ平成１２年度が７４％という、これは平成１１年度よりも下がっているのでしょうか。","respondent":"市川産業振興課長","answer":"それと、２番目のお尋ねは、実行高の有無にかかわらず、さっき原委員のお尋ねに、この４年間の推移を説明させていただきましたけれども、実際の融資実行高には大分ばらつきがありますが、融資実行率だけは年々低くなってきてあります。というのは、下がってきております。","voiceIndex":94,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"簡単でいいんですけれども、融資の実行、産業ニュースを見て、融資を受けたい方が、課長がいらっしゃるところに初めて伺いますよね。そうすると、紹介状をいただくまでの、簡単でいいんですが段取りを。伺いますよね。","respondent":"市川産業振興課長","answer":"私どもに来られるお客さんは２通りあります。金融機関を通して、金融機関で何らかの事前の接触を持たれて来られる方と、それから丸っきり初めてですということで私どものカウンターに来られる方がいらっしゃいます。","voiceIndex":96,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"今出た中小企業診断士が、まさに相談してくれる。５００万円なら５００万円、いいですよと書いてくださいますよね。ここでなんですけれども、区が直接相談を受けて、紹介状というか、何でそこで中小企業診断士が入って、融資のオーケーを出すのか。融資のオーケー、紹介状を出すか出さないかを中小企業診断士がやるのですか。","respondent":"市川産業振興課長","answer":"そうしていただくからには、なるべく有効な事業資金の使い方をしていただきたい、そのためのアドバイスをする、これが私どもの相談員が利用なさるお客様にいろいろなお話を聞いた上で必要なアドバイス、例えば運転資金を借りるにしても、在庫管理はどのようにしているんですかと。","voiceIndex":98,"id":"exchange-038"},{"speaker":"金高委員","kind":"質問・要望","question":"それは通常の区のほうを外した融資の話ですよね。区を通して行くと、保証料の部分と、それから区の利子補給も入る、わかるんですけれども、例えば逆に直接保証協会に行って、保証協会の方と話をつけて、それだったらば、何とかなりますよといったときに、それを今度区のほうに持ってきて、区のほうにいただきたいんですけれども、どうですかという、審査ができるのですか。","respondent":"市川産業振興課長","answer":"これは事業者と金融機関のやはり関係と申しましょうか、そういう事実があります。ただ、それが私どもいいとか悪いとか、勧めるとか勧めないとか、またそれはちょっと別の話で、ただ、実際の取り引きとか資金調達する場面では、結構日常化している場面ではないかと思います。","voiceIndex":102,"id":"exchange-039"},{"speaker":"金高委員","kind":"確認","question":"再確認だけ、そうすると、そういうのがあった場合には、区のほうの要するに利子補給とか、保証料の補助とか、そういうのは可能だというふうに解釈してよろしいですか。","respondent":"市川産業振興課長","answer":"もともと区の制度融資をお使いになるということで、お話がこうやって持って来られれば、これは後先逆になっても、私どもは要するに、先に話をつけたかつけていないかというのは、私どものカウンターの中から見えない話ですので、それはご心配要らないと思います。","voiceIndex":104,"id":"exchange-040"},{"speaker":"堺委員","kind":"質問・要望","question":"１点だけ。参考までに教えていただきたいのですが、これは昨年の実績で、３４０件で１３億３,０００万円という形ですね。あるいは、資金の使途として運転資金または設備資金（併用可）となっていますけれども、これの内訳、この辺は明確に把握しているんですか。把握しておられれば、全体の状況を知るというか、そういう上で参考に教えていただければ。","respondent":"市川産業振興課長","answer":"飲食業が１０％ぐらい、あと、その他と。大体大まかはこのぐらいの率で、この率は大体毎年変わってございません。それと、資金の使い道ですけれども、圧倒的に運転資金です。もう恐らく９割を超す使用目的は運転資金です。","voiceIndex":106,"id":"exchange-041"},{"speaker":"堺委員","kind":"質問","question":"資金の使途については、多分そうだろうなと運転資金。目的別にだと。多分安定するためのそういう資金。ただ、これは併用可というふうになっておりますけれども、年末なんか併用可でもやっぱり全体的に運転資金ということの中身というか、その辺はどうなんですか。併用で申請してくる人はいないということですか。","respondent":"市川産業振興課長","answer":"つまり、１,０００万円から１,５００万円ぐらいの何か設備投資をしたいというときに、ちょうど年末のときなので、この緊急資金があるので、まず安いこれを使って、足りない分を通常の資金で使うとか、それで、こうは書いてあるんですが、５００万円の中で設備もやって。","voiceIndex":108,"id":"exchange-042"},{"speaker":"堺委員","kind":"質問","question":"年間の利用内訳で、製造業で２８％ですか、あとは建設業その他の内訳がなかったんですが、どの程度かつかんでおられますか。","respondent":"市川産業振興課長","answer":"大体順位で言うと、建設業は飲食業の次に位置する、第５番目ぐらいのポジションです。ただ、飲食業がさっき１０％程度と申し上げましたけれども、そんなに率は変わらないぐらいです。大体そこで数字を足し合わせるとあれなんですが、ほとんど網羅されてしまう。","voiceIndex":110,"id":"exchange-043"},{"speaker":"本田委員","kind":"質問","question":"先ほど換気所の件については報告、説明をいただきまして、また地元説明会が始まってまいりますので、今日は再質問はいたしません。一応先ほどの説明で、言っていたとおりだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-044"},{"speaker":"菊地委員","kind":"質問","question":"前回でしたか、ご説明いただいたときに、９月１７日の辺でもって、区のほうから意見を上げていくというのがありましたけれども、その日程関係をちょっと教えていただけますか。","respondent":"金井環境課長","answer":"ですから、基本的に私どものほうで今後の予定として、１０月中ぐらいに区長の意見の提出時期が来るかなと。","voiceIndex":120,"id":"exchange-045"},{"speaker":"菊地委員","kind":"確認","question":"それで、もし上げるとなれば、請願で出てきた内容だけではなくて、それは学習会を通じて得た知識を含めて、精査をするなり何なりしたいということで確認をさせたわけですので、それで、意見書を上げるとなったときの期間の問題なんですけれども、首相あてに請願を安易に上げるのは失礼じゃないかという議論もありましたし、期間いつごろ実際に上げていくのかという、意見書を上げるとなれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-046"},{"speaker":"南委員長","kind":"確認","question":"ですから、その時期をいつというふうに一応一定のめどを立てて、そこまでに頑張って学習もし、意見書を出していける方向で勉強していこうというふうな、そういうことだったというふうに思うんですけれども、できるだけ、私としては時間を長く先延ばしにしないで、国際的な会議の中身ですから、どの辺が適切なのかというのは、ちょっとまだはかれないんですけれども、できたら一番よかったのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-047"},{"speaker":"本田委員","kind":"提案","question":"アメリカの国も必ずしも全くだめということではないというふうになってきているというような動きなどを見ながら、私の要望としましては、次の区民委員会に、この議定書問題について議論する議題としてぜひ提案していただいて、それまでに今日出された資料に目を通しておいていただきまして、それぞれ会派の中でも論議し合って、一定の方向を出しながらさらに話を前に進めて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-048"},{"speaker":"原委員","kind":"意見","question":"ただいま本田委員からもお話がありましたけれども、今日、よく資料を持ち帰って読ませていただいて、いろんな国外の要求、国内の要求、あるでしょうけれども、それらも含めて、特にこの委員会の中では、今回の資料を提出していただきましたから、そういう中で目を通して、どういうものか、あるいはどんな状況になるかを含めて到達するように、間に合うかどうかは別として。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-049"},{"speaker":"金高委員","kind":"質問","question":"夜間の態勢が３５名で、昼間の本部態勢９９名という今の報告だったんですけれども、そういうような方々は、服装なんですけれども、このままちょっと通常業務に戻ったそうですけれども、いろんな各部署にそれぞれ分担していて、これだけの方々が水防本部というところから、通常仕事をやりながらということですけど、いわゆる作業服というんですか、防災服。","respondent":"辻田防災課長","answer":"ただ、この日は特にこのほかに９９名以外にも勤務時間中であったということもありますので、防災服を着て、いつでも出動できる、応援が組める態勢ということで、もちろん防災課もそうですけれども、土木関係を中心に、事前に防災服を着用しながら執務をしたという状況です。","voiceIndex":138,"id":"exchange-050"},{"speaker":"本田委員","kind":"質問","question":"それで、テレビなどでも１５号については予報がどんどん流れるとか、そういう形で報道されておりましたので、非常に東京を直撃という格好で、皆さん警戒をしながら対応したんだと思うんですけれども、防災無線が聞きにくいということ、それから、品川ケーブルに対しても、目黒川とか立会川とか、品川の区域の状況、東京にも警報が出ているわけですから、品川はどうなっているだろうかと。","respondent":"辻田防災課長","answer":"その辺のことは検討していきたいなと、もちろん防災無線の調整等をしまして、それから音量を上げることができます。本当の災害のときは、音量を上げて放送するということを予定しておりますけれども、そういうことも今後考えなければならない。","voiceIndex":140,"id":"exchange-051"},{"speaker":"本田委員","kind":"質問・要望","question":"ぜひケーブルテレビ、テロップでもいいし、一つの品川速報で、例えば目黒川の水位のところを画面を映しながら、どういう状況になっているというようなものが、皆さんのところに入るとか、そういう品川の実情に即した、例えば集中豪雨も、東京全部が降って品川も降っているというのでなくて、何年か前にあったように、もうほかは晴れているのに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-052"},{"speaker":"原委員","kind":"質問","question":"うちにも電話があって、何を言っているかわからない。それがビルに反響しちゃって余計わからないというお話も来て、すぐにというわけにはいかないですけれども、今後の中でもうちょっと、あれは町会長あるいは地域の各町会のところには有線か何かで行っているのでしょうか。","respondent":"辻田防災課長","answer":"そういうことで、補完の方法をいろんな形で考えていければと思います。","voiceIndex":143,"id":"exchange-053","title":"町会・自治会支援"},{"speaker":"原委員","kind":"質問・要望","question":"どうもありがとうあります。今後も含めて、検討していただきたいと思いますし、それからもう一つ、先ほど目黒川が１０時に警戒水位になってきたというようなお話でしたね。それは今回使われたのか、使われないのか、それともう一つは、どこの時点でそれを使うような形にとられているのか、ちょっとそこのところを。","respondent":"辻田防災課長","answer":"だから、それの時間が長くなればなるほど、中にたまる量が多くなるです。下流のほうの水量の調整をしているです。〔「今回は５万ｔ」と呼ぶ者あり〕大体５万ｔ入ったということです。","voiceIndex":145,"id":"exchange-054"},{"speaker":"菊地委員","kind":"質問","question":"一つだけちょっとお聞きしておきたいんです。産業振興マスタープランのほうなんですけれども、今回の委員会で出るのかなと思っていたんですけれども、ちょっといまだに出ていないんですけれども、経過をお願いします。","respondent":"市川産業振興課長","answer":"〔「時期的にまだわかりませんか」と呼ぶ者あり〕 今、最終校正の一歩手前のところでとまっていますので、最終的にゴーサインを出してから１週間ぐらいということですので、なるべく早くお届けするようにいたします。","voiceIndex":148,"id":"exchange-055"},{"speaker":"石田副委員長","kind":"質問","question":"１点だけすみません。私はＩＳＯ１４００１のことはよくわからないのですが、いろいろ大きい企業ですと、非常に細かく棚まであって、紙まで全部分けているとか、いろいろやっていますね。ああいうすごい厳しい、はたから見ると厳しそうな大手の企業なんかのビルに行くとなっているんですけれども、そこまで品川区が段階的にやっていこうという将来お考えなんですか。","respondent":"宍戸ＩＳＯ担当課長","answer":"このＩＳＯの仕組みの一つは、記録をきちっととって、外部の説明や何かにきちっと説明できるようにするということが、実際にそれの関係で、今、副委員長のおっしゃったようなことをなさっているんだと思います。","voiceIndex":153,"id":"exchange-056"},{"speaker":"原委員","kind":"意見","question":"それで、そういう視察項目を見ると、彦根で４項目、その下の黒壁は、これは一つにまとめられますし、そういうような形で、くくっていって、それぞれに分けて、その訪問してきたところを出してもらって、あとは、正副でまとめられた段階で、ほかの委員からの参考意見を加味するというふうにされれば、割合目標が決まっていて、まとめやすいんじゃないか。そう思うんですが、ほかの方のご意見は。","respondent":"南委員長","answer":"正副でちょっと打ち合わせしたときがおそくて、貴重なご意見だというふうに受けとめます。いいでしょうか、そういう方法で、１人一つずつ分担をしていただいて、報告書として。最終的な責任は、正副にあるわけですけれども。","voiceIndex":161,"id":"exchange-057"},{"speaker":"原委員","kind":"意見","question":"それでいいと思うし、それから、ほかの人の意見がそこに入れられないというのではなくて、やっぱり例えば私の受けたところでも、感じ方が、考え方が違う場面もあります。そういうところは１回やっぱり出していただいて、まとまって、ここにはこういうものがあった、こういうふうに感じたという。〔「後で検討会をするという」と呼ぶ者あり〕それを入れておけば、委員の中で自由に広がると思う。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-058"},{"speaker":"石田副委員長","kind":"意見","question":"ここに書いてある項目がありますね。彦根が１、２、３、それで、長浜はこれは１、２は一つにしよう。ここの項目の中で私はこれをやりたいというのを先に言っていただければ、我々の業界では玉鳥というんですが、そういう項目をどうぞお一人ずつとっていただければと思うんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":167,"id":"exchange-059"},{"speaker":"原委員","kind":"意見","question":"それかあるいはくじ引きじゃないけれども、どうしても、それは好きなところでやるほうもやりやすいかもしれませんけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":169,"id":"exchange-060"},{"speaker":"石田副委員長","kind":"質問","question":"私から勝手に言っていいですか。ここの懇談会のまとめをもし正副でやれということであれば、正副で必ず足助を入れてほしいな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-061"},{"speaker":"本田委員","kind":"質問","question":"きょうは、京都と言ったもんですから、ある程度環境問題で、地球環境のことで書かなくちゃいけないんですが。言ってくれましたので、助かりました。ちょっと体調上の問題がありますので、視察は不参加しますので、この報告書づくりにはお役に立てないで大変申しわけないんですけれども。〔「お知恵を拝借に参りますので、そのときには」と呼ぶ者あり〕資料には目を通しておきますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-062"},{"speaker":"石田副委員長","kind":"質問","question":"黒壁と東大阪ですから、ものづくり。懇談会はこちらでまとめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2308#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":52576,"voices":189}},{"id":"h13-20010926-7","meetingId":"h13-cm09","date":"2001年9月26日","dateIso":"2001-09-26","committee":"厚生委員会","time":"午前１０時０６分～午後 ４時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"第１に、効果のところで犯罪に対する一定の抑止効果が期待できるとなっていますけれども、これはこういった施設にこういった装置が設置されているということを広報したりする、そしてまたこういうことがあるんだから犯罪を犯したら捕まってしまうなというようなことで抑止効果を発生させるということなんでしょうか。そこがどうなっているのかお伺いします。","respondent":"谷田部児童課長","answer":"ですから、よく民間の警備会社で各家庭に警備会社の表示をしているというのも一種の抑止効果をねらっている部分がありますので、私ども施設の管理上、例えば目立つところにこういう装置のステッカーを張るですとか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"船波委員","kind":"質問","question":"わかりました。もう一つ。補助対象外の施設は別途安全策を構築するということですけれど、どういったことが考えられているのか、現時点でのプランをお伺いします。","respondent":"谷田部児童課長","answer":"ですから、この装置とは、即応という部分ではワンクッション入ることによって多少遅くなるかもしれませんが、万全な体制で私ども対応はしていきたいというふうに思ってあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鶴副委員長","kind":"質問","question":"その５０名なら５０名、指揮命令系統というのがあって、指示なしには消防署だって動かないじゃないですか。指示がなければ消さない、そういう仕組みになっているじゃないですか。だから、この５０名駆けつけたときでも指令がないと、いろいろな指示がないと入っていかない。どういうふうになっているのかなと。Ａという学校に大変な緊急事態が発生して現場に駆けつけたって、どういう指揮を取るんでしょう。","respondent":"谷田部児童課長","answer":"ですから、仮に何かが発生してこの通報装置が作動した場合、警察官が多数駆けつけるわけですが、当然館長、園長のほうと連携をとりながら、どこどこの場所で事件が発生したとか、そういうようなことは当然警察官と館長、園長を含めて。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鶴副委員長","kind":"意見","question":"そうすると、その非常事態という判断の基準というのは、どの程度のものだったら非常事態というふうに判断して館長とか園長がしかるべきところに、最初は警備会社に通報するのかということですね。その非常事態という判断の基準ですよ。","respondent":"谷田部児童課長","answer":"ですから、その辺の予見をどの時点で見定めるか、これは非常に難しいと思いますけれども、私ども日常の館内の安全管理の面で、児童センターを長く運営していますので、その辺は十分対応ができるというふうに思ってあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鶴副委員長","kind":"質問","question":"火災でもないほうがいい。瞬時にして逮捕されるのだと。だから、そこらあたりのどこまで普及徹底、今回の１１０番制度に伴っての対応措置というのは、こういうところまで厳しい措置がとられるのですよということをできる限り周知徹底をしてもらったほうがいいのではないかというふうに、抑止効果をねらうならばそのぐらいの周知徹底は必要ではないかというふうに私は考えるのですが、いかがでしょうか。","respondent":"谷田部児童課長","answer":"周知徹底という部分ですけれども、先ほど船波委員のご質問にもお答えしましたとおり、ここの施設にはこのような装置が設置されているというような部分でのＰＲ、それから実際訓練で、設置した後、警視庁との合意が得られたら、試しに一回やってみて。","voiceIndex":13,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"そういうふうなことはお考えにならなかったのでしょうかということをお伺いしたいのと、それから池田小学校の事件は犯人は全く１人でしたので、いわゆる格闘ができるプロの人が１人でもいれば、それを事前に抑えることができたわけですから、そういうことを考えていくと、もちろん５０名というのはありがたいのですけれども、警視庁の５０名という枠にとらわれて施設の具体的な安全管理のうえでの規模とか。","respondent":"谷田部児童課長","answer":"いわゆるこのシステムが使えないというふうな結論に至りまして、それでは別な方法は何かというところで同様のシステムが、いわゆる民間の警備会社で用意しているもの。","voiceIndex":15,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"例えば初動態勢が１０名でもいいですよとか、５人でもいいですよとか、こちらのほうから逆に伝えた中で警視庁からいい回答を引き出したほうが、こういう学童保育クラブの子供たちの安全とか、それから児童学園への対応とか、相当変わってくる可能性があるんじゃないですかということをお伺いしていますので、もう一度ご答弁をお願いいたします。","respondent":"谷田部児童課長","answer":"これは施設の規模ですとか、面積、それから建物の構造、そういったものを事前に警視庁のほうに届け出をして承認を受けるようになってありますので、その時点で通報があった場合に警察官何人ぐらいで駆けつけるかとか、それから最寄りの警察署だとか交番ですとか。","voiceIndex":17,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"警視庁のいろんな体制上の問題でそうなっているのだったらば、これは区のほうからどんどん指摘をしていく必要があるし、何も５０名という頭があるから動かないのではなくて、池田小学校の事件は１人の犯人だったわけですから、それを考えていくと、初動のときに例えば２人でも３人でも本当は駆けつけてくださったほうが恐らく安全確保には十分な機能を果たすと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"嶋委員","kind":"質問","question":"仕組みの中に、設置場所を今考えていらっしゃるということなのですが、これを見ますと、事務室とほか１室とありますが、これは基本的に考えてこのまま１施設２カ所という認識でよろしいのか、それとあと先ほどもいろいろ施設の大小が出ておりますが、この施設の大小に係ってこの設置場所が数が減ったりふえたりとかするのかどうか、ちょっとお聞きをいたします。","respondent":"谷田部児童課長","answer":"基本的には１施設に２カ所の非常ボタンを設置するというのが一つの仕組みになっています。","voiceIndex":20,"id":"exchange-009"},{"speaker":"嶋委員","kind":"質問","question":"そうお聞きをして安心をいたしました。まして、その大小があると思いますので、ぜひ安全対策で本当に子供たちが安心して学校生活また保育園とかで生活ができるようにお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-010"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから押しやすく押しにくい場所を探さなきゃいけないよというような判断になろうかと思うんだけど、その辺はどんなふうに考えていらっしゃるのかということと、それからここには保育園、児童センター等になっているんですけれど、福祉施設がいろいろ西大井福祉園、区直接じゃないけれども、運営主体が民間になっている、そういったところなんかの対応というのは。","respondent":"谷田部児童課長、日下部障害者福祉課長","answer":"そのときに確認のために警視庁のほうから逆発信を使いまして、その発生場所のほうに電話が入ります。そのときにもし誤報だったら電話を取って、警視庁からの逆信に対して、今のは間違いでしたというような対応もまず１点とれると。その他の福祉施設での対応についてのお尋ねですけれども、今回のこの学校１１０番の設置の対象といいますか、これはどうしても対象者の体力がまだ小さいとか、あるいは防御体制が必ずしも十分でないと、そういった学校でいえば小中学校。","voiceIndex":26,"id":"exchange-011"},{"speaker":"船波委員","kind":"質問","question":"９月１８日に住民説明会をしたということですけれども、これはどういったところへ呼びかけて参加を募ったのでしょうか。","respondent":"谷田部児童課長","answer":"それから道路を挟んで反対側が洌崎町会というのがあります。それから目黒川を挟んで櫻心会という町会もあります。それから品川第２地域センターの管轄になりますが、東親会という町会、いわゆる４町会の町会長を通じて回覧をしたというのが私どもの住民説明会へ周知した範囲です。","voiceIndex":33,"id":"exchange-012"},{"speaker":"船波委員","kind":"質問","question":"わかりました。それから、そうやって呼びかけて来ていただいた方々の懸念材料としてはホームレス対策ということがさっきありましたけれども、それ以外にどんなことがあったのでしょうか。この件についてはほぼ了承されたというご説明でしたけれど、了承されないというか、疑問を呈されたというようなことは、ホームレス対策以外にどんなことがあったのかを伺います。","respondent":"谷田部児童課長","answer":"そういった細かい要望等もありましたので、それはそれで個別対応で今後そういった方たちとは詰めていくというようなことになってあります。","voiceIndex":35,"id":"exchange-013"},{"speaker":"船波委員","kind":"質問","question":"わかりました。土の部分と浸透性にした部分、どういう理由でそういうふうに分けたのか、その辺をお伺いします。","respondent":"谷田部児童課長","answer":"先ほどの説明で、通路として利用されている方が比較的多いというのが管理工事課のほうの事前の調査でわかりましたので、その方々が通行しやすい材質を考えなければならないという部分で、その通行する部分を透水性の舗装、そちらのほうで整備すると。","voiceIndex":37,"id":"exchange-014"},{"speaker":"鶴副委員長","kind":"質問","question":"ちょっと気になったことだけをお伺いしておきたいんですけれども、桜の木を含めて、あそこの樹木は何本ありますかね。それから、フェンスはまた新たに取り替えるのかどうかです。そこのところをちょっと答えていただけませんか。","respondent":"谷田部児童課長","answer":"ですからしばらく木登りできるまでというと、５年も１０年もかかってしまうのでは木登りはできないなというふうになりますので、現存する大木が２本ありますので、そちらを利用して木登りができる。","voiceIndex":39,"id":"exchange-015"},{"speaker":"鶴副委員長","kind":"質問","question":"木登りしたら落ちる場合もありますね。それで私たちが小さいころは、高いカキの木に登ってカキを取ったり、森に行って野鳥をとるために天井罠かけたりというふうな楽しい思い出があるわけです。桜の木でも滑らないように、例えば素手で登るのがおもしろいんですけれども。今お話聞きましたら、高木で４４本、低木で２９９本、ここにはどんな鳥が来ているでしょうか。","respondent":"谷田部児童課長","answer":"鳥を観察した結果はございませんので、どんな鳥が来ているかはわかりませんが、私が行ったときにはハトとスズメが公園の中にいたです。","voiceIndex":43,"id":"exchange-016"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"小鳥のさえずりを聞こう。カラスの鳴き声だけじゃなくて、その条件を整えることによって小鳥はそこへ来るのですよ。車椅子に乗ったままですよ。いや、時間がなくて言及しなかったかもしれませんが、そういうふうなせっかく多くの子供たちに遊んでもらおうというんだったら、ハンディを持った子供たちもここで遊べる冒険公園にしてもらえないかという希望を私は持っているんですが、その点はいかがでしょうか。","respondent":"谷田部児童課長","answer":"それからまた、私ども遊びを指導する者も必要に応じて配置しますので、その中で介助しながら遊べるというようなことも考えていきたいというふうに思ってあります。","voiceIndex":45,"id":"exchange-017"},{"speaker":"鶴副委員長","kind":"質問","question":"車椅子で遊べる泥んこ遊びのできる施設というのを、大々的なものではありませんが、文献でもいいですからごらんになったことはありますか。","respondent":"谷田部児童課長","answer":"ちょっと私どもは見たことはございません。","voiceIndex":47,"id":"exchange-018"},{"speaker":"鶴副委員長","kind":"提案","question":"だから議員が提案したことについては、それぞれ傾聴に値するという考え方に立っていただいて、いろいろ文献を調べるなり、ほかの自治体を調べるなり、そしてなおかつこういう理由でできないと。そういうことで申し上げましたので、もう一回１０月に設計をなさるわけですから、設計が終わったら設計を変更するのは厳しいことでしょうから、今の段階であえて申し上げさせていただいた次第です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"これは実例ですけれども、大森駅にわずかなスペース、幅８０cm、高さ１５０cmぐらいのフェンスがあったので、それを乗り越えてその中に寝たりしている実例があるわけで、いろいろ向こうのホームレスの方も知恵を持っていますので、当たり前ですけれど、それを定住化させるとすごく税金もかかるし、手間隙もかかってくるわけですので、せっかくこういう立派なものをつくっていくわけですから。","respondent":"谷田部児童課長","answer":"近隣の子供たちだけじゃなくて、例えば荏原方面から館外行事の一環でこちらまで足を延ばして、それで私どもの職員の指導のもとに思い切り遊んでもらうというようなことをまずやっていくということで、説明会でも子供たちは全然遊んでいないじゃないか。","voiceIndex":50,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうすると管理のほうですけれども、例えば管理・指導するボランティアの方が帰るときにはそれを全部しまって施錠するということですね。わかります。ホームレス対策はこうしたらよかったとか、これはある意味失敗したよとか、そういうようなものを十分踏まえて対応していっていただきたいと思うのですが、その辺の対応と確認はいかがでしょうか。","respondent":"谷田部児童課長","answer":"住民説明会でもホームレス対策というのが随分言われたところです。そういったご意見を踏まえまして、ホームレスの定住化の阻止に向けて、これから具体的な図面を引くわけですから、その中でホームレス対策を考えていきたいというふうに思ってあります。","voiceIndex":52,"id":"exchange-021"},{"speaker":"嶋委員","kind":"質問・要望","question":"何点かお聞きをしたいと思います。考えていらっしゃるかどうかということと、それとあと元なぎさ通りにあるのが、きっとこれが自転車の駐輪場だと思うのですが、目黒川のほうには駐輪場を考えていらっしゃるのかどうかをお聞きしたいと思います。","respondent":"谷田部児童課長","answer":"それ以外の場合については、原則閉めておくというような形で対応していきたいと思ってあります。","voiceIndex":54,"id":"exchange-022"},{"speaker":"嶋委員","kind":"質問・要望","question":"それと、今の電話のことなんですけれども、しっかりした電話ボックスだとまたいろんな意味で危険もあったりしますけれど、今ただ電話があってカバーがされる簡単なのがありますので、ぜひ安全対策を考えると、やはり子供たちは低学年が遊ぶとなるとやはり電話を家にかけたりとかすることがあるので、ぜひ電話をつけていただきたいことを要望したいと思います。それをお聞きしたい。","respondent":"谷田部児童課長","answer":"あれもこれも詰め込みすぎだと、本当に冒険広場ができるのかという話になりますけれども、そういうご要望を少しでも生かす形で考えていきたいというふうに思ってあります。","voiceIndex":58,"id":"exchange-023"},{"speaker":"嶋委員","kind":"質問・要望","question":"ちょうど手入れがしやすいように、やっぱり子供の目線で感じるぐらいの花壇も結構ありますので、もしできたら何カ所かだけでもいいから、全部路地ではなくて、そうやった手入れも楽にできるような花壇がありますので、ぜひそれは要望したいと思います。たしか横断歩道が大分離れたところにあると思いますので、こういう意味での交通安全対策などは考えていらっしゃるのか、ちょっとお聞きしたいと思います。","respondent":"谷田部児童課長","answer":"ですからその辺で道路の構造上の問題だとか、いろんな問題はあろうかと思いますので、その辺はちょっと確認をさせていただいた上で横断歩道等が設置できれば設置につきまして働きかけをしていきたいというふうに思ってあります。","voiceIndex":60,"id":"exchange-024"},{"speaker":"嶋委員","kind":"意見","question":"ぜひ危険防止というか、呼びかけというか、立て札を立てるとまたあれでしょうけれども、飛び出し注意みたいな形で、車を運転する方も、私もきのうあんなにそばに公園があるのを本当に申しわけなく知らなかったんですけれど、車の方たちがこの横に公園があって子供たちがいつ飛び出してもおかしくないというような危険予知ができるような安全対策をぜひお願いをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そしてちょっと何点かお聞きしたいんですが、先ほど指導員ってプレイリーダーということで何かのときにお答えいただいていると思うんですけれど、その方はボランティアでということで今答弁されましたけれども、これは有償のボランティアになるのかどうか、もし有償だったらどれぐらいの時給になるのか、そしているときといないときみたいな形で今おっしゃられましたけれども。","respondent":"谷田部児童課長","answer":"悪いことをしても怒れない大人もたくさん出てきている。ちょっと理想的な話なんですが、やはり地域社会を子供のこういう広場を使って、大人たちがよその子でもいけないことをしたら叱れるような、そういった形で運営できないかというのをまず基本として考えています。","voiceIndex":63,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、その世田谷のところでもお聞きしたところでは、やはり火を使うということに対して周りとのいろいろ心配というか、トラブルというのがあって、周りとの関係を本当に信頼関係をつくるということがすごく大事だというふうなことでお聞きしたんですけど、そういうところでは世田谷はプレイリーダーが必ず２名ずつは毎日配置されているというそういう状況になっていて。","respondent":"谷田部児童課長","answer":"遊びを指導する方の、先ほども大分申し上げましたけれども、いろいろな方々に参加していただきたいということで考えてございまして、その辺のコーディネートは児童課がやっていくです。","voiceIndex":65,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"信頼関係はそういうふうなところでということですが、火は使えるというふうなところでは結局ボランティアの方がいるときにはそれを貸し出して火を使うということができるという状況になるわけですよね。そうすると、その火の後始末だとか、そういうふうなところの責任というか、そういうふうなところまで全部そのボランティアの方が責任を持って最後まで後始末をするという、そういうことになるんでしょうか。","respondent":"谷田部児童課長","answer":"それは子供がちゃんとしっかりやって、それをやった結果、そばについている大人が最後の確認をして道具をしまうということですから、火をつけたらつけっぱなしじゃなくて。","voiceIndex":67,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その子供たちにそういうことを教えていくというふうなところが、そういうところでの、世田谷なんかではそういうところでプレイリーダーがそういう形で責任を持つというところまできちんと教えていくというふうな体制になっていると思うんですが、そこら辺の体制がこういう無償の、しかも見守りというふうなところでのボランティアで大丈夫なのかというふうなところなんですけれども。","respondent":"谷田部児童課長","answer":"責任は、最終的には区が持ちますから。区が設置して、子供たちに遊んでもらうということで、何かあれば区が最終的な責任を負う。これはもう原則です。それをすべてボランティアの責任だということはあり得ません。","voiceIndex":69,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"最終的には区が責任というふうなことはすべてそういうふうなことになると思いますけれども、かなり私はあそこのところの住宅が本当に周り全部木造で、本当に公園にすぐ密接しているというふうなところで、そこのところでもしも万が一火災とか何かが発生するというふうなことになったら大変だなというふうな思いがあったのでずっとお聞きしているんですけれども、そういうふうなところはどうお考えでしょうか。","respondent":"谷田部児童課長","answer":"住民説明会で、火おこし体験ができるということを私どもは強調してご説明申し上げました。そのときに火が飛んできてうちの家が火事になったらどうなると、一切私どもはそういうご意見は聞いてございません。そういうような子供たちに楽しい広場をつくるのかと。","voiceIndex":71,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。本当にそういうところでは管理も含めて子供たちが本当に伸び伸びと遊んでいけるようにきちんとやっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-031"},{"speaker":"須藤委員","kind":"質問・要望","question":"高齢者に対しては花壇等を残してもらえるということなので、やはり子供の広場という表現をしても、品川区全体の住環境としては高齢者が多くなってきているわけですから、そういう人たちに対しても何かの配慮をしていかなければいけないだろうというように思いますけれども、そのあたりは先ほど言ったような花壇等で対応したいというようなお話なので。","respondent":"谷田部児童課長","answer":"１点目の子供の数ということですけれども、手元に町々別の人口統計がございませんのでちょっとわかりませんけれども、私どもは児童センターをあの近辺で運営していますが、年々入会者もふえてきているということもございまして、決して子供が減っているということではなくて。","voiceIndex":78,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このＩＳＯ９０００シリーズの取得に当たっての予算の関係でお聞きしたいんですけど、総予算がどれぐらいかかるのかとか、その内訳、コンサルタントとかこういうふうにお願いしていると思いますので、その内訳についても教えていただきたいのと、そしてそのあと毎年２回ずつ監査が入るとかいろいろありますよね。","respondent":"金子保育課長","answer":"それがＩＳＯの９４年版に対してＪＩＳ規格では９８年版、かなりおくれて翻訳されるというふうな事態になっていまして、現実にも福祉の関係では私の知っている範囲では２０００年版について取得したというのは聞いておりませんので。","voiceIndex":86,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そしてあと、これをつくるのに当たって、このマニュアルがここに１ページ、これは要綱ということになるのか、手順ということになるのかよくわかりませんけれど、マニュアルということでは今課長さんがお持ちのところで、それに付随する下位文書というのはすごいたくさんあると思うんですけれど、これそのものは大体およそ何枚ぐらいあるものなのかということと。","respondent":"金子保育課長","answer":"今後の文書化についてもやはり労力がかかるのではないかということですけれども、私どもでは従来からお話し申し上げているとおり、この手法を全園的に広げてやっていこうという、保育園全体の保育サービスの質的向上を図ろうというふうに考えておりますので。","voiceIndex":88,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"毎年子供もかわるし、それとあわせて親もかわるし、職員もかわるというふうな中では、いろいろとマニュアルそのものも見直しとかというふうなことがずっとかかわってくるのかなというふうに思うんですが、そこら辺の維持するに当たっての人員配置というのがそのまま続けられるのかどうかについて一つお聞きしたいのと、それともう一つ。","respondent":"金子保育課長","answer":"前段の、今後の維持管理に当たっての人員配置ですけれども、まだ私どもはそこの詳細については詰めておりませんけれども、今回１園取得して。","voiceIndex":90,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"その満足度のはかり方というのは、具体的に何か親から寄せてもらうだとか、アンケートを取るだとか、そういうふうなのというのはあるのかということと、あと苦情処理対策というところでは、この９０００シリーズを取ることによってそこら辺のところが明確になっているということがあるのかどうかをお聞かせください。","respondent":"金子保育課長","answer":"１点、ご答弁申し上げます。満足度のはかり方ですけれども、これも実はこの９０００シリーズとは別途、既にご承知のとおりと思いますが、第三者評価ということで東京都の実施している部分に私どもも参加して、昨年度並びに今年度引き続き試行を実施する予定にしております。","voiceIndex":92,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それとあと、ちょっと細かくなるんですけれども、一つついているこのカラーコピーの資料なんですけれど、これは保育園生活の流れ及び園児数と職員配置というようなことで書かれているんですが、これ例えば園児が何人いて職員がどういうふうに配置されているかというのはこの図でわかるんですが、例えば７時半から８時半までの間は職員が１人しかいないということになっていますけれど。","respondent":"金子保育課長","answer":"１点目の、第三者評価の追加の報告ということですけれども、現在１３年度の東京都の事業展開がおくれていまして、当初予定ですと、大体１０月ぐらいに１３年度の第三者評価の試行をしようという予定だったのが、現在また準備段階で、恐らく私の見込みですと二。","voiceIndex":94,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりこれをつくる目的というのは、保育の質の向上というところだと思いますので、これに本当に手だけ取られて、逆に保育が後退するようなことがないようにぜひお願いしたいということと、あとまた父母の満足度というふうなところでは、この東五反田保育園はいろいろと予算のところでも出されていましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何点かお伺いいたします。ですから、例えばある親御さんはこういうふうにしていただきたい、また別な親御さんはこういうふうにしていきたい、当然要望は違ってくるわけですから、その中でいかに答えを出していくかというのは大変難しいとは思いますけれども、ただどこかでそのサービス提供の担保はしていく必要がある。お願いいたします。","respondent":"金子保育課長","answer":"これは何かをするに当たっては当然あり得るものだというふうに思っておりますが、私どもとしましては少なくとも最大限の理解を得られる、同意を得られるような方策を当然追求するわけですけれども、保育に当たっては児童の最善の利益、これが大前提になりますので。","voiceIndex":97,"id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問・要望","question":"むしろそのことをもってほかの園に広めていく、それから品川区の行政のほうも保護者の方々も含めていろんな方々に説明したりすることも出てくると思います。ですから、今なかなか回答しにくい部分はあるかもしれませんけれど、ＩＳＯを導入した結果こうなりましたよという実績と言いましょうか、結果と言いましょうか、それを目に見える形で表していただきたいと思うんですが、お願いできますでしょうか。","respondent":"金子保育課長","answer":"そういう意味ではそういったものを、変わっていく保育の内容を何らかの形で保護者の形に見やすい形で表現していくと。これは非常に重要なことだというふうに考えますので、その点についてはご指摘を踏まえて考えていきたいというふうに思っております。","voiceIndex":99,"id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問・要望","question":"プロセスが大切とおっしゃいました。まさにそれがいわゆるＩＳＯを導入したことによる結果であるはずですから、そのプロセスをもってほかの保育園に広めていっていただきますようにここでは要望しておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-041"},{"speaker":"船波委員","kind":"質問","question":"ＩＳＯ１４０００シリーズのほうですと、その認証取得をする組織がある絶対的な環境にする配慮をしているから認証が与えられるというのではなくて、その環境に対する配慮がその取得する組織が今現在どこであるにしても、それを見直してよりよくしていくシステムができたということに対して認証が与えられるのだと思っていますけれども、この９０００シリーズに関しては、どういうことに対して。","respondent":"金子保育課長","answer":"認証取得後の検査と言いますか、維持管理ということですけれども、先ほど鈴木委員のほうからもありましたとおり、これにつきましては一定の年数で、毎年かどうかはちょっと私ども確認しておりませんけれども。","voiceIndex":102,"id":"exchange-042"},{"speaker":"船波委員","kind":"質問","question":"わかりました。今までのきょうのご説明を聞いていると、保育の質を利用者の満足度なども考えて向上していくことに関しては第三者評価の結果などを考慮して考えていくということで、このＩＳＯ９００１に関しては同じクオリティのものが提供されるようにするということが強調されているような感じがしたので、そうなのかなと思ったんですけれど、どうでしょうか。","respondent":"金子保育課長、小沼福祉事業部長","answer":"私どもにしてみれば、保育サービスというものが一定の水準を絶えず維持していくためには、やっぱり問題が次々起こってくるわけですから、それについての対応策なり対処策というのを必ず考えて実行していく。今、保育課長のほうからるる詳細な点の説明があったのですが、一言で申し上げてしまいますと、これチャレンジしました、取りますと、これは本当に永続的にそれをキープしていかざるを得ません。","voiceIndex":104,"id":"exchange-043"},{"speaker":"船波委員","kind":"質問","question":"わかりました。別の点なんですが、この東五反田保育園というのは、ＰＴＡが設立される園でもあるんですけれど、このＩＳＯを取得して維持していくというのはそれは大変な作業だと思いますけれども、保護者とのかかわりということもあって、ＰＴＡとはどういう関係になっているのか、ちょっとお伺いしたいと思います。","respondent":"金子保育課長","answer":"それについては非常に真摯に素早い取り組みをしていまして、例えばことしの夏前だったと思うんですけれど、昔で言えば目安箱みたいな、無記名で出してもいいような投書の箱を設置することによって保護者の声を。","voiceIndex":107,"id":"exchange-044"},{"speaker":"船波委員","kind":"質問","question":"保護者の思いをくみ上げる、ルートとしてそういうことをやっているというのはわかりましたけれども、この管理表によるともうことし４月から始まっているこの９００１取得へ向けてのさまざまな動きの中で、何か保護者の方々にしてもらうこととか、お願いしたこととか、あるいはもうお知らせしていることとか、そういうことはどんなことが行われてきているんでしょうか。","respondent":"小沼福祉事業部長","answer":"ですから、そこらあたりでも審査の対象となりますし、逆にＰＴＡの方々からの意見の吸収なり、あるいは応答ができるようなものが自動的になっていると。それも含めての全体の質のアップというんですか、品質向上に努めると、こういうふうにご理解いただければと思います。","voiceIndex":109,"id":"exchange-045"},{"speaker":"船波委員","kind":"確認","question":"すみません。それともその９００１のマニュアルに入れていくものの中でそういった園と保護者とのかかわりについてはこういうものを入れようと考えていますけれどどうでしょうかというような話とか、そういうのは行われたんでしょうか。","respondent":"金子保育課長","answer":"ただ、先ほど部長が申し上げたとおり、マニュアルの中に乗っているＰＴＡの設立というふうな一つの単位を考えてみますと、このＰＴＡの設立に関しては保護者から役員を募ったり、こういったものを実施するけれども賛成の方は意見なりご質問なり受けますよということでは。","voiceIndex":111,"id":"exchange-046"},{"speaker":"鶴副委員長","kind":"質問","question":"この９０００シリーズの取得については、東五反田の保育園だけですか。","respondent":"金子保育課長","answer":"１３年度で９０００シリーズ取得を目指しているのは東五反田保育園１園です。","voiceIndex":113,"id":"exchange-047"},{"speaker":"鶴副委員長","kind":"質問","question":"その保育サービスの質の向上というところに最大のねらいがあると思うんですね。ということは、一つのところが例えばそれに準拠する形でやっていこうとしているのか、いやいや１３年度は東五反田が一つで、ほかのところも続々とそういう９０００シリーズの認証を取得したいという保育園が出てくれば、それにチャレンジさせるという意味なのですか。１３年度は、という意味は。","respondent":"金子保育課長","answer":"そういう意味では私どもとしては、１３年度は１園でこれを取得することを目指して、ほかの園で取得するというのではなくて、そのノウハウをほかの園に広めていって、品川区の保育園全体のレベルアップを図っていこうというふうに考えているところです。","voiceIndex":115,"id":"exchange-048"},{"speaker":"鶴副委員長","kind":"質問","question":"それはすばらしいというふうに思いますね。ならば、そういうふうにそれは園の関係者だけではなくて、実際保育園に子供を預けている人並びにこれから預けていこうという人については、どういう形でそのすばらしい品質を持っているということを知りうることができるのですか、具体的には保育園に行かなければわからないのか、保育園に行かなくてもわかるようになるのかです。どうなんでしょうか。","respondent":"金子保育課長","answer":"先ほど申し上げたマニュアルないし下位文書等々たくさん文書はありますけれども、こういったものというのはその場で保育園なら保育園、あるいは保育課なら保育課というところでごらんいただくというふうになると思いますけれども。","voiceIndex":117,"id":"exchange-049"},{"speaker":"鶴副委員長","kind":"質問","question":"どんな職員がいるのか、どんなまずい職員がいるのかというようなことについては、どのようにして私たち区民は知り得るんでしょうか。そういう資料というのはこの中にインプットされていくのですか、されていかないのですか。一番大事なことなんです。そのどういう人的資源が整っているかということについてはどうして知ることができるのですか、その片鱗でも。","respondent":"金子保育課長","answer":"私どもで今回取得を目指しているこのマニュアルによって、私どもが目指しているところは、どの園であっても、どの保育室であっても、同質のサービスが提供できるように全体としてレベルアップを図っていきたいということですので。","voiceIndex":119,"id":"exchange-050"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"それは理解しますよ。一番身近なところで、全体的から見れば課長が９００名ぐらいの人を面倒見ていることに、面倒見るというか、保育課の課長の配下には、上下はないわけだけれども、職員がいらっしゃるわけです。全部目が届かないですね。となってくると、だれに一番しっかりしてほしいかといったら、園長さんだわね。いい方向に追求、追い求める追求です。そういう体制のほうは大丈夫ですか、部長。","respondent":"金子保育課長","answer":"副委員長ご指摘の部分というのは、確かに過去においてそういう心配をせざるを得なかった場面というのはあっただろうというふうに認識しております。","voiceIndex":121,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この保育園ＰＴＡについては、今までも何回か質疑、ここでは質疑されていませんけれど、されてきたと思うのですが、活動等について区としても支援するということで答弁されていますけれども、その支援の具体的な中身について一つ教えていただきたいのと、それからこの保育園ＰＴＡの活動する中身というのは具体的にどんなものになると考えているのかについて教えてください。","respondent":"金子保育課長","answer":"２番目の保育園ＰＴＡの活動内容として私どもが考えているのは、そこの各園の事業の内容にもありますけれども、子育てに関する講座、こういったことを開くことによって会員相互の保育の知識の向上を図り、あるいは園児、保護者、あるいは会員相互の交流活動。","voiceIndex":127,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、例えば保育園行事とのＰＴＡとのかかわりというふうなところはどういうことになってくるんでしょうか。","respondent":"金子保育課長","answer":"予算的なものですけれども、１３年度予算で計上しているのはご指摘のとおり３０万円ですけれども、今のところ園の事情によって、例えば連絡手段として掲示板がいいとか、あるいはウォールポケットのようなものがいいとか、それは個別に違いますので。","voiceIndex":129,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ＰＴＡの会議というのがこれからされてくるようになると思うんですけれども、その部分では保育園の園舎を使うということもＯＫだということで今ご説明いただきましたけれども、これは基本的に親が働いているというふうな状況ですから、学校のＰＴＡのように昼間ということにならないと思うんですけれども、そうするとそのときには職員が超勤扱いになってＰＴＡの会議に参加するという。","respondent":"金子保育課長","answer":"もう１点、職員の超勤対応ということですけれども、基本的には役員さんもその他の方も含めて、先ほどちょっと申し上げたとおり、労働時間、あるいは保育の時間以外に過超な負担というのをおかけするというのは基本的には考えておりませんので。","voiceIndex":131,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"保育園の行事は区の職員が基本的にというふうなところで、一瞬たりともというわけではないというふうなことなんですが、ここら辺のところではぜひ今回のＰＴＡ設立というところでも、保護者と職員が意見交換や相互の親睦というふうなところで、やっぱり保育者と。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-055"},{"speaker":"嶋委員","kind":"質問","question":"この保育園ＰＴＡ設立というのは、本当につい最近お聞きしたような感じがしました。区のほうはこれを予想していたぐらいの数だったんでしょうか。これはこれだけやはりするということは、やっぱりニーズに合って、保護者の方たちの思いがあったのかなと思いますが、そこら辺ちょっとお聞きをしたいと思います。","respondent":"金子保育課長","answer":"私ども予算を調整した段階では、先ほどちょっと申し上げたとおり、３０万円で、その内訳は６万円掛ける５園というふうに思っておりましたので、私どもとしましても予定より多いかなというふうに考えているところです。","voiceIndex":134,"id":"exchange-056"},{"speaker":"嶋委員","kind":"質問・要望","question":"大変喜んでいらっしゃるということでよろしいでしょうか。本当に私も八潮に越してきて１９年になりますけれど、やはり八潮北小がＰＴＡをつくっていく段階から、最初から入っているんですが、そういう中で本当に大変でしたけれど、楽しい思い出を、こういうときってめったにないんです。あってはならないことだと思うんですが、ちょっとそこら辺をお聞きしたいと思います。","respondent":"金子保育課長","answer":"先ほどの２枚目の資料にあるとおり、保護者につきましては少ないところで２２名から４０名ということで、保育園の定員が大体７０から１００ですので、そういう意味では全体ではないというところはおわかりいただけると思いますし、私ども園長に向けて。","voiceIndex":136,"id":"exchange-057"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、園長直接なのか、担任の先生なのか、そこら辺は園によって違うかもしれませんけれど、園長に直接やはりお話が保護者ができるような体制をますます綿密にとっていただけたら大変助かりますので、要望しておきたいと思います。よろしくお願いします。お母さん方がなかなか園長さんに直接言うというのはやっぱり難しい。要望にとどめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-058"},{"speaker":"鶴副委員長","kind":"質問","question":"これは今までにいろんな反省の上に立ってでき上がったことですから、例えば園舎の使用についてもできるようになったのはこれは保護者、要するにＰＴＡということになったから使える。当然ですね。それを超えているということはとてもいいことだし、やっぱり理想的なものは全園にこういうＰＴＡの組織があったほうがいいというふうに私は考えるんですが、今後の展望は煮上がっている絵があるのですか、今。","respondent":"金子保育課長","answer":"前段のほうでお話のありました目的ということなんですけれども、私どもはこの園舎を使用できるという格好のためには、任意団体とはいえ、一定の目的、一定の活動方針の中でやってもらわなければいけないというふうに考えておりまして。","voiceIndex":139,"id":"exchange-059"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、これは逆に言えば、保育園の管理運営とか人事管理等に関しては一定の距離を置くと言いましょうか、不介入ということはなかなか難しいでしょうから、請願・陳情の道がありますから、それはやめろということはできませんので別にしても、ある程度一定の距離を置くシステムとか、そういうところを担保しながらこのＰＴＡをどんどん設立をしていただきたいと思うのですが、質問は。","respondent":"金子保育課長","answer":"今後の拡大の方向ということですけれども、私どもとしましては、各園の、例えば保護者の状況、あるいはそこでの、正直に申し上げますと、職員の認識状況、そういったものすべてを総合的に判断して、徐々に拡大していこうと思いまして、先ほど申し上げたとおり。","voiceIndex":141,"id":"exchange-060"},{"speaker":"伊藤委員","kind":"質問","question":"今、ふと思いましたけれど、いろんなビラの事件もあったり、いろいろありましたけれども、でも結果としてここまで来たわけですから、これをいつまでも、確かに自主的な団体ですから設立を待っているということなんでしょうけれども、やはり今までのいろんな、ある意味苦労、それからいろんな思いがあるでしょうから、それをいい意味に転換していくことを考えたら、これはただ好きにありますよ。","respondent":"金子保育課長","answer":"私どもとしては、先ほど申し上げたとおり、過去のいろいろないきさつを排するために、私どもがチェックをしていかなければならないと思っていましたので、そういう意味では１０以上までは難しいかなと思っていましたので。","voiceIndex":143,"id":"exchange-061"},{"speaker":"伊藤委員","kind":"質問・要望","question":"簡単に要望だけしておきますけれども、相当このことについては今まで議論もありましたし、それからいろんな要求も実際あったことも事実です。一つの回答がこれですから、これはいい意味で定着をしていただくために、今言った保育課長の答弁を踏まえてそれで進めていっていただきますように要望しておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もしあったら後で結構なんですが、いただきたいということでお願いしたいと思うんですが、そのことが１点と、それと事業内容が組まれていますけれども、これはＰＴＡの会員というのが先ほどから出ているように２２名とか４０名ですけれども、この会員を対象ということで、それ以外の方は対象にはならないのかどうかということと、それともう一つ、例えば小山台なんかは保護者が２２名という状況ですが。","respondent":"金子保育課長","answer":"会員の保護者をこれからどう拡大していくかということですけれども、先ほど申し上げたとおり、やはりどういう事業をやっていくのか、その事業を見ていただきながら会員を増やしていくというのが最も端的な会員勧誘の方法ではないかと思いますので。","voiceIndex":146,"id":"exchange-063"},{"speaker":"鶴副委員長","kind":"質問","question":"だから全員がこの新しく生まれたＰＴＡの会員に、本当は子供がおるんだったら素直に今までのことを改めてすっと入ってきたほうが、署名運動なんかもやる必要ないんだからいいと思うんだけど、やっぱり今のそういうふうにちょっとありましたように、前とのしがらみがあって拒絶反応している、拒絶反応どころか。","respondent":"林（和）委員長、田中健康課長","answer":"ほかに。ないようですので、これで４番目の（仮称）保育園ＰＴＡ設立についての報告を終了いたします。続きまして、５番目の、乳がん検診マンモコースについて、理事者からご説明を願います。この１０月から品川区医師会、荏原医師会におきまして、月１回、１回１５名程度とりあえず準備をしていただいて。続きまして、６番目のＣ型肝炎ウィルス抗体検査の実施について、健康課長、同じですので、一緒に説明願いまして、一括して質疑したいと思います。","voiceIndex":148,"id":"exchange-064"},{"speaker":"船波委員","kind":"質問","question":"併設、両方を選べますとはいっても、そういうものが新しくできると、では問診、視診、触診をしただけでは見過ごされてしまって、発見されるのが遅くなってしまうから最初からマンモグラフィをしたほうがいい、だからこういうのが新設されて、それであればやはり最初からマンモグラフィをしなくては不安なんじゃないかというふうに私自身も思いますし、そういった思いが出てこないかなと思うんですが。","respondent":"田中健康課長","answer":"ですから、この中の相当数が精検に至るまでにご自分の不安を早く解消させたいという意味で選ばれる方が相当数出るのではなかろうかということで、並行して実施をするということがありますが、これ自体がどのような結果という今後の推移を見まして。","voiceIndex":155,"id":"exchange-065"},{"speaker":"船波委員","kind":"質問","question":"そうしますと、こういったことがもうすぐ１０月から実施ということですけれども、現行と新設と二つのコースが併設されて、どちらか年に１回受けてくださいという場合に、早く確実にというか、結果を知りたい方は最初からマンモグラフィのほうで、自分で別に自覚症状があるわけでも何でもない、それほど不安に思っていない人は無料の現行のコースでもいいですよというようなお知らせになるんでしょうか。","respondent":"田中健康課長","answer":"この状況に合わせてご自分の不安、それから一般的な診断という形で受けていただく選択肢かというふうに認識しております。","voiceIndex":157,"id":"exchange-066"},{"speaker":"船波委員","kind":"質問","question":"わかりました。今回Ｃ型の検査を始めるということですけれど、それではＢ型はどうなんでしょうかということをお伺いしたいと思います。","respondent":"青山品川区保健センター所長","answer":"それに対して、Ｂ型のほうは１６％ぐらいというようなこともございまして、特に対策のおくれていたＣ型肝炎に対する対応を今厚生労働省が極めて急いでいるというところがあります。","voiceIndex":159,"id":"exchange-067"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう方式になっていくのか、ちょっと教えていただきたい。","respondent":"田中健康課長","answer":"ただ、不安を感じている方はそのダイレクトメールが行くまでの段階ではあれなものですから、間もなく私どもも区の広報でこの新設しましたというこの新たなコースについてのお知らせをいたしますし。","voiceIndex":161,"id":"exchange-068"},{"speaker":"嶋委員","kind":"質問","question":"そういう場合はお誕生日月でなくても申し込みができる方と、それとお誕生日月になってから初めてこれを見て申請する方が重なっていくと思いますけれども、先ほどもいろんな関係で月１回１５名程度、両方で３０名ということになると、大変、もし電話をしてもどういう方向……。すみません、電話か郵送かというのをちょっと教えてください。","respondent":"田中健康課長","answer":"これは実は一般コースの精密検査がほかの月３回、実は現在もやってございまして、それとのバランスがこれから周知度とか、それから皆さんの選択の度合いによってどういうふうに流れるかということも含めて、両医師会のほうとこれからご相談しながら回数等、あるいは機会等。","voiceIndex":163,"id":"exchange-069"},{"speaker":"嶋委員","kind":"質問・要望","question":"これは今回１,０００円なんですが、一般で受けるとなるとどのぐらいの金額になるかおわかりでしょうか。","respondent":"田中健康課長","answer":"保険診療の点数がいろんな方法論があるんですが、６,５００円から７,５００円ぐらいというふうにお考えいただければよろしいかと思います。","voiceIndex":165,"id":"exchange-070"},{"speaker":"嶋委員","kind":"質問・要望","question":"それぐらいかかるんだったら、ぜひこの区の無料を受けるということもぜひ区民の皆さんに言っていきたいと思いますので、ぜひこれは回数を多くしていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"乳がん検診のマンモコースのことなんですけれど、このマンモグラフィの文献を読んだら、マンモグラフィで最も期待できるのは、微細切開下で腫瘤を形成しない早期のがんの検出ができるというふうなことで書かれていまして、最近はそういう早期がんというのがよく報告されているということで書かれていたんですけれども、そういうことを考えると。","respondent":"田中健康課長","answer":"それで、私どもとしてもはっきりわかっていれば、ある程度少ないご負担の中で早く結果がわかるもののほうがよいのではなかろうかということで議論も進めておりまして、ただ、それがどこまでのことをやればいいのか、それこそ予算的なものもございまして。","voiceIndex":168,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこのところで、本当にそこでやっていれば見つかるものが見つからないでしまうというものがあるんじゃないかなということが危惧されるんですけれども、私の知り合いでもしこりがあってこの医師会の検診を受けたんだけれども、大丈夫でしょうということで言われて。","respondent":"田中健康課長","answer":"そういう意味でこれからそういう形のものがどこまでが一般的に受けていただき、あるいはその精度管理と言いますか、発見の正確さみたいなものが医学の発展とともにどういうバランスで行くかということを含めながら検討したいというふうに考えてあります。","voiceIndex":170,"id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"Ｃ型肝炎についてなんですが、私も区民検診のほうで受けられるというふうな方向でニュースでいろいろと見ていたので、今回は区民検診で受けられることになったのかなとちょっとはじめ勘違いしていたんですけれど、これですとなかなかちょっと一般的には保健所まで行って健康相談の中で相談を受けて、その上での希望者にというふうなことになるので、どれぐらいの受診率というか。","respondent":"田中健康課長","answer":"できれば４月からということで厚生労働省は考えているようですが、恐らく本格的な対策というのは厚生労働省も５歳刻みの節目検診でもって、５年間ですべて計画的に心配をなくそうということが基本だというふうに考えてありますので。","voiceIndex":172,"id":"exchange-074"},{"speaker":"鶴副委員長","kind":"質問","question":"このマンモグラフィですけれども、医師会で機械を何台持っているんですか。医師会でこのマンモグラフィ検査をする機械を何台持っているのですか。","respondent":"田中健康課長","answer":"それぞれの医師会１台ずつかというふうに認識しています。","voiceIndex":174,"id":"exchange-075"},{"speaker":"鶴副委員長","kind":"意見","question":"なぜ聞いたかと言いますと、私たちは早期発見早期治療ということで、ほかの病気もそうですが、がんをどう駆逐するかということが私たち人類にとって大きな課題ですね。先ほど、実際は有料であったら６,５００円から７,５００円という答弁によるとそういうお話をされましたね。それであと心配になった人が１,２８１名ぐらいがこの受けていらっしゃるということだったかな。","respondent":"田中健康課長","answer":"昨年の実績で申し上げますと、精密検査という形で受けている方が１,２８１名です。","voiceIndex":178,"id":"exchange-076"},{"speaker":"鶴副委員長","kind":"意見","question":"だから１,２８１名の方がこのマンモグラフィ検査を受けられたと。あるいは超音波検査だけだったのか、あるいは今までの細胞診検査まで、三つのこの項目で全部を受けられたのかどうか。","respondent":"田中健康課長","answer":"この三つをすべてやっているかどうか、必要に応じということがありますので、精密検査の所見によりまして、両医師会の診療所の専門の先生方が必要に応じてやっているですので、マンモグラフィは確かに基礎的にはやっているようです。","voiceIndex":180,"id":"exchange-077"},{"speaker":"鶴副委員長","kind":"質問","question":"品川区みたいに保健所を持っているようなところが、保健所にもこういうマンモグラフィ検査装置があってしかるべきだと、そういうふうに思うんですよ。何か言うと、両医師会に委ねてお願いしてしまうと。基本的なものの考え方というのはどうなんですか。区民の命と何とかというのは、私たちは区民の命と財産を守る使命が自治体にはあるわけですよ。どうですか。１,０００円負担だけで。","respondent":"田中健康課長","answer":"保険の自己負担分を区が埋めてあげるという内容でございまして、そういう形では保険適用はされておりますので、不安な方、極端な話を言えば、私自身もいろいろ区の中で受けまして。","voiceIndex":182,"id":"exchange-078"},{"speaker":"鶴副委員長","kind":"質問","question":"わかりました。私の聞き違いというか、予測でしたから。女性の方はそういうことはないのかもしれませんが、本当は自己負担はないんですよと、結果的には。自己負担分に相当する１,０００円、それを今回この行政サイドで負担するので、検診を受けたいと思っている人は全く何の負担もないんですよということになるわけですか、これは。今の説明によると。","respondent":"田中健康課長","answer":"ですから、結果的には無料という、最後まで無料ということなんです。今回は１,０００円をいただくことによって早く対応が図れるようにしたいという内容で考えてあります。全く保険とかかわりなく検診という内容です。","voiceIndex":184,"id":"exchange-079"},{"speaker":"鶴副委員長","kind":"意見","question":"今回新設される分については、１,０００円払ってくださいよと、１,０００円はいただきますよと、ただじゃないということだね。わかりました。こういうふうな１,０００円負担、１,０００円だからいいじゃないのという人がいるかもしれないけれども、そうじゃないのではないかなという疑問もちょっと残るし、私も研究課題にさせていただいて、これ以上質疑はいたさないことにいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":186,"id":"exchange-080"},{"speaker":"伊藤委員","kind":"質問・要望","question":"一つだけ確認ですけれど、乳がんマンモコースのご説明でいろいろいただきましたけれども、私たちの会のところに医師会のほうから乳がんの検診の回数増とか、それから待機者増というので、解決体制を取ってほしいという要望が来ているんですが、その思い、今最後、副委員長の質疑の中で確認なんですが。","respondent":"青山品川区保健センター所長","answer":"ただ、そのあたりを実際に募集をしてみて、そして医師会のほうにもいろいろお願いをしながら、どのような頻度でどのような人数を一回当たりこなしていただくのか、そういったような事柄も医師会と十分に相談をしながら。","voiceIndex":187,"id":"exchange-081"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、そこの部分を埋めるための努力というのは、せっかくこういうふうな窓口が広がって、結果としてまたそれがおくれてしまったら本末転倒になるわけですよね。だからその後対応をどうしたらいいのかというとなかなか……。わかるんですよ。税金の使い道の問題になってくるからわかるんですけれども、でももう少し考えていただけないでしょうかという思いがあるんですが、答弁をいただけますでしょうか。","respondent":"田中健康課長","answer":"今回初めてこういう形で自己負担をいただきながら新たな方法ということで進めてまいります。これがどういうふうに希望の推移が変わるか、ちょっと私どもも予測ができていない部分があります。","voiceIndex":189,"id":"exchange-082"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ぜひ、税金の投入の部分ももちろん整合性あるんですけれども、こういうシステムが円滑に回ることによって、要は疾病、がんというものを防いでいくことになるわけですから、そういうようなことの目的を十二分に考えた上で具体的な対策をとっていただきますように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-083"},{"speaker":"鶴副委員長","kind":"提案","question":"区別しているんだったら、いろんな在宅支援の復帰支援策がたくさんあると思いますけれども、今回提案したことについて品川区では検討なさるのかなさらないのか。原則は午前９時から５時というふうになっている。僕の答弁の聞き間違いだったらお許しいただきたいんですけれども、財政支援をやっているからということで、財政支援をやっているんだったら、なぜほかのところがそれをやっていないんですか。","respondent":"新美保健高齢事業部長","answer":"延長デイサービスについては、ご質問のとおり、現時点では１カ所でサービスセンターでやっておりまして、財政支援の中身は基本的に今まで在宅サービスセンターでやっていたサービスで共通にやってもらう部分のほかに。","voiceIndex":194,"id":"exchange-084"},{"speaker":"船波委員","kind":"質問","question":"このレジュメでは一律……。何せいろんな、当初のワーキンググループでさえも６０人以上というようなたくさんの人が代わってやってきたことですから、それは何か決定に至るにしても何にしても、いろんな意見が出て、それをまとめるということは大変なプロセスだった、人間相手のことですから大変なプロセスだったのではないかと思いますけれど、そういった経験談というか、特に関心があるところです。","respondent":"林（和）委員長","answer":"ここの中に入れておいていただければ、前もって向こうで、そのときにも説明もあるでしょうし、いきなり聞かれるよりも、前もってこちらから調査事項の中に入れておいていただければ、向こうで用意していただけるんじゃないかなと思いますので、それを入れるということ。ほかに。","voiceIndex":207,"id":"exchange-085"},{"speaker":"鶴副委員長","kind":"質問","question":"配ってあるこのレジュメのところに、平成４年のときの鷹巣町の高齢化が今１９％を超えていたので、寝たきり老人の介護の問題など大きな問題があって、そのために理想の福祉とはどうあるべきかを検討しようと現在に至る福祉への取り組みが始まったということですから、ここがスタートになっているのかなと思うのね。だからどこからどこの範囲まで話をすることにするのかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":210,"id":"exchange-086"},{"speaker":"船波委員","kind":"質問","question":"そうですね。ですからワーキンググループが、主なところはワーキンググループが立ち上がってからそこに参加された町民の方々と町の話し合いということとか、いろいろなサービスやら施設を整備してほしいという意見が出て、そこに至るまではあれやこれやの意見があって、じゃこれにしましょうと決定するのもなかなか難しかったのではないかと思いますけれど、そういうところ。決定に至るまでの様子ですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-087"},{"speaker":"鶴副委員長","kind":"提案","question":"僕なんかがここにいろんな施設だとか何かで住民のボランティア組織であるワーキンググループによって要するに検討されて提案されて実現したというところにすごくよさというものをよくできたなと、よくみんなが２万２,０００人の人口の中で大人の人が１万８,０００人ぐらいいるのかしらね、子供除いて。だから提案があったこの人たちとは会話するチャンスがなかなか設定が持てないということでしたよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":213,"id":"exchange-088"},{"speaker":"船波委員","kind":"質問","question":"ええ、参加された方に、でも話を伺えればそれはもちろん、そういうところをぜひと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":217,"id":"exchange-089"},{"speaker":"鶴副委員長","kind":"意見","question":"特にどういう困難なことがあって、それをどう克服したかというところが僕だったら知りたいなと思う。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":219,"id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問","question":"多分町は関係していなくても、こういう意識が高いとろですから、町の皆さんが自主的にやっているかもしれない。要は介護保険のサービスをどこかで、鷹巣町のほうで客観的な立場でもいいし、町を離れた立場でもいいんだけれども、把握しているところがあったんだったらば、ぜひそこを見たいし聞きたいし、意見も聞きたいという思いがあるんですが、いかがでしょうか。どうしたらいいんですか。","respondent":"事務局","answer":"このレジュメの中にもう１点再度確認の意味も込めまして落としまして先方にお送りしてご用意いただくということは可能かと思います。","voiceIndex":228,"id":"exchange-091"},{"speaker":"伊藤委員","kind":"質問・要望","question":"鷹巣については、いろんなつくり上げてきた経過がいろいろ私ども勉強する中ですごいなと思うのは相当あるんですね。だから、両部長がいる前では申しわけないんだけれど、その客観的な立場で介護保険サービスの提供を評価している仕組みがあったらぜひそこを、できれば鷹巣町では見てきたいという思いがあります。もちろん限界がありますので、要望だけ伝えておきますけれども、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-092"},{"speaker":"嶋委員","kind":"質問","question":"もし、分担が、一応全部できればいいんですが、今は大変だということだったので、分担が一番早いかなと思いますけれど、そうしますと、自分はやっぱりこれをやりたいというのがあるかと思うんです。その希望が通るんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"１人が一つの項目だけというよりも、複数で複数の項目を持つというふうにしたらどうかなと思います。","respondent":"林（和）委員長","answer":"それを全員で全部をやるのがいいのか、それともそれぞれが担当、さっきも言うように、１人の方が２項目ずつ持つのか、１項目持つ人とに分けるのか、それとも複数で持って４項目ずつやるのか。","voiceIndex":237,"id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"感想というのは、例えば自分が分担されたところの項目に対しての感想というのじゃなくて、全体を通しての感想を全員が出すという形にして、そして分担はできれば複数で、２人で２項目ずつ持つとか、２人で違うペアでも構わないんですけど、自分で例えばメモしてきたものだけだと不十分かもしれない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-095"},{"speaker":"船波委員","kind":"質問","question":"一人で必ず２項目とか、あるいは一つの項目について必ず２人がやるとか、もうそういうふうに固く決めないで、事前に皆様の希望を聞いて、少なくとも漏れているところがないようにしておくぐらいでいいんじゃないでしょうか。ですから、関心が高いところでは、一つの項目について３人いてもいいかもしれないし、あるいは薄いところではお一人しか関心のない項目もあるかもしれない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":240,"id":"exchange-096"},{"speaker":"鶴副委員長","kind":"意見","question":"一番いい方法は、要するに今回の厚生委員会の行政視察に参加してというタイトルでみんなそれぞれで書いてもらうことです。自分が気に入ったところをどうだったとか、要するにレポート形式でもいいし、随筆形式でもいいし、ドキュメンタリーでもいいし、それを書いてもらう。でないと、会派が違う人と調整するのは大変だよ。見解も違うことだし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":241,"id":"exchange-097"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、最終的には正副委員長のもとで、厚生委員会という大きな中でやっていくわけですから、当然意見の不一致があったにしても、厚生委員会の名のもとにまとめていくわけですから、ぜひ厚生委員会という大義名分の中でまとめていっていただくためには、感想の部分はストレートな表現ではなくて、例えばこの件については意見の不一致があったとかそういうふうなものでまとめていっていただくと考えると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":246,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"この鷹巣町と宮古市の介護保険の事業概要というのは、この市勢概要の中に入るということで確認させていただいていいんでしたっけ。ちょっとそこのところがどう……。介護保険全体の事業概要という項目がここにないんですけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-099"},{"speaker":"鶴副委員長","kind":"質問","question":"原稿用紙なら原稿用紙５枚というふうに。運営主体は民間がやっていましたとか、職員体制は６名でやっていました。その他云々。ＡさんとＢさんとＣさんの文言が文言的に重なってもそれは当然同じところに視察に行くわけですから、表現が違うだけですよ。そういうほうが、原稿用紙５枚とは言いませんから、何枚がいいかは検討してもらって、それのほうがいいのではないかと思いますが、どうですかね、伊藤さん。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":256,"id":"exchange-100"},{"speaker":"伊藤委員","kind":"確認","question":"やり方はいろいろあります。ただ、きょう欠席の委員も含めて、きょう出た、これはだれがお願いすればいいんでしょうかね。きょう出た意見を踏まえて欠席の両委員も含めて再度確認をとっていただいた上で、例えばじゃ全員がそのことを見つめていくんだということとか、それから個々にこの項目は私がやるという担当を決めていくのか確認してほしいんですが、時間がないということですからきょう決めますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3000#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":91947,"voices":262}},{"id":"h13-20010926-8","meetingId":"h13-cm09","date":"2001年9月26日","dateIso":"2001-09-26","committee":"建設委員会","time":"午前１０時０７分～午後０時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"辻委員","kind":"質問","question":"そもそも公園の説明のところにありますけれども、法的な担保性を高めるためというのは、そういう意味合いというのは、図面から見ると、６００m2という、後を取って６００m2を取ってこっちへつけるということですね。隣接して一緒になって一体というなら分かるけれども、真ん中に下がっている区道ですか、大きい通りがある。財源的にこれをやったほうが金を取りやすいとかというと話は別ですけれども。","respondent":"岩田管理工事課長","answer":"位置については、いろいろ意見もありますけれども、残余地の取り扱いについて、都市計画決定を受けて、都市計画公園として土地を取得する場合は、国庫補助金並びに都市計画交付金、その上物については財調で対応されるという財源的な仕組みがございまして。","voiceIndex":5,"id":"exchange-001"},{"speaker":"上山委員","kind":"質問・要望","question":"要望ですけれども、どういう形になるか、これから検討をされておると思いますけれども、これから工事を始めるわけですが、現場は、夕方だったんですけれども、まだかなり荒れているような感じですし、住民の皆さんがいろいろ要望も出されていたかと思いますので、そういう要望を汲んでいただいて、きれいな公園というか、子どもたちが遊べるように、よく検討をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-002"},{"speaker":"辻委員","kind":"質問","question":"自己責任というのは非常にいいんですが、基本的には対象はフリーでしょう。やはりそこには自由に木登りとか、子どもがやるのを見るとはらはらするというのがあるんですけれども、こういう公園という立場から見たときに、それだけの保険というんですか、事故に対するものはどういう考え方ですか。一般的にわーっとかかっているんですか。その辺をお伺いします。","respondent":"岩田管理工事課長","answer":"これは、保険の意味では、こういった公の施設は２３区の自治体賠償保険に一括で入ってありますので、そういった財源的な補てんも併せてしておるです。ただし、今回の場合、おっしゃるように、公園内での遊びは自己責任というのが原則です。","voiceIndex":13,"id":"exchange-003"},{"speaker":"辻委員","kind":"質問・要望","question":"よろしくお願いします。木登りのできる木を選んで、うまくやっていただきたいと思います。椎の実がなるとか、登りたくなるような木。その辺もよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"ここはすぐ隣が密集住宅に接しているところですね。学童保育クラブが長い間あったから、ある程度近所の人も理解があるとは思うんですが、全員一致で拍手で承認してもらったというのがあったけれども、住民の人からどんな意見が出たのか、出なかったのか、ちょっと教えてほしい。プレイリーダーがいないときには、学童保育クラブの冒険ひろばはオープンになっているんですか、そこらをちょっと教えてください。","respondent":"岩田管理工事課長","answer":"これでは残念ながら泥ダンゴもできませんし、泥んこ遊びもできないわけです。昔のように自由に土をこねて、子どもたちが泥んこになりながら遊べるような空間をここにつくってあげよう。","voiceIndex":16,"id":"exchange-005"},{"speaker":"築舘委員","kind":"質問","question":"ちょっと気になったのは、公園の整備のことで、園内を通行する方のための舗装をやっておって、舗装がどの程度なのかわからないんですが、あまりコンクリートみたいなのでびっしりでやらないほうが、自然のままで、先ほど言われたように、土が最近珍しくなっていますから、そういった意味の自然の部分を残せるような、そういった形で固めないほうがかえっていいんじゃないでしょうか。","respondent":"岩田管理工事課長","answer":"委員のおっしゃるように、できるだけ土の部分を多くとってあげるように配慮をしております。","voiceIndex":18,"id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"維持管理費用で、都が平成１３年度１００％予定していたのは１億9,０００万円で、都が負担する５０％送水を引いた額が2,９００万円という、ここの仕組みがわからないんですけれども、どうしてこうなったのかということ。それから、目黒川をきれいにして、区の計画で、あそこ全体を遊歩道と合わせた、水の何とかというのがありましたね。その辺の考え方についてお尋ねしたいんです。","respondent":"北村下水道河川課長","answer":"この放流量を買ってでもという形で増やすということになりますと、費用負担の問題ですとか、場合によっては新たな設備投資が必要になるというようなことも想定されますので、非常に難しいところではありますけれども、いろいろ都のほうでも。","voiceIndex":29,"id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"おそらく東京湾の水をポンプアップして、それをやるとなると、この比ではなくなってしまうと思うんですね。だから、そのことを考えれば、ある程度費用負担して、目黒川をきれいな水にするというのは、追求して、研究していただきたいと思います。それから、これは落合浄水場でしたよね。そこの水そのものはもっと増やすことができるんですか。どっちなんでしょうか。","respondent":"北村下水道河川課長","answer":"しかしながら、これは落合処理場の放流というのは神田川に流していますので、神田川水系から城南三河川のほうへの、難しい言葉で言いますと、流域変更という形になりますので、その辺の影響がない範囲内で今取り組んでいるという形ですから。","voiceIndex":31,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"いろいろな必要性、あるいはつくらないほうがいいとかというのは別に置いておきまして、何点か質問したいんですが、一つは、道路公団そのものの見直しを、統合するとかというのを今やっていますね。それは、都市再生の柱の一つですから、そのことで止まるということはないと思うんだけれども、その辺の影響はないのかというのが一つ。その２点をお聞きしたいと思います。","respondent":"伊佐都市計画課長","answer":"道路公団の見直しの影響ですが、今の段階で首都高速道路公団でどうだという判断はできないということで、３公団と本四公団の見通しの動向については、注視してまいります。","voiceIndex":38,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"目黒川は昔から湿地帯みたいな、川のあれで、非常に地盤が弱いと。それから、首都高速は本当にカーブが多くて、地方から出てきた人は運転できないですってね。それほど、だって、カーブを曲がったところに駐車していて、車が故障したりなんかしたら避けらない。だから、その点でどうかなと思って質問をさせていただきました。これは東京都のものなので、とりあえず今日はこの辺にしておきます。","respondent":"伊佐都市計画課長","answer":"支持層、固い層の中に、ある程度厚みを確保した上で、各箇所を設定しているというふうに聞いております。そういう意味での固い層の中をシールドトンネルで掘削しても、支持杭への影響は出ないものと考えているという説明をいただきました。","voiceIndex":40,"id":"exchange-010"},{"speaker":"沢田委員","kind":"意見","question":"これは後でまた、決算特別委員会もあるので、そちらに譲りたいと思うんですけれども、支持層の部分でボーリング調査は一切行っていない。ただ、こう言ってもしようがないので、今日のところはここまでにしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-011"},{"speaker":"上山委員","kind":"質問","question":"ちょっとお尋ねなんですけれども、今回はまちづくり事業部の所管ということでやっておられると思いますけれども、今課長からありましたけれども、住民の皆さんから、商店街云々かんぬんと出されたという話も、そういうこともあったということをいただきましたけれども、同じことを繰り返すつもりはありませんが、特に所管が違うかと思うんですけれども、まちづくり、あるいは商店街の問題で言えば。","respondent":"中島街路事業担当課長","answer":"連携の問題ですけれども、私どもこの住民説明会の後、合計６回説明会を実施しています。その説明会で、産業振興課長、それと担当の係長がすべて出席しています。","voiceIndex":48,"id":"exchange-012"},{"speaker":"上山委員","kind":"質問","question":"これまで６回、きめ細かく商店街の関係でやってこられたということで、その点では評価もしたいわけですけれども、今後のことですけれども、道路との関係で言えば、いよいよ２６号線も完成して、そういう関係での急いだということで説明もありましたし、前回、同僚議員が質問をしておりましたけれども、渋滞の見通しというのはなかなか難しいと思うんですけれども、この前の答弁では。","respondent":"中島街路事業担当課長","answer":"渋滞の関係ですけれども、私ども数年前、実際の予想のシミュレーションをしています。それについては、はっきり整備後、あるいは２６号線開通後の交通量を調査していますけれども、その時点でも１６３号線が開通すれば渋滞が改善されるという数字が出てあります。","voiceIndex":50,"id":"exchange-013"},{"speaker":"横山副委員長","kind":"質問・要望","question":"それが長年にわたって放置されてしまう。ですから、そういった替地というか、換地については回転を早くというか、そうして、商店街が生き残っていくような施策をやっていただきたいと思います。そういう部分、特に商店街という、現在あるそれを育てていこうという部分で、商店街の方々もそういった部分で団結しているわけですから、進めるからには、そのぐらいの気構えで進めていただきたい。","respondent":"中島街路事業担当課長","answer":"これを完了させるためには、地元の計画線にかかってくる方のご協力が不可欠になるわけですけれども、実際私どもの、今回説明会等をする中で、商店街を形成していますので、空き地について、変な形で放置しておくと、イメージというんですかね、お客様にとっても。","voiceIndex":52,"id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"１点だけ。そういう気持ちと、やっぱり何とかしたいという気持ちも相当強いと。とても７年ではいかないと思うんです。２６号線だって、１件が長期間にわたってＯＫしないために、ずっと待っていた。ところが、先ほど示されたこれで、まちづくり協議会の要望があるので、今後検討しますと言いながら、具体的には来年の４月、５月で用地説明会をやり、８月だったのを、５月から用地買収の交渉をやる。","respondent":"中島街路事業担当課長","answer":"先ほども申し上げましたけれども、１６３号線につきましては、街路事業と並行してまちづくりについても考えていきたいということでございまして、実際、先ほどまちづくり協議会の設立するための勉強会を開きたいというようなことが、参加者の発意でございましたけれども。","voiceIndex":54,"id":"exchange-015"},{"speaker":"沢田委員","kind":"意見","question":"だって、用地買収で、５月から実際に、ここは幾らというふうにやっていくわけでしょう。ところが、住民の人たちは、その土地を提供すればもらえる床面積がどれぐらいで、あるいはあとどれぐらい足せば１階に店舗、上に住まいができるかということと、じゃ、用地買収単体でいけばどうかということを、両方案を出して、どっちがいいのか。これには相当時間がかかると思います。答弁は結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-016"},{"speaker":"辻委員","kind":"質問","question":"なくなってしまう人たちというのは、自分の家がなくなったときに、残らないわけですから、その人たちが次にそこで商売をやるというわけにいかないですね。残った、１軒丸々としている。その裏側で残ったところは民家ですからね。１２ｍとか、あるいは１５ｍから２２ｍに広がった後の３ｍは歩道が入っているわけですから、それは非常にいいことですけれども、商店として考えれば、ちょっと。","respondent":"中島街路事業担当課長、佐藤委員長、田村住宅課長","answer":"私ども先ほどからご説明しておりますけれども、今回の１６３号線の事業につきましては。ほかにないようですので、本件の報告を終了します。実施機関としましては、まちづくり事業部１６班、３２名編成でやっておりまして、区内の荏原、品川、大井消防三署と共同でやっております。","voiceIndex":57,"id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"待望していた西五反田の荏原市場跡地の募集なんですけれども、だんだん期待していたのがしぼんできちゃったんですけれども、全体の状況で聞きたいんですが、８７戸を建設をして、そのうち３７戸を西大井分にして、今回１２戸を募集するということですが、その残りはどうなるんですか。","respondent":"田村住宅課長","answer":"３７戸は大井伊藤町住宅の建て替えということと、今回の東京都の都営住宅で新築の募集が１２戸ということです。それ以外に品川区としては地元割り当てということで、１１月に予定しています。","voiceIndex":67,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"西大井六丁目の都営住宅の建て替えの受け皿というか、これは地元割り当てだというのは分かるんですけれども、それにしても、あそこに入りたいと首を長くして待っていた人が、非常にささやかになって、ちょっとがっくりしているところもあるんですけれども、西大井の３７世帯は、一時移るけれども、また西大井に戻りたいだとか、あるいは移りたくないとかという部分になると。","respondent":"田村住宅課長","answer":"大井伊藤町の関係ですと、これから基本設計、実施設計をして、建て替え後の計画が来年の２月頃に大枠ができますので、その時点で大井伊藤町の現居住者に、建て替え後、仮移転して、やっちゃ場から戻るのか、あるいはやっちゃ場のほうに住むのか、それをご本人の話をその時点で。","voiceIndex":69,"id":"exchange-019"},{"speaker":"沢田委員","kind":"質問・要望","question":"西大井六丁目の人をやっかい者みたいに扱ってはいけないというのは分かりますけれども、ただ、もし六丁目の方がまた戻った後は、本来的には地元割り当てで３７戸を実質取っているわけですから、東京都と大いに頑張っていただいて、地元割り当てとして募集をできるように頑張っていただきたいということを要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3702#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":35310,"voices":83}},{"id":"h13-20010926-9","meetingId":"h13-cm09","date":"2001年9月26日","dateIso":"2001-09-26","committee":"文教委員会","time":"午前１０時０２分～午後１時１６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"その町工場のおやじさんの話を聞いて、子どもたちも非常に感動した記憶があるので、そのあたりも含めて、どういうふうに進められているのかを質問したいと思います。","respondent":"青木指導課長","answer":"お手元の資料集ですが、５６ページをお開きいただければと思います。そこには、移り変わる産業の交通ということで、品川区の商業や、工業といった内容についての説明が書いてあるわけですけれども、とりわけ製造業につきましては、６０ページから出てあります。","voiceIndex":3,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"そういう点で私は申し上げたことなんです。具体的には体験学習といういろんな、商業の場合は割と入りやすいんですけれども、工場の場合に、そこで物をつくるというのはなかなか難しいんですけれども、体験をした、例えばその方々に来ていただくとか、そういうふうな地域の工業、特に製造業の点についても理解を深めるという点では、その辺のところをもう一遍伺います。","respondent":"青木指導課長","answer":"今委員ご指摘のありましたように、地域のそうした優れた技術というものも、子どもに紹介するという時間も今後増やしていきたいというふうに考えております。","voiceIndex":5,"id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから、総合的な角度で、たまたま製造業が厳しいからこうだという単純なところではなくて、子どもたちの地域的なまちの中でのそういう取り組みにも係わっていくと思いますので、ぜひそういう点ではいろんな角度で研究をしていただきたいというふうに、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"せっかく副読本を見せていただいたので。この中で、学習活動例というのがありますけれども、大体５時限ぐらいの時間なのか、社会科の先生が取り上げて、これを実際に使ってやられるのか。ちょっとお聞きいたします。","respondent":"青木指導課長","answer":"これは社会科の時間に、それぞれの教員がこの冊子を自分たちの指導の中で、どういうふうに組み入れて指導をするのかという計画を立てて、その学習の活動例というのを生かして、計画を立てて指導をしているところです。","voiceIndex":8,"id":"exchange-004"},{"speaker":"山路委員","kind":"質問・要望","question":"そこが大事だということをお聞きしまして、今では神戸のトライやるウィークというのがはやりましたね。今ではどの学校も当たり前にやっていますけれども、そういう意味で、生徒の好きな、将来目指したいという、このポイントを進路指導で外さないように指導をしていただきたいと思いますけれども、その辺は的確にできているかどうか、ご説明をいただきたいと思います。","respondent":"青木指導課長","answer":"委員ご指摘のとおり、そのように今指導をしています。","voiceIndex":10,"id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"いろいろお聞きしましても、体験してよかったと。豊橋市のいろんな体験を聞いたら、地元の産業に興味を持った生徒が非常に多かったんです。もしくは、先ほどからの質問で、中小企業のお子さん、親の跡を継ぐんだということで、いろいろと研究をして、またほかの体験をして、自分の将来の仕事に生かしたい。そういう両面で効果があると思いますので、どうぞこの点につきましてはよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-006"},{"speaker":"山路委員","kind":"質問・要望","question":"３点目は、学校選択の判断材料、判断方法といいますか、お国柄、地域柄、違いはありますけれども、何らかの形で品川区にも今後生かしていける、参考になることだと思いますので、この辺もお願いしたい。４点目に、アメリカの教育委員会と学校の関係と役割ということについても調査をしていただければと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"高星委員","kind":"質問","question":"例えば私が小学校の子どもだとします。そのときに、「日本は憲法で戦争を反対しているんだよね。そこのところになぜ日本が行くの」と聞かれたら、今の教育委員会はどう教えるか。中学生、高校生ぐらいは幾らでもごまかしはきくと思うんだけれども、小学校の、それも目が輝いている子どもたちに、日本は何で戦争に反対しているのに、アメリカの戦争を手伝うんですかと言われたら、何と答えたらいいかと思って。","respondent":"青木指導課長","answer":"大変難しい問題だと思いますけれども、すでにいろんな現場で、教員と、子どもたちのほうへ、そういう問題についての話というのはあるかと思いますけれども、テロということに対しての問題については。","voiceIndex":24,"id":"exchange-008"},{"speaker":"高星委員","kind":"意見","question":"現状では今の答弁しかできないのかなと思う。現在ではそれ以上なかなか、いろんな考えがある中で、それを飛び越えて前へ一歩進んだ答弁は、指導課長のところではなかなか難しいのかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-009"},{"speaker":"桜井委員","kind":"質問","question":"狂牛病のほうなんですけれども、今日の東京新聞によりますと、東京都の指示が出ているようですけれども、品川区の場合の牛の入荷はどこからきているのでしょうか。この記事によると、都の食肉市場が港区にありますよね。そこの出荷、入荷の登録業者との対応をしているようですけれども、区のほうはどこからきているのか。","respondent":"久保田学務課長","answer":"ただ、先ほど申し上げましたとおり、牛肉の使用というのは、学校給食においては数少ない状況ですので、そういう点では今のところ、念のためということで、ほかの肉に切り替えて対応をしているというような状況です。","voiceIndex":31,"id":"exchange-010"},{"speaker":"桜井委員","kind":"質問","question":"その関係というのは、保護者へのお知らせというのは、その辺はどうなんですか。","respondent":"久保田学務課長","answer":"ただ、いろいろ細かいところについては、それぞれ問い合わせがあれば、学校のほうで答える。我々のほうには今のところそういう問い合わせは１件もございません。そういう形で対応をしてまいりたいというふうに考えております。","voiceIndex":33,"id":"exchange-011"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望ですけれども、当日はもちろん具体的に現地でご説明いただくんですけれども、前もって予備知識として概要みたいなものはいただけるんでしょうか。","respondent":"事務局","answer":"先方から資料はいただいてはおるんですが、今資料を調整中ということで、当日にしてくださいと。は建物のパンフレット的なものしかいただいておりませんで、まだ皆さんにお見せしてもそれほどの感じでもないんじゃないかと思います。","voiceIndex":43,"id":"exchange-012"},{"speaker":"桜井委員","kind":"質問・要望","question":"希望として、一定程度の時間の制限があるので、ある程度できるところで資料を見せていただきたいと思います。事業内容について、できればお願いしたいと思います。","respondent":"事務局","answer":"ですから、当日に間に合わせるです。手元にもともとそういうものがあれば、そういうものをいただけるんですけれども、手元にないということでございました。","voiceIndex":45,"id":"exchange-013"},{"speaker":"山路委員","kind":"質問","question":"各委員が報告書を出して、正副委員長でまとめていただくという形ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-014"},{"speaker":"桜井委員","kind":"確認","question":"個人視察ではないわけですから、委員会としての視察ですから、それぞれやってきて、実際に現場を見て、いろいろな経験をしたことを委員会で、例えば時間を１時間なら１時間とって、報告をして、自分はこういうふうに感じたというところで、そこで委員会としては、こういうふうに全体として確認がされることもあるし、また、それぞれ今後に生かす面があると思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-015"},{"speaker":"松澤委員","kind":"意見","question":"今の話の中で、感想文という形でいいのかということがありますね。それに是も非もあると思うんです。それなら、今桜井委員が言ったように、こういう中で１時間なら１時間述べ合って、こういうところはよかった、これはこうだったよというのを、委員会の中で話をしたら、それは視察の報告になっているんだよと。それも一つだと思うんです。私は、直感的にはそれでいいような気がします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-016"},{"speaker":"川西委員","kind":"提案","question":"私は昨年は建設委員会にいまして、分担制でやりました。委員会では行くんだけれども、議員活動の一つで、その一人ひとりがどういうふうに次の委員会活動、あるいは議員活動に生かせるか。そういう意味で、委員長の提案で、今回は並列にそれぞれ感想を列記して、出するというところで参考になるのではないか。議論しても、一致点はないと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-017"},{"speaker":"桜井委員","kind":"意見","question":"もう一つ、例えばそれだけでは委員会としては不十分で、私の感じとしては、どこどこへ行ったとか、いわゆる事実ですよね、どういう視察をして、どこを見た、どこを視察して、どこと懇談したという、そこの時系列は正副委員長のところでやっていただくというところで、簡単な、こういうテーマで、こういう懇談をしたというのは記録として残して、それで委員会としての、そこでいいんじゃないかと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-018"},{"speaker":"高星委員","kind":"質問","question":"したがって、みんなそうやって行くわけですから、そこに行ったときに、説明を受けたりして、皆さんと相談しながら、ここのテーマについては、こういうことだったねということで、ある程度まとめ上げる努力を、正副委員長にそこでちょっと骨を折ってもらって、取りまとめをしていただいて、それで総括的に、記録に上げていかなければいけないなという気がする。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-019"},{"speaker":"高星委員","kind":"意見","question":"そういうことじゃなくて、僕が言ったのは、現場を見てのところの、そこで議論をしたものを大事にしたい。極端なことを言ったら、あまり参考にならないんじゃないか、品川区のほうがいいよというようなところもあるかもしれないし、そういうのを羅列して、生で議論をしたものをとっておくというのが大事なんじゃないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"意見","question":"その前に委員長のほうで吟味なさったものもありますけれども、私はそれでも十分対応できるのではないのかなと思います。議論をぶつけるのはいいと思うんですけれども、まとめることはないと思うし、自分はこう思いました、これがよかったと思ったから参考にしたいという、それが結論で、皆さんが出せばいいんじゃないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-021"},{"speaker":"川西委員","kind":"意見","question":"別に反対しませんけれども、物を書くというときには、もう一回いただいてきた資料を読み直すんですよ。それが次から次へと、予定して行ってきますでしょう。やはりおさらいというのが、３行書くのでも、一応全部目を通しますから、見てきたのと、資料とが一致するということで、いいなと思います。","respondent":"事務局","answer":"調査項目に対する記述は、正副委員長が調整するところは一致していると思います。は感想をレポートにするのか、委員会の中で議論をして、その委員会記録を貼付するのかというところで、今お話が二つに分かれていると思います。そこのところをおまとめいただければと思います。","voiceIndex":63,"id":"exchange-022"},{"speaker":"松澤委員","kind":"質問","question":"意見が分かれるようでしたら、委員会ですから、正副委員長にお任せして、委員長の考え方で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4418#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":13893,"voices":66}},{"id":"h13-20010926-5","meetingId":"h13-cm09","date":"2001年9月26日","dateIso":"2001-09-26","committee":"総務委員会","time":"午前１０時０４分～午後０時１２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"国際交流の事業のところで、こっちから行ったり、向こうから来たりというのがあるんですけれども、費用というのはどういう基本的な考え方になったのかということ。今回も２００名なので、相当費用がかかっているんじゃないかと思うんですけれども、今回は東海道４００年祭との絡みもあって、通常のと変わってくるのかなと思うんですけれども、その辺のところはどういうふうになっているか。","respondent":"太川総務課長","answer":"は公式訪問団の宿泊費、歓迎会、友好協会主催のさよならパーティー、それから伝統工芸そのほかの出演者の分等々を含めまして３,８００万円を経費として予定しているものです。","voiceIndex":8,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"今回１０周年ということで、５周年のときは２３０名と書いてあるんですけれども、行ったり来たりでやっているんですけれども、規模の考え方というのは向こうがこのぐらい来ると、やっぱりこっちもこのぐらいというふうなことになってくるのかもしれないんですけれども、その辺の規模の考え方というのはどういうふうになっていますか。","respondent":"太川総務課長","answer":"やはり、その辺のバランスというのは考えていかなきゃいけないものだと。ただし、経費につきましては、それぞれの国の負担になりますので、そこのところは多少の差異は出てくるかなと考えております。","voiceIndex":10,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"私も、基本的には周年行事ではなくて、日常的な交流が中心だろうなというふうに思うんです。かなり規模が大きくなって、これからどんどんこういう感じでいくと大変だなという感じがしたものですから質問しました。では、そういう方向で、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"一般区民の方との交流となると、２０日、２１日の演奏会ですとか、東海道４００年祭の一環の中での交流が持てるんですが、さらにより多くの区民の方々、あるいは我々議会側というか私自身は、例えば公式訪問団の方々との交流なども図れたらなという要望があるんですが、一般区民の方々との交流というものが全体を見回すと少ないように見受けられるんですが。","respondent":"太川総務課長","answer":"やはり品川の伝統工芸の部分で伺う予定になっておりますのが、草木染の染色と木工関係だったと思いますけれども、やはりそういう職人の世界を見てみたいという要望が強うございまして、それらにつきまして時間の許す限り日程の中には組み込んで見ていただくようにしております。","voiceIndex":15,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"一連の行事の中で、私自身も積極的に交流を図っていきたいなと思うんですが、例えばオンディーヌの方々などは、一方日本の音楽に大変興味があるのではないかなという、想像ですけれどもありますので、日本の工芸もぜひ親しんでいただきたいんですが、音楽的なものも含めて交流を深めていただけたらなという、これは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"三上委員","kind":"質問","question":"せっかく分散演奏会がいろんなところで行われる中にあって、子どもたちだけの交流ということで終わらせるのか、それともそういった意味で、関心を持っている地域の皆さんにご参加くださいと学校が呼びかけをやってもいいのかなということもあるし、地域でということになれば地域で歓迎するということに、本当にお金の多寡ではなくて、何らかのもので地域の皆さんがせっかく来ていただいたということで。","respondent":"太川総務課長","answer":"地域での部分ですが、これにつきましては、ここは私のほうも友好協会に話をしてまいりますけれども、基本的には学校でやる部分、地域の方がノーということではないと思いますので、その辺につきましては多少の日程的なものがありますので。","voiceIndex":18,"id":"exchange-006"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、そういう意味にあって広く一般区民の皆さんが、品川区とジュネーヴとやっているんだということをまず認識してもらうということが大事なことであって、そういう形で全く接触を持たない人たちも関心を持てるような機会というものを、このジュネーヴだけに限らずニュージーランドにしてもポートランドにしてもあると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"北野委員","kind":"質問","question":"これはどの場所に設置して、だれが押すんですか。発見した方が押すとか、そういうところはどういうふうになっているのかお聞きしたいんですけれども。","respondent":"桑村政策担当課長","answer":"この絵を見ていただきたいと思うんですけれども、非常ボタンがあります。今のところ東京都の考え方としては２カ所と言っておりますが、一つは事務室につけていただきたいと思います。","voiceIndex":29,"id":"exchange-008"},{"speaker":"塚本委員","kind":"意見","question":"給与の適正化ですけれども、これは独自の諮問委員会をつくってやっているんだろうと思うんですけれども、そこのところを確かめておきたいと思います。適正化というと、その辺のニュートラルですけれども、下げた理由があるのかどうかということを知りたい。あるいは、待遇の考え方を現状に合わせていくかという、等級等の考え方を、そういう事例があるかどうか確かめたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-009"},{"speaker":"三上委員","kind":"意見","question":"職員の残業というのか、今は不規則勤務という部分にしてもこれがどういうふうになっているのかということです。品川区の場合だったら、完全に保育園の場合だと勤務手当そのものが通常勤務という形で時間差を取り入れてやって、それで１０時までの延長保育をやっているわけですけれども、そういったことについての時間的な部分について、その点はどういうふうに行っているのかということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-010"},{"speaker":"北野委員","kind":"質問","question":"組織・機構の見直しということで、組織がどういうふうに見直されていったかというのをお伺いしたいなと思います。それから、透明性を確保するということで、情報公開とか市議会の公開というのもありましたので、それについてもどういう進め方をしているか伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"役人というのはやっぱりコストに追われて仕事をするということがあまりないですから、どうしても遅れがちになってしまうということがあります。佐賀市の場合は、そういうところ、いろんな技術のギャップができてくるところを何か工夫していらっしゃるかどうか。品川区の場合も、どうしているのか教えてほしいけれども、とりあえずお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-012"},{"speaker":"田中委員","kind":"確認","question":"人材育成に関しては男性職員も含めて、研修体制をどういう形でやっていくのかということ。は塚本委員がおっしゃられた部分で、公共事業再評価システムを構築したということなので、この内容について。それが入札の改善につながったのかどうかだとか、まずシステムそのものについてより詳しく、積算のことも伺っているかと思いますが、特に聞きたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"職員の削減、定員管理の適正化等も実態と考え方ですね。はここにもスクラップ・アンド・ビルドと書いてあって、いろいろ行革をやっていく上での市民からの市政の意見の反映とか、仕組みがどうなっているかということ。もう一つが、情報公開の実際ですね。これは考え方と、まだやったばかりなので、この辺の実際のところを伺ってみたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"１０年前にやったとか、そういうところはいくらでもあるわけで、実際話を伺うと何年前にやりましたというような報告がありますけれども、新しい地方分権の流れの中でどういう課題を踏まえて合併しようとするところを見たいということが一つ。その中で、合併協議会の本音のところの主な論争点をお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"前のときもちょっとお願いしていたんですが、唐津市の競艇場があるんですね。そこの今の現状だけでも聞かせてもらえるように付け加えていただけませんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"麻生総合研究所というのは……。何を質問しろと言われても、これはすごい情報量と言いますか、すごいことをやっているなということなんですけれども、基本的にはこれを我々は今勉強したよということをメッセージを出しておいて、そこからお聞きしたほうがいいんじゃないかなという気がします。","respondent":"本多委員長","answer":"本当に特色ある取り組みですので、我々も事前に勉強会を開いてやっているところを先方にもお伝えして、現地で本当に実り多い調査にしていきたいと思いますので。","voiceIndex":59,"id":"exchange-017"},{"speaker":"土井副委員長","kind":"質問","question":"その人のポイントがなければ、この人は集まってこないわけで、さっき言った守旧派じゃないけれども、派はいろいろあるけれども、思いはあるけれどもというけれども、ここに管理委員会につなげた人がどこのだれなんでしょうかということをまず聞きたいと思いました。そしてつながったんだから、今度はつながった人が来てくれるんですから聞くことはたくさんあるんじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"私も同意見で、すべてを学びたいという思いで参加したいんですが、その前提としての本来自主的な資料収集しなくてはいけない部分なのかもしれないんですが、品川区と福岡市の大きな違いというのは、品川区は特別区であって、福岡市は政令指定都市であるということの、福岡市ではできるけれども、品川区ではできないことだとか、そういった政令指定都市と特別区の比較できる内容を前提として知った上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"意見","question":"そうすると、例えば普通ですと経費をこのぐらい削減するだとか、収入をこのぐらいアップするんだとかという、大体そういう目標がくるんじゃないかなと思うんだけれども、そういう目標があんまり見えないので、この資料を見ただけなのでよくわからないんですけれども、ある意味では最初に目標ありきではなくて、その辺のやり方みたいな……。","respondent":"中尾根企画部長","answer":"そういう意味では、当初からどういう目的を考えて、何％これをやろうというような、今までやっているような手法は取っていないということですので、そこに問題がある。","voiceIndex":66,"id":"exchange-020"},{"speaker":"三上委員","kind":"質問・要望","question":"市長就任後に取り組みを始めたということですから、市長の経歴がどういう方だったのかということについて、ここらあたりをまず最初にしっかり学びたいなというふうに思います。組合が「うん」と言うかどうかということの話になってくると、どういうような形で組合が教育をする形になってきてたのかということについて、組合の状況あたりを教えていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-021"},{"speaker":"北野委員","kind":"質問","question":"経営管理委員会の中での作業部会というところが、職員の公募ですよね。どういう方たちというか、どういう職種の方たちがなっていらしているのかというのと、どういうことで選考したのか、ちょっと細かいんですふうにお伺いしたいと思います。この結論を出すのは、全部経営管理委員会で報告書をまとめたのかどうかというので、職員の係わり方もお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"去年、区民委員会で田中委員と一緒に行きましたけれども、大変有意義で、特に特徴的なのは、現地の活動家と懇談をしたということなんです。分担制にしますと、やはり会派の問題が出てきたり、それぞれがそれぞれの方向を出すのは構わないですけれども、分担制はいかがなものかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-023"},{"speaker":"土井副委員長","kind":"質問","question":"したがって、やっぱり一度は全員の委員会みたいなところで若干の意見交換的な意味も含めて、まとめをしたものをまとめるという形にしていったらどうだろうかというふうに思います。あった事実は事実ですから、淡々と書くだけですから、そこにはまるのは何なのかということなので、分担すると片方の意見だけが載ってしまうんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、私としては、やっぱり各自いろいろ考え方、受け取りも違うので、自由に書いて、それを寄せ集めるという感じでもいいのかなという感じがするんですけれども。最後から２番目の案が、一番感じたことを素直に自由に書いてもらうというのがいいかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-025"},{"speaker":"田中委員","kind":"意見","question":"私も大体皆さんと同意見で、私も昨年区民委員会に参加しまして、昨年の方式はいい報告の仕方だと思いますので、分担制ではなくて、個々の委員の方々の感想なり評価を口頭でお伝えをし、それを正副委員長のほうでまとめていただくような方式がいいかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1560#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":36577,"voices":80}},{"id":"h13-20010927-13","meetingId":"h13-cm09","date":"2001年9月27日","dateIso":"2001-09-27","committee":"清掃・リサイクル特別委員会","time":"午前１０時１４分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、説明していただきまして、そして１０月１２日までという、ここのところなんですけど、今課長の説明では、東京都のこの審議会の、一定程度のまとめがこの行動計画にまとめられて出てきて、都民、区民の意見もその日までに聴取していくという、そういうレベルにあることがわかったんですけど、この行動計画と品川区のごみ行政、そこの関係が、どういうふうに私たちが認識をしていったらいいのかというのが。","respondent":"中山清掃リサイクル課長","answer":"したがって、かなりその各区で考えている施策、品川区なら品川区の施策もにらんだ上で、例えばそれに全くもとるような方針が出れば、それは区として、それはおかしいんじゃないかということを申し入れていくということで、先ほど区民、都民の意見も聴取するですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"そういう、この内容の行動計画について、区としても実際清掃行政を行っている立場から、独自の計画もやり、そして推進しているわけで、拘束されるものでもなく、また意見もしっかり述べていく協議機関があるということなので、一定程度安心はするんですけれども、安直にやっぱり東京都のこれを受けて、一つ一つの条件について、ああだこうだというふうに、変更というのかしら、ここはしないんだという。","respondent":"中山清掃リサイクル課長","answer":"最初のご質問は、先ほどのお答えと繰り返しになろうかと思いますけれども、いずれにしましても、区の施策の方針に東京都の計画が、たがになるというようなことがあってはならないわけであって、そういうことは基本的にはあり得ないし。","voiceIndex":7,"id":"exchange-002"},{"speaker":"土井委員","kind":"質問","question":"今、この計画の効力というか、力が及ぶのは、我々のところは我々でやっているんだから、そんな、あれされることはないんだよという意味のお話があったと思うんですが、私、ちょっとこれを見ながら非常に思ったのは、一番最後のところなんですよね。これなんですけど、一番最終のページの前のページですね。ここが極めて大きいと、私は思ったんですけど、いかがですか。","respondent":"中山清掃リサイクル課長","answer":"区の清掃工場の現状を考えましても、一般廃棄物の排出量の見込みからすると、大変この工場の整備をやっていくと、かなり今まで、今後の地域処理というのにかかわるんですけども、安定的処理をやれるように整備していくということを考えてくると、産業廃棄物に比べると。","voiceIndex":9,"id":"exchange-003"},{"speaker":"土井委員","kind":"質問・要望","question":"その問題がいっぱい内在しているように思えるので、変な意味で、うがってとらえれば、何か衣の下によろいが見えるような計画にも見えるし、あるいは、もっとしっかり考えれば、我々が独立をして、国や都なんかより分権をしっかりやっていくとするならば、我々も処理してやらなければいけないんだという自覚を求める中身でもあるということですから。","respondent":"中山清掃リサイクル課長","answer":"ですから、それはそれで十分東京都と連携をとる必要はあるわけですけれども、この計画によって、まさにいわゆる基礎的自治体として運用を始めていった施策に対して、今まで以上に、東京都が移管した事業まで権限を持って運営できるやの意識ではないと考えていますが。","voiceIndex":11,"id":"exchange-004"},{"speaker":"土井委員","kind":"質問・要望","question":"今つくり替えるときに、じゃ、でっかいのをつくっておかなくてはいけないんじゃないのという話になるかもしれないわけですよね。だから、そこのところは、やっぱりよく情報収集も含めてやっていただくとともに、財政的なところなど、技術的ばかりではなしに、財政的なもの等についても十分見計らって対処していっていただきたいなということを、一応この段階じゃ、それしか言いようがないので、要望も含めて。","respondent":"野本環境清掃事業部長","answer":"なおかつ、公害の排出規制が非常に厳しくなってきている。ですから、東京都ですとか、１３大都市と言われているようなところを除いては、一般の市町村の焼却炉では、従来の感覚では燃やせなくなりつつあると。","voiceIndex":13,"id":"exchange-005"},{"speaker":"須藤委員","kind":"意見","question":"この計画のメンバーが有識者云々であるというんだけど、そういうところがどういうメンバーの方なのか。それから、この立ち上がった時期は、いつ委員会なら委員会が立ち上がってきたのかということを聞きたいと思います。","respondent":"中山清掃リサイクル課長","answer":"部会長以下１３名という形で検討しているものです。そこで、この部会が設置されましたのが、平成１２年１０月１６日に、今回の諮問と、この廃棄物行政のあり方の検討部会の設置ということが出されておりまして、以降、この特別部会として検討を行ったのが、現在まで９回。","voiceIndex":16,"id":"exchange-006"},{"speaker":"須藤委員","kind":"意見","question":"そうすると、一般区民からの意見を聴取したという話がちょっと出たけど、それはどんなふうにして、一般区民のどうのというのは、相当難しい問題だろうと思うんだけど。いわゆる品川区の広報に、こういうことがあるので、皆さんご意見を、とやるのとか、その意見を聴取するというのはどういうことなのか、聞きたいと思います。","respondent":"中山清掃リサイクル課長","answer":"ここ二、三年でしょうか、いわゆるパブリックコメントというふうに国が言い始めてから、意見を聴取するという、いろんな計画の中間段階で聴取するという手法がいろんなレベルで出てきておりますけれども、基本的には、インターネットのホームページで公開をして。","voiceIndex":18,"id":"exchange-007"},{"speaker":"須藤委員","kind":"質問","question":"それはいいんですけど、この委員会で、先ほど部長がおっしゃったリサイクル委員会、広域的委員会、自区内処理、いろんな大きな問題がいろいろと出てきていると思うんですよね。もう一つ、今日、午後から視察に行くんだけど、これはどういう意味合いで、委員長、視察を考えられたのかなと。今日の午後の視察は、各委員からこういう視察要請があったんですか。ペットボトルですとか。","respondent":"高木委員長","answer":"これは、この委員会として、いろいろなところで仕事をしている部署、部署の認識をできるだけ高めていかなければならないということで、こういう場所を正副で検討いたしまして決めさせていただいたと。","voiceIndex":20,"id":"exchange-008"},{"speaker":"須藤委員","kind":"意見","question":"はい、結構です。視察もそういうことで行くことになろうと思うんだけれども、品川区議会、清掃・リサイクル特別委員会として、方向性がある程度あって、じゃあ、こういう人も見に行く必要があるよという形でいったのかなと思ったので、特にその方向性が云々と、正副で決めたのではなくて、参考にこういう状況を視察してみましょうということですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"意見","question":"先ほど、部長のご答弁の中で、廃棄物の処理が焼却、埋め立て中心のところから、性格を一変して、リサイクルを進めていくんだというお話をされたわけですけれども、その２８ページのところで、ちょっと心配な１点が入っていたので、ぜひお願いしたいなと思うのが、「廃プラスチック類のサーマルリサイクル等の促進」というところで、ここのところで、発生抑制やマテリアルリサイクル、この言葉ですけど。","respondent":"中山清掃リサイクル課長","answer":"ところが、プラスチックのリサイクルという話で、なかなかこれが全国的にも進まないのは、プラスチックというものを考えたときに、日用品のようなもので、完全にプラスチック単体で利用されていればいいんですが、一番多い部分というのが。","voiceIndex":23,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"そこで、区のほうの考えで、都の押し付けるものじゃないという話は先ほどから伺っておりますけれども、この辺のサーマルリサイクルあたりは、区の視野に入っているのかどうかっていうのを改めてお聞きします。","respondent":"中山清掃リサイクル課長","answer":"ですから、今後どうしていくかは、まさに住民の方、あるいはいろんな場面での議論を受けながらですけれども、はなから視野に入れないということではないという認識は、少なくとも私は持っております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区にやっぱりいろんな角度で検討もしてほしいな、意見も載せていただくことが大事だと思います。そういった意味では、やはりいろんな情報提供もしていただきたいし、またその辺をどう考えていくのかという、いろんな論議をやっぱりする場をたくさん、これからも持っていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"北野委員","kind":"質問","question":"できるんでしょうか。タイムスケジュールは。","respondent":"中山清掃リサイクル課長","answer":"これは、いずれにしてもこの計画自体は、法に基づいて都道府県が策定することになっているものですけれども、この計画ができないから、各それぞれの廃棄物処理の施策が展開できないわけではございませんので、逆にこのことによって。","voiceIndex":29,"id":"exchange-013"},{"speaker":"北野委員","kind":"意見","question":"それは当然、区の計画もあるけれども、やっぱり連携というのが今のところ、清掃工場は区ではないというところもあるし、いろんなところで連携が必要じゃないのかなと思うんですけれども、どうなんでしょう。","respondent":"中山清掃リサイクル課長","answer":"確かに、これは区の計画と、最初の図にもあったように、連携、調整をとっていくものですということで、意味は関連がありますけれども、実際的にこの計画は、繰り返し言いますけれども、区の施策に拘束力を持ってかかっているものではありません。","voiceIndex":31,"id":"exchange-014"},{"speaker":"北野委員","kind":"質問","question":"はい、わかりました。何度かは、主婦の考え方として、発言はさせていただいていると思うんですけれども、区は判断として、市町村の判断になるということなんですけれども、今の現状を考えた上で、考え方とかをちょっとお伺いしておきたいんですけど。","respondent":"中山清掃リサイクル課長","answer":"そういった意識も踏まえながらですけれども、この前申し上げたように、ごみの減量は非常に下げどまっている傾向を考えると、今後選択していく方策の一つというふうには、再度認識しているということは申し上げたいと思います。","voiceIndex":33,"id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"そのために、その処理経費の統一的な算出方法を提示するなどとしておりますけれども、この処理経費の統一的な算出方法というのは、もう既にでき上がっているんですか。今、検討中なんですか。いずれ、何らかの形で判断しなきゃならない時期が来るだろうという中で、２３区全体の区の流れ、傾向、今の認識、区はどう進めていくか。あるいは、どの把握されていますか。その辺、ちょっとお伺いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"２３区の雰囲気という意味では、今申し上げたような、やはり今後いろいろこの施策、制度の施策を考えていく中でコストの分析は重要だということでは、２３区を挙げて検討に入ろうということで、今、分析に入っているところです。","voiceIndex":35,"id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"各区の算出をやっているんでしょう。要するに、介護保険料そのものも各区によって負担の額が違ってますね。それは、いろいろな施設の規模によってはいろんな形で算出方法が各区によって、条件が違うというんですか、それによって介護保険の料金の額が、区ごとによって違ってきているという場合。その段階で、各区によっていわゆる金額が違ってくる。それはどうですか。","respondent":"中山清掃リサイクル課長","answer":"介護保険の場合は、サービスの質と負担という中で多分設定があったかと思うんですが、やはり同様に、区の中で行う施策、執行を見やりながら決めていくことですから、実際この辺は、今段階でどういう方向かということは、計り知れない部分がありますけれども、いずれにしても。","voiceIndex":37,"id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"そのために、場合によっては、有料もやむを得ないかなと、私個人的にですよ。それから、今日いただいたこの資料の中にあります、２７というんですか、全体でいくと３ページ目ですかね。そこで、そういうものを例えば平成１２年度の決算が既に出ているんですから、例えばその中で、平成１２年度のごみ処理の経費については、もう既に明らかにされている部分がある。その辺はどうなんですか。","respondent":"中山清掃リサイクル課長","answer":"各区の考え等がある中で、何かためにする数字みたいなものを出して、うちが安いとか高いという話が、客観的にどうなのかというところでは、調整を図りながらやっていくということで今作業しておりますから、いずれにしても、これは当然示してまいりますし、ごみの減量化の。","voiceIndex":39,"id":"exchange-018"},{"speaker":"船波副委員長","kind":"質問","question":"そういったことも検討されているんですか。","respondent":"中山清掃リサイクル課長","answer":"おそらく、個別の品目までは、鋭意検討というのはいってないというのが実態なんですけど、ただ行政で収集している一般廃棄物とその他という区別の中でいえば、今後むしろ、ここで言っているのは、事業者が、本来そのつくった人、売った人。","voiceIndex":42,"id":"exchange-019"},{"speaker":"船波副委員長","kind":"意見","question":"そういった動きも含んでいけば、家庭の中で、持っていくのをどうしようと悩む部分も少なくなると思いますけど、引き取られていった後に、品川区とか東京都とかかわりなくの環境に対して負荷が少ない方法で、本当に処理していけるかということが、今度は心配になってくるわけですけれども、それは産業廃棄物に関する重点施策とか、そういうところで検討されているのかも知れませんけど。","respondent":"中山清掃リサイクル課長","answer":"産業廃棄物の流れについて、なかなか、今、区のほうで正確に答えるのは難しいんですが、言われているのは、いわゆるマニフェスト伝票制度というのがどうも十分機能していないと。","voiceIndex":44,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"私は一番最初のときに、この中間報告のここの性格と区との関係で、どういうふうな関係にとらえればいいのかという質問をさせていただいたんですが、この内容については、拘束されるものじゃないというふうなご答弁でしたよね。一安心したんですけれども、今いろいろ質疑を伺っていて、個別のいろんな問題が出されたときに、例えば有料化の問題では、区も視野に入れていると。","respondent":"野本環境清掃事業部長","answer":"当然、これはもう有料化だとか何とかじゃなくて、もうここ数年来、１０年ぐらい言われている行政のアカウンタビリティー、説明責任の果たすべき道具の最たるものですから、これはもう、そういうこととは関係なしにきちんとやっていく。","voiceIndex":46,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういうことで区も当然とらえているよというふうなことを強く希望もするし、そういうふうなことだというふうには理解をするわけですけれども、あえて、その点については、軽々に導入すべきじゃないということをちょっと要望させていただきたいのと、意外と心配だったのは、これは拘束されるものじゃないよと言いつつも、こことここと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-022"},{"speaker":"土井委員","kind":"質問","question":"時間がないところであれですが、この前のときもちょっとお話しした、この性格は何ぞやということの部分について、どうお伝えをいただいたかということと、それから、要するに２３区清掃協議会なるものの性格そのものが何ぞやということが書いていない、この２３区の清掃協議会のパンフレットというのは、いかがなものかという部分については、どうなったんですかな。","respondent":"中山清掃リサイクル課長","answer":"したがって、協議会そのもの、一部事務組合そのものの説明がないというのは、それぞれのリーフレットにゆだねているということで、ここは２３区で行っている清掃事業及び各区ごとのリサイクルをある種共通の表現でまとめたものというふうにご理解いただければと思います。","voiceIndex":52,"id":"exchange-023"},{"speaker":"土井委員","kind":"意見","question":"それは、どういう、要するに配布基準、どこに配布されて何に使うのという。","respondent":"中山清掃リサイクル課長","answer":"配布部数が品川区、１,０００部送られてきました。","voiceIndex":54,"id":"exchange-024"},{"speaker":"土井委員","kind":"質問","question":"まさしくそういうことだと思うんですが、ですから、要するに何のためにつくるのという目的がないままにつくったんじゃ、廃棄物になっちゃう可能性があるわけですね。数量と予算と決算と、こうつながっていくようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5648#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":38867,"voices":60}},{"id":"h13-20010927-16","meetingId":"h13-cm09","date":"2001年9月27日","dateIso":"2001-09-27","committee":"街づくり特別委員会","time":"午前１０時０４分～午後４時３５分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問","question":"最初に率直にお伺いしたいんですけれども、この地域は、いわゆる通常の補助対象の地域ではないかと思うんですけれども、Ｂ－４はそうじゃないと思うんですが、一般的な中から、開発していく上で補助の対象になっている、あるいはするんだと、なっているというか、その違いというのですか、これを開発する側、あるいはする側、うめる側だとか、あるいは行政側から見て。","respondent":"南雲都市開発課長","answer":"この品川駅東口地区につきましては、これはもともとは国鉄の操車場の用地でございまして、当然従前は道路がなかったということで、ＪＲの清算事業団が区画整理事業を行いまして、道路をつくって、その後の宅地造成へ分譲したということで。","voiceIndex":8,"id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"そこら辺はわかりました。もうちょっと別な視点で伺いたいんです。もう少しちょっと、この時点、例えば以前の計画と大きく違った、あるいは変わらざるを得なかったというのがあれば、ちょっと教えていただけませんでしょうか。前に一度あったかと思うんですが。（「変わったのは工期の」と呼ぶ者あり）ええ、そうですかね。当初から動きが変わりましたね八ツ山アンダーパスの関係で。","respondent":"南雲都市開発課長","answer":"八ツ山アンダーパスにつきましては、当初の工期より大分おくれるということで、今年の７月のこの委員会でも報告していますが、その理由といいますのは、従前の権利者の方がおりまして、その方にほかのところに移っていただくということですとか、それから。","voiceIndex":10,"id":"exchange-002"},{"speaker":"上山委員","kind":"質問・要望","question":"ちょっと別のところでお伺いしたいんですけれども、今度のＢ－４地区の建物の関係でなんですが、壁面の後退といろいろ新たに条例上はきめられましたけれども、この地域は、私素人が申し上げて、いわゆる今度建てる関係で言うと、総合設計みたいな形の、そういう手法みたいなのを使うんでしょうか。","respondent":"南雲都市開発課長","answer":"それは、この区画整理事業に伴って、幅員の広い道路をつくったり、例えば公園をつくるということで、そういう環境整備等々をにらんで再開発計画で容積のアップを行っているということでございまして、この地区は、現行は人口増で４００ですが。","voiceIndex":12,"id":"exchange-003"},{"speaker":"本田委員","kind":"質問・要望","question":"参考までに聞かせていただきたいんですが、壁面の距離なんですけれども、８メートルとか１4.５メートルとか、どういうところから算出をしているのか。Ａ－１地区では１５メートル、Ｂ－１地区では１０メートル、今回の改正ではＢ－４で８メートル、品川がぐっと接近してくるわけなんですが、これはどういう計算で距離というのは出てくるんですか。参考までに教えていただきたい。","respondent":"南雲都市開発課長","answer":"壁面線の後退距離については厳密な計算式があって、それに基づいているわけではございませんが、考え方としては、駅前広場ですとか、それから幅員の広い道路、こういうものについてはセットバックの距離を広くとりまして、セットバックした部分も含めて広い幅員。","voiceIndex":14,"id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"これを８メートルにしたというのは、建物の用途から出てくる数値なんですけれども、今の話ではどうもちょっと、事業者側の用途といいますか、それによって決まってくるわけなんですか。","respondent":"南雲都市開発課長","answer":"この地区の場合に、３枚目のカラーのパースがついておりますが、このＢ－４地区といいますのは、一番端にあるということもありまして、他の建物に比べすると高さは抑えられていて、真ん中のほうが高くて周辺に行くに従って、周辺等は少し低く抑えて。","voiceIndex":16,"id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"Ｂ－１地区の１０メートルと同じく並べて何でできないのかなと、単純にこれを見ていまして、感じるんですよ。低く抑え建物の面積を広くとったということなのかなというふうに思うんですけれども、そういうことなんですか。","respondent":"南雲都市開発課長","answer":"これにつきましては、Ｂ－１地区というのは相当地区の面積が大きな区域でございまして、１０メートルのセットバックも十分に可能なんですが、Ｂ－４街区というのは規模が小さい区域ですので、やはりほかの大きい区域と同じ距離だけ後退するのは。","voiceIndex":18,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと今のところなんですけれども、高さと容積の関係なんですが、先ほどの質問で、この地域は人口で４００のところを再開発計画で７８０までふやしたということなんですけれども、まず、この高さ制限というのはどういうふうになっているんですか。","respondent":"南雲都市開発課長","answer":"それからもう１つ、道路からの斜線制限といいますか、道路からの勾配がつきまして建物の形状が定められるということでございまして、そういうものを勘案して、各事業者のほうで建物の形状を設定するです。","voiceIndex":20,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"何かよくわからないんですけれども、先ほどの質問の何で８メートルなのかという、その根拠というのがよくわからないんですが、これは要するに、全体の景観だとか、いろいろ道路からの斜線だとかの関係で高さはここまでにしかならないということで、この容積をとると８メートルだと。１０メートルはなくて８メートルになる、そういうことなのですか。私もよくわからないので、簡単に言っていただけますか。","respondent":"南雲都市開発課長","answer":"８メートルといいますのは、壁面線ということで、建物をこの線よりも道路側にはつくっていけませんという都市計画の制限でございまして、これは最小限この範囲は建物はつくれませんということなんですが、実際は、この壁面線の後退距離よりもさらに下がっていくというのは。","voiceIndex":22,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと質問と答弁がかみ合ってないような感じがするんですけれども、ほかのＢ－１地区とかというのは１０メートルというお話だったんですが、私の質問というのは、何で８メートルとか５メートルなのかというところなんですが、要するに、これは高さがもうこれしかつくれないよということで、容積をいっぱいいっぱいとるとなると余り後退できない、そういう考えで５メートルとか８メートル。","respondent":"南雲都市開発課長","answer":"この壁面線の後退も定められまして、さらに事業者のほうでどういう建物をつくるかを考えるときに、空地の利用ですとかそういうものを考えて建物の形を定めていくということで、建物の計画の前に、まず都市計画で定める最低限の基準というものがこの壁面線の後退です。","voiceIndex":24,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"意見","question":"何となくわかりました。今、容積率もかなり緩和されているということなんですけれども、この地域全体と、あと東口の再開発のところ全体と、このＢ－４地区のところを合わせてでいいのですけれども、全体的に、あと容積での緩和というのがありましたけれども、ほかに緩和されているものというのは主にどんなものがありますか。","respondent":"南雲都市開発課長","answer":"ここについては、この東口全体で一体的に開発するということで、個々に建てた場合には、隣の建物との間で隣地の斜線制限ですとか、隣の建物との間の制限を加えているんですけれども、この地区については一体的に建てるということで。","voiceIndex":26,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問・要望","question":"はい、わかりました。住民の方々の一番の要望というのはやはり立体交差と思うんですけれども、実際にアンダーパスということになると、この再開発のところを利用する方々は第一京浜に出るのに非常に出やすい、そういうことになるんだけれども、地域住民の方の利害からかんがみて、全然変わらないというふうに思うんですよね。","respondent":"南雲都市開発課長","answer":"この八ツ山アンダーパスについては、整備の内容については従来どおり立体化するということですね。ここの図面でいきますと補助１４９号線の下をトンネルでつくって第一京浜の……〔「踏切」と呼ぶ者あり〕踏切ですか。","voiceIndex":28,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"これが置いてきぼりになっちゃうというのは、やはりなかなか理解されないというふうに私は思うんです。確かに建設委員会のときもその費用の問題という話は出たんですけれども、具体的にどういう計算でなっているのか、これはもうちょっとわかりやすくお聞かせいただければと思います。","respondent":"岩田管理工事課長","answer":"当時、国鉄清算事業団が東口を区画整理事業で開発を進めるという話が出たときに、こういった開発に伴ってこれだけ大規模な開発が行われれば、当然発生交通量も相当なものが生まれてまいりますので、我々品川区にとってこの八ツ山踏切の問題については。","voiceIndex":30,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"考え方としては、開発の事業で利用する人がふえる、その分はこっちのほうでやるからという、アンダーパスのほうを通るから地区の影響をなくすんだという話なのだろうと思うんですけれども、住民の方の要望というのは、やはりこの立体交差の解消ということだと思うんですよね。そういう意味では、もうちょっと何とかならないのかなというのは、この段に来てもやはり非常に強く感じております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"藤田委員","kind":"質問","question":"垣または柵の構造なんですけれども、今までは旧条文ではなかったものを新たに設けた、その理由はどういうものがあるのかということをお伺いします。","respondent":"田平建築課長","answer":"従来なかったわけじゃなくて、Ａ－１、Ｂ－１には条文があったわけです。これは新旧対照表でわかりにくくて申しわけございませんが、旧条文になかったとは言えないんです。今回、Ｂ－４地区という新たな地区がふえたので、そっくり同じに写しかえているということです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"藤田委員","kind":"質問","question":"そうしますと、門または塀の構造が、この部分は先ほど説明ありましたように、このＢ－４地区というのはオフィス地区になるということで、このパースを見てみますと、かなり高層ですね。ここで、何ゆえ透視可能なフェンスまたは鉄柵等が必要なのかということなんですけれども、それの理由をちょっと教えてください。","respondent":"田平建築課長","answer":"やはりこの品川駅東口再開発全体の景観だとか、それからこういうフェンスなんかつくる場合には統一感がもちろん望まれるわけで、つくる場合にあっては、そういう統一がとれたものにすべきであるという考え方からこういう条文になっております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、むしろこういうのは設けちゃいけないよというのであれば、これはすっきりするんでしょうけれども、例えば火災があった場合に、だあっと逃げていった場合に、どれだけの人がこのオフィスで仕事をしているときに、どういう形で逃げられるかということを考えれば、本来はここはこういうものは設けちゃいけないよというならまだ理解できるんですけれども、これを張りめぐらせると。","respondent":"田平建築課長、南雲都市開発課長","answer":"今後、都市開発課のほうで具体的な周囲の構築物について協議してまいりますが、そのような防犯上、避難上の観点も踏まえまして協議していきたいというふうに思っています。一部管理上の問題もあって、小規模な柵で、バックヤードのような場合も中にはありますので、全部禁じてしまうというのは管理の問題からも問題が生じてしまいますので、最低限の基準としてこういう透視可能なものということでして。","voiceIndex":37,"id":"exchange-016"},{"speaker":"藤田委員","kind":"質問・要望","question":"防犯上であれば、コンクリートでがっちり囲めれば、ブロック塀が一番防犯上はこういうのが防げるんじゃないかと思うんですけれども、そういう意味からすれば。その辺、ぜひ頭に入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"ちょっとお聞きをしたいんですが、この建物についての、帰属を教えていただきたいなと思いまして、通常ですと入り口という感じだけれども、これで見ると半分以上は建物も土地も持っているが、帰属は品川区ですか、港区になるんですか。","respondent":"岩田管理工事課長","answer":"２枚目で見ていただきますと、建物が品川区が約５０％強、港と半分ずつぐらいですが、ただ、残念ながら入り口が港区側にできておりまして、このビルの住所そのものは港区港南なという位置づけになる予定です、まだできておりませんので。","voiceIndex":41,"id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"そうしますと、確認だけさせていただきたいんですが、品川区に帰属するのは、このＶタワーの隣の低層階と公園の３というところが品川区で維持管理というか帰属をされて、一部道路がちょっとあるけれども、そういう考えでいいのかどうかだけ、ちょっと確認。","respondent":"南雲都市開発課長","answer":"品川区に帰属しますのは、Ｖタワーの前の半円状の低層のほうと公園ということになります。道路上にデッキといいますか、歩道橋はできています。","voiceIndex":43,"id":"exchange-019"},{"speaker":"石田委員","kind":"質問","question":"もう１点だけ。ところが、地域のコミュニティーは、北品川１丁目、八ツ山町会に入っていく話になると思うんですが、そこら辺の兼ね合いの、入居される方にどうやって説明をしていこうという準備がされているのか、されていないのか、そこだけちょっとお聞きします。","respondent":"南雲都市開発課長","answer":"このＶタワーについては、１つの事業者が一括で販売をしておりますが、販売の時点で重要事項の説明の中で、この低層の階については品川区、それから高層の階については港区に帰属するということで、小学校などの学校についてもそれぞれの区になりますので。","voiceIndex":45,"id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"そこの確認を、例えばそう言ったとしても、現実に行った場合に、じゃ友達がこうだからというときに、品川区は結構受け入れてくれるかもしれないけれども、港区は港南小学校になると思うけれども、そこら辺との話し合いをちゃんと詰めておいていただきたいという要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問・要望","question":"一方では大企業、いわゆるそのための街づくりというのが、かなり容積も急に緩和をしてどんどん大きなのをつくる一方で、本来やるべきところというのが進んでいないというのはやはり納得できないというふうに思います。もう１つは、さっきも質問したんですけれども、やはり八ツ山の踏切の解消問題というのは、やはり一番の地域の方々の要望だというふうに思うんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-022"},{"speaker":"上山委員","kind":"意見","question":"ちょっとお尋ねするだけなんですが、住民の皆さんからすると、この大崎の方面だとか西品川の今回の自由通路延伸で西口のほうに延びるということで、非常に期待をされて、早くという声が聞かれるんだけれども、当初何か、大体開通と同じぐらいまでにはつながるというか、できるんじゃないかというような感触があったと思うんですけれども、工事上で何かあったのか、あるいは今少しおくれるという話だったか。","respondent":"南雲都市開発課長","answer":"平成１３年１２月の臨海副都心線の開通というのは、これは何としても達成するつもりで、優先順位としては一番高いということもございまして、そういうことから、当初は構築物も考えていたんですけれども、この狭い範囲の中でふくそうする工事を行うということになるとですね。","voiceIndex":57,"id":"exchange-023"},{"speaker":"上山委員","kind":"質問・要望","question":"大変なことで、非常に何かここら辺の住民の方からすると大事なことであると思いますので、ぜひ方々に働きかけや要望を含めて、お願いしたい、この要望だけよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-024"},{"speaker":"三上委員","kind":"確認","question":"ある程度、ちょっと確認だけさせてください。これが逆になってるというのは、その逆のこの横のところが階段というところでいいんですか。なぜそういうふうな考え方がされないのかということの、構造上の問題があるというのであれば、それはそれでわかるんですけれども、そこらあたりちょっとはっきりと、こういう形にならざるを得ないという理由を明確にしていただけません。","respondent":"南雲都市開発課長","answer":"駅舎については、どうしてもこの場合、今は山手線の上にあるんですが、さらに臨海副都心線の上にも改札をつけるということは、これはＪＲのほうとしてもできないということで、ＪＲの場合ですと、北と南に別に通るということであれば可能だということなんですけれども。","voiceIndex":60,"id":"exchange-025"},{"speaker":"三上委員","kind":"質問","question":"けれども、結局この自由通路も段差がついてずっと１６３号線までつながってきているわけでしょう。形状に合わせて両方ともつくっているということじゃないですか。自由通路の幅が、仮に渡り廊下的に、それこそ１メートルでも５０センチでも離れた形の自由通路とこ線橋を２本通すような形にでもしておけば、将来的に壁をぶち破って、そこのところにつながっていくことにでもすれば、できる話になるわけですよ。","respondent":"中谷まちづくり事業部長","answer":"本日の図面では、臨海副都心線のホームの全体の話がわかりませんので、先生のほうには申しわけないのですが、この自由通路よりも相当左側、この図面で南側の方面のほうに持ってこざるを得なかったという経過の技術的な部分と、ＪＲとの交渉経過がありますので。","voiceIndex":62,"id":"exchange-026"},{"speaker":"三上委員","kind":"質問","question":"いや、ＪＲがそういう言うのもわかるけれども、乗降客が多くなったら、問題の批判というのはＪＲに集中するわけでしょう。違いませんか。今の段階、そう思いませんか。これはもう余りにも、ＪＲは勝手だけれども、こちら側が余りにも、そういった点に対しての強く主張していないということでないんじゃないんですか。私はそうだとしか思えない。","respondent":"中谷まちづくり事業部長","answer":"〔発言する者あり〕 先ほどちょっとご説明したんですが、将来もしこちらに改札をもう１つつくるようになると、これはどこか費用負担してつくるようになるということになりますれば、ここのとこからこちらへつなげるわけですね。","voiceIndex":64,"id":"exchange-027"},{"speaker":"三上委員","kind":"質問","question":"将来の西口のそういった方向性というのは、時代が変わってこようが、必ずあの広い土地ですから、何らかの形で行われるのは当然わかっているわけでしょう。そんなことを言っていたら、西口の形になってきちゃう、今度はＪＲで駐輪場、どういう形で整備するんですか、今度はもうそういう運動起きてきざるを得ないじゃないですか。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"今の質問の関連なんですけれども、資料を見ますと、平成１０年のところで利用客が４万7,０００人になっているんですが、平成１０年ですとまだゲートシティがオープンしていないと思うんですけれども、直近では大体どのくらいになっているのかというと、西口は、先ほどの話でいいんですが、利用客がどのくらいになる見込みなのか。","respondent":"南雲都市開発課長","answer":"その中でも比較的混雑する前といいますか、スムーズに歩けるような水準を確保するということで、この１５メートルという幅員はつかめておりますので、将来の人口全部通ったとしても、ここの１５メートルの幅員がある通路であれば。","voiceIndex":67,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"私が聞いているのは、今回このＦ型のこ線橋、いわゆる地元負担なんですよね。普通の考え方で、私なんかの感覚で言いますと、これは駅を利用する方だから、やはりＪＲの負担じゃないかというふうに思うんですけれども、これはＪＲがつくらない、こういうものはつくってほしいというところが金を出すべきなんだと、それが簡単に言うとＪＲのほうの理屈ですよね。","respondent":"南雲都市開発課長","answer":"ＪＲの内部では、例えば乗降客数何人当たり改札口が幾つというような基準があると思うんですが、具体的に何人になったらこ線橋をつくらなきゃならないというような法的な基準はないと思います。","voiceIndex":69,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっとそこのところは、この前も神戸の駅で、あの花火の事故がありましたけれども、やはり何らかの向こう側の基準なんかもあるんじゃないかというふうに思うんですよね。これから交渉していく上でも、向こう側の理屈というか、考え方もしっかり、もしかしてちゃんと持っておいたほうが話がしやすいかななんていうふうに思いました。ちょっとした感想です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-031"},{"speaker":"上山委員","kind":"質問","question":"一般に例えば高さがどれくらいになるのか、もし概略がわかれば、ちょっと教えていただけませんでしょうか。","respondent":"南雲都市開発課長","answer":"再開発事業につきます３棟の建物について、大まかな状況をご説明させていただきたいと思いますが、これについてはまだ計画が完全に固まっておりませんので、今後の数字については動くという可能性があります。","voiceIndex":80,"id":"exchange-032"},{"speaker":"上山委員","kind":"質問・要望","question":"計画がまだ策定していないと思いますが、もう１つお伺いしたいんです。それから、直接、違うかもしれませんが、備蓄棟と書いてあるところ、こちらの今再開発組合が単独で行うという、こちらもし何か情報があれば、どこがどのような感じになるのか教えていただければ、お伺いしたいんです。","respondent":"南雲都市開発課長","answer":"この再開発事業の推進の体制ですが、この土地につきましては大林組と日本鋪道という２社が参加組合員予定者ということで、再開発準備組合との間で覚書を結んでおりまして、今後細かい内容については当事者同士で詰めるということで。","voiceIndex":82,"id":"exchange-033"},{"speaker":"上山委員","kind":"質問・要望","question":"今回、当初はここは三井不動産なども入っていたように思うんですけれども、中心的な土地を持っていたように思ったんですが、何かそういういきさつでおりたかどうか、何かよくわかりませんけれども、何か情報があれば教えていただきたいのが１つ。","respondent":"南雲都市開発課長","answer":"これまではこの第３地区については、三井不動産も事業共同者ということで、事務局の運営などにかかわっておりましたが、これが後退したということで、組合に来たいという企業ですとか多くの方が、組合の手で事業を進めていこうということで。","voiceIndex":84,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"このティクス棟というのは、今千代田グラビアのあるところかと思うんですけれども、千代田グラビアが名前が変わったということじゃないんですか。千代田グラビアはまた別なんですか。","respondent":"南雲都市開発課長","answer":"申しわけありません。","voiceIndex":86,"id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、ここは金陽社があったところになるわけですか。金陽社がここには参加しないで独自に土地を売って、というそういう形になっているんですか。","respondent":"南雲都市開発課長","answer":"金陽社は組合の中に入っておりまして、金陽社ですとか、大きなところとしましては三明化成、東罐共榮というような会社が組合をつくっておりまして、それでこの３棟をつくるということで、このティクスというのは、親会社は戸部工業という会社なんですが。","voiceIndex":88,"id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"戸部工業ですね、わかりました。それとあと、これは組合には入らないけれども、一体的に事業を進めるということなんですが、具体的にどういう、これによって例えば制約を受けるもの、ティクスの側が制約を受けるものがあるとか、あるいは逆にいろいろ便宜を図ってもらえるみたいなものがあるとか、そこのところをちょっとあればお伺いしたいと思います。","respondent":"南雲都市開発課長","answer":"ここでは立体ということで、真ん中のところは人工地盤でちょっと暗いですけれども、ここに面してこの２棟のオフィス棟が入り口をつくるということで、こういう建物の周りの部分は人が自由に行き来できるような形状にすることで、自分のところの土地の境界であっても。","voiceIndex":90,"id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどのビデオで、少しここの建物が低くなってたかなと思うんですけれども、これは何メートルぐらいなんですか。","respondent":"南雲都市開発課長","answer":"こちらの建物ですが、組合のほうは２２階で、このティクスのほうの建物は１７階ですので、５層ですから、１５メートルから２０メートルくらい低いという形になります。","voiceIndex":92,"id":"exchange-038"},{"speaker":"宮崎委員","kind":"質問","question":"はい、わかりました。先ほど事業費と補助金のところで、上山委員も聞いたんですけれども、以前、私質問したときに、たしか６００億円ぐらいの総事業費で１２８億円ぐらいの補助金になるんじゃないかと、当時の試算だったと思うんですけれども、それはそれであるわけですよね。そこから変化していないということ、そういう意味ですか。","respondent":"南雲都市開発課長","answer":"過去に、想定される事業費ですとか補助金の額は報告していますが、それについては、先ほどありました三井不動産が事務局時代につくりました事業計画でございまして、その事業の資金計画などについて変化しておりまして、総事業費も変化が予定されておりまして。","voiceIndex":94,"id":"exchange-039"},{"speaker":"本田委員","kind":"質問","question":"一つだけ。その図面で三つ目のシーサイド駅の入り口というのはどこのところになるんですか。その工事の進捗はどのくらいにできるわけですか。開発とどういうふうに関連していますか。","respondent":"南雲都市開発課長","answer":"このシーサイド駅は、交通広場の近くですね。それとあと、この店舗棟というところの隣接した部分に出入り口ができるということで、これについては平成１４年１２月に、この下の部分にはこの駅もオープンする予定です。","voiceIndex":101,"id":"exchange-040"},{"speaker":"本田委員","kind":"質問","question":"交通広場と店舗棟のところ、この図面で何か白いようなコンマみたいなのがあるのが、これが出入り口の建物なんですか、今言ったのは。","respondent":"南雲都市開発課長","answer":"はい、そうですね。このパースの中で白い屋根のようなものがかかっているところがあります。交通広場の道路際のところと、店舗の道路際のところですが、これがこの駅から地上に出てくる出入り口の屋根です。","voiceIndex":103,"id":"exchange-041"},{"speaker":"築舘委員","kind":"質問","question":"この真ん中の道路がありますね。そこの両側と、あと交通広場に入るところは信号がつくんですか。真ん中の入り口ができるじゃないですか、ここの地区幹線道路。業務Ｄ棟のところの海岸通りと上と、あと交通広場のところは信号がつくのか。","respondent":"南雲都市開発課長、岩田管理工事課長","answer":"この真ん中の道路から交通広場に入る部分と、それから海岸通り、補助１６０号線のところに３カ所、信号がつきます。この東西海岸通りと１６０号線に通じます貫通道路に新たに設置する信号機は、海岸通りの突き当たりのところですね、交差部に１カ所。だから２カ所です。","voiceIndex":105,"id":"exchange-042"},{"speaker":"横山委員","kind":"質問","question":"旗の台の学校前に、確かに見たとおり大変な場所というのは、きょう初めて見させていただいたんですが、いろいろ権利者等々あるんだけれども、土地所有者が、やはりあの辺の人が土地を所有して、もっと少ない人で１筆というか、もっと簡単に区切られているのかなと私は思うんですが、それぞれがあの形で登記できるのかどうかわからないのだけれども、土地権利者はどのくらいいるんですか。","respondent":"浜脇住環境整備課長","answer":"ほとんど土地と建物は同じ方がお持ちです。ですから、４９名の土地持ちの方がいらっしゃるというふうにつかんでおります。","voiceIndex":115,"id":"exchange-043"},{"speaker":"横山委員","kind":"質問","question":"ですから、ああいったところの部分、本当はもっと区が相談に乗るという形じゃなくて、１歩２歩も踏み込んだ形で、首根っこでも引っつかまえて、それでやるぐらいの熱意がないと、やはりああいう状況というのは改善されていかないよね。だけれども、そういう状況ですから、それを本当に束ねるくらいの指導というか、行政上はどうお考えになるか。","respondent":"浜脇住環境整備課長","answer":"ですから、その辺を、何とかうまく負担がどんどんお互いが少なくなるような手法を検討していっても、やはり丸々うちのほうといいますか、行政側が建て替えるということまで今の情勢の中では難しいのではないかなというのが今、そう言ってはちょっと弱気ですけれども。","voiceIndex":117,"id":"exchange-044"},{"speaker":"石田委員","kind":"意見","question":"先ほど中心的な方がいて亡くなってしまったとここに書いてあるんだけれども、変な話、１回目のときに、その４人の方が中心となるような理解ができる説明ができていれば、その４人が中心になって輪が広がるということもあるんだけれども、それがゼロになってしまったということは、そこで説明に納得ができないで、次行ってもしようがないよということで来なかったわけなんですが、そこら辺の判断は。","respondent":"浜脇住環境整備課長","answer":"私ども、建て替え等につきましては、ご自分たちのほうで用意していただくということでございまして、当時この際に、今結構内装したり、あるいはそういう店を持つために、何かのローンみたいなのを持っていらっしゃって、それからさらに、そういったものを用意するのは難しい。","voiceIndex":119,"id":"exchange-045"},{"speaker":"石田委員","kind":"質問","question":"そこが問題で、制度の説明を多分していらっしゃると思うんですね。必ずこういうときの民間の方というのは、例えば再開発でも、漠然と、さっきの例ではないにしても、４組合の中でちょっと話たら、もうあれだけの、あれは大会社がつくったかどうかわかりませんが、そういうところがああいうビデオまでつくって、イメージのものをつくってくれるんですね。だから進まないわけね。","respondent":"浜脇住環境整備課長","answer":"全戸ごとにお渡しして、職員が一人一軒一軒に行って置いてきましたし、いらっしゃるときには説明させていただきました。そういうのが今の現状です。","voiceIndex":121,"id":"exchange-046"},{"speaker":"石田委員","kind":"質問","question":"そこら辺のことを、今言ったように、今２つのもの、じゃそれを民間でやったらどうなんですかというとこまで突っ込んで、こちらで民間とそういう話で、建物の高さの問題も含めて保留床をつくっていけばいいわけですね。この貸す費用のものまで突っ込んで出しているのかどうかわからないけれども、それと、完全な民間のやり方なんだけれども、そこまで突っ込んでやっていらっしゃるのかどうか、お答えください。","respondent":"浜脇住環境整備課長","answer":"民間とやればという話がありますが、やはり地元の方が２０名もいらっしゃいますと、ご自分たちのつながりのあるコンサルタントとか民間の方がいらっしゃいまして、なかなか地区のほうで、そういったものを行政側が一緒に配付するというのは非常に難しい状況に今はあります。","voiceIndex":123,"id":"exchange-047"},{"speaker":"横山委員","kind":"質問","question":"要するに建て替えもきかないし、ただ土地持っているというだけの話であって、それで、そういう権利というか、その人の利益も生まれてくるわけですから、やはりこういう事業を進めるに当たって法の整備というか、そういった後押しがない限り、絶対私はだめだと思うんですね。そこら辺に根っこがあるんじゃないかなと思うので、それを外して幾ら論議を積み重ねても、到達点はないんだと私は思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-048"},{"speaker":"横山委員","kind":"質問","question":"世田谷は、正直言って、今から何年ぐらい前ですか、前にここへ行って勉強しているんですよね。ですから、そういうふうにちょっと感じるので。","respondent":"浜脇住環境整備課長","answer":"今委員がおっしゃいます太子堂は三軒茶屋のそばでございまして、若干私が想定してた角じゃなくて、隣の角、区域外になっている街で、それで、太子堂２・３丁目に行ったらいいのか、北側４丁目に行ったらいいかというふうは定かではございませんが。","voiceIndex":133,"id":"exchange-049"},{"speaker":"横山委員","kind":"意見","question":"前にお邪魔して、世田谷区は進んでいるので、太子堂のほうも成果が上がっているんだと思うんですけれど。訪問の仕方で、品川区というのはまだ勉強かというような、そう言われないような形で行かないといけないなと。同じ区だし、同じ街の、地域が違っても、そこら辺のことがあるということだけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-050"},{"speaker":"川西委員","kind":"意見","question":"それで、私は、きょうの現地見させていただいて、あと２回、３回かな、そういう中でどうやって、バックアップというふうな言葉がでましたけれども、誘導策として代替地が、居住年齢も比較的高いということで、例えば都の中で、都営住宅の優先の制度とか、区の中ではシルバー住宅優先制度とかいうようなものを、そうするとそんなに金をかけないでできるから、こういうものを、１つずつ提示していかないと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-051"},{"speaker":"石田委員","kind":"意見","question":"本当に課長が一生懸命頑張っているのはわかるんですけれども、大変だなと思っていますし、それで、よく前から言っていることなんですが、１回目に行くときとか、２回目に行くときとか、今先生がおっしゃったのも一つなんですが、行くときにどうしてもやりたいという意思で行かれるんでしょうけれども、状況判断からも含めて、話し合いがずっと進んでいった、ここというときが必ずありますよね。","respondent":"浜脇住環境整備課長","answer":"私どもとすれば、きょうの地区とか、あるいはブロックごとに進まない理由といいますか、主なご意見で悩んでいらっしゃるということは、私どもとすれば解決すればいいと思って、これを出したんですけれども、かなり広範な感じでございまして。","voiceIndex":138,"id":"exchange-052"},{"speaker":"本田委員","kind":"質問・要望","question":"今横山委員さんが言われるよりも、かなり挑戦的にやらなければどうにもならぬというような地域もあります。それだけで終わっちゃうのか。それとも、ここまで制度の内容を聞いたり、この辺の網をかけた状況の中から制度改正なり、都なり国に対する要望書なり、議会として委員会としてまとめて、バックアップをしていくという形をつくっていくのか。","respondent":"山室住宅指導担当部長","answer":"今まで先生方の必要なご意見いただいたわけなんですが、もう少し区が踏み込んで、この整備を進めるということについて、実は我々のほうも事務的にはいろいろ検討しています。","voiceIndex":141,"id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6216#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":55023,"voices":145}},{"id":"h13-20010928-14","meetingId":"h13-cm09","date":"2001年9月28日","dateIso":"2001-09-28","committee":"行財政改革特別委員会","time":"午前１０時０８分～午後０時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"例えば、ここで見ると、３ページの人権啓発課で、女性問題海外派遣事業というのがありますよね。一挙に廃止ですよね。だから、それが２点目。そういう場合の、即、これのように１４年度から廃止、あるいは１５年度から廃止というふうにしていく場合に、手続というんでしょうか、やっぱり一定程度そこへの区民の声というのか、そういうものを受けとめるルールづくりが私は必要だというふうに思っているんです。","respondent":"榎本行財政改革担当課長","answer":"見直しをする場合のＣ評価の場合に、四つの視点ということで説明の部分に入っておりますけれども、この部分につきましても、事業部経営会議の中ではかなり話し合いが行われまして、どういう形でのＣなのかという形での部分がありますので、その辺については。","voiceIndex":7,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"やはり、こういう時代ですから、意欲を持った住民の皆さんが、例えば図書館ボランティアなんていうのがありますよね。でも、何か事務事業の評価のところで、勤労奉仕型に出していくというのは、例えば住民が見たときに、どういうふうに考えるんだろうなと率直に思うんですよ。そういうところを二つ指摘をしておきたいんですけど、コメントがあれば。","respondent":"榎本行財政改革担当課長","answer":"１件目の結論を出す前に、ある程度意見を聞くかという形なんでけど、そもそも事務事業評価のシステム自体が、まずは行政機関の内部で評価していくというのが一義的なシステムでありまして、その後、こういうふうに報告書を出してとか、また。","voiceIndex":9,"id":"exchange-002"},{"speaker":"金高委員","kind":"意見","question":"これが、要するに事務事業評価という形でもって行政改革の一環で出てきたと。その職員の意識改革を図るという道がありますけど、その辺の大きな変化あるいは大した変化がなかったとか、ここにすぐ出てくるのは違うとか、その辺のところはどういう形でもって目に見えてきているのか、あるいは後退しているのか、その辺、何かもしあれば。","respondent":"榎本行財政改革担当課長","answer":"各担当者もこの事務事業評価を何のために行うのかという部分につきましては、かなり論議や説明をした中での意識というのは高まっていると思います。","voiceIndex":11,"id":"exchange-003"},{"speaker":"金高委員","kind":"質問","question":"要するに、下半期といいますか、１０月以降、来年３月まで。それからさらに、例えば来年度、再来年度、これからずっと内容が続けていくことによって、職員の方々の意識が相当やっぱり変わってくるでしょうし、費用対効果もよくなって、全体の枠が上がってくると思うんですけども、その辺のところの、要するに上半期というんですか、その辺の取り組みがどういう形になっているか、ちょっと教えてください。","respondent":"榎本行財政改革担当課長","answer":"下半期の取り組みですけれども、実際にはこの事務事業評価を２１２本実施したところ、いろいろ仕組み自体に不具合な点とか、まとまっていない点とか、ある程度出てきています。","voiceIndex":13,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"上位計画との整合性ということで記載されてあるんですけども、基本構想や長期計画など、その辺との係わりということでちょっと聞きたいんですけども、まず、長期計画の中で方向づけがされておりますけれども、いろいろとこのような評価をされて、その辺の長期計画と違った評価がされてくる場合、その辺の修正というんでしょうか、係わりをどのように考えているのか聞きたいと思います。","respondent":"榎本行財政改革担当課長","answer":"その上位計画との整合性ですけれども、実際には総合実施計画の各柱を各事務事業がどう支えているかという形での関連についてという形になっております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"内容のことでちょっと細かいことを聞かせていただくんですけども、思うに、支給・助成とか、支給するものとか、そういったものにちょっと目立ったんですけども、自己評価では、見直しですとか廃止・中止というような評価の仕方をしているんですけれども、一次、二次評価では、継続というような評価の仕方がちょっと、その支給とか、助成する部分ですごく目立ったんですけども。","respondent":"中尾根企画部長","answer":"したがいまして、一つ一つの事業を検討したときに、それらを勘案してどうしたらいいのか、やっぱりこういう矛盾があるからもっと変えるべきではないか、そういう意見が今回助成であるとか、支給の、そういう部分に非常に現場サイドの考え方としては。","voiceIndex":17,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"例えば、最終的に二次評価で廃止・中止する事業が９ということで、評価としては出ておりますが、これは単にまだ途中の段階でありまして、９事業を廃止・中止にする事業として、まだ評価として指定をされた段階でありますので、これが実際に来年以降結果として廃止・中止に実際にできたのかどうか、仮にできなかった場合、まずできなかったわけですから、そこから項目もそれぞれ拡大する事業が２９ありますが。","respondent":"榎本行財政改革担当課長","answer":"特に、前回の東京都の評価システムでも、モニタリングをするということで、あと３年間をかけますというような形での説明がございましたけれども、ちょっとそんなような仕組みが入れられればなという形で、例えば、特にＤ事業であれば、数限られていますので。","voiceIndex":19,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"これは要望になりますけども、例えば、予算的にどれだけ削減できたのかなとか、あるいは区民満足度がどれだけ向上したのかとか、そういった事業が計画どおり達成できた、できていないだけではなくて、さらに一歩踏み込んだ結果があらわれるような仕組みにぜひしていただきたいと思います。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"例えば、青少年対策なんかは地区委員会や青少年委員会、いろんな問題があるけども、連帯がとれていないんじゃないか、いろんな議論がある中で、そういうときに、Ａに評価したからという形でもって、ここで言うと、地域活動課との話し合いの中で、今度ＢをＡにして、今度予算措置とかいろんな話はあるだろうけど、それをＡにしていこうという努力、今までの内部的疑問点。","respondent":"榎本行財政改革担当課長","answer":"それで、例えば最初に拡大する事業といったときに、一般的に今のいろいろな行財政の流れの中で、拡大というとやはり人員が多くなるとか、予算が多くなるとかというようなイメージでとらえた課長と、重点的にそれをＡだからそのままやるんではなくて。","voiceIndex":22,"id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、課長がしっかり、私が見ているときは区民の代表で見ていますからね、区民の代表ですから。区民から見て、これはＢだろうと。何でこれがＢなんだろう。もっと話し合いながら、一次評価、二次評価をＡにしたけども、全体をＡにするためにはどうしたらいいかというディスカッションなり、そういうものがどこでなされて、どう反映していくのかということを聞きたいんですけど。","respondent":"榎本行財政改革担当課長","answer":"要は、評価が当然方向性が違うという部分があれば、できるだけ多くのところでその事業についてどういう方向性を出したらいいのかという部分を考えていかなきゃいけないということなんですけども、その部分の、どこで議論するかという部分は。","voiceIndex":24,"id":"exchange-010"},{"speaker":"辻副委員長","kind":"確認","question":"来年度の流れですね、１４年度になったときにも、やはり今ごろの時期に評価というか、その結果が出てやるのかどうか、ちょっと確認したい。来年度、１４年度も新しくまた事業を指定すると思うんだよね。そして、結果発表するというのは、大体同じスケジュールなの、どうなの。","respondent":"榎本行財政改革担当課長","answer":"それで、予算編成に間に合わせないと意味がこの仕組み上ありませんので、９月下旬までには一定の結論を出すという大まかな流れというものは同じような形で事務事業評価につきましてはやらざるを得ないと考えております。","voiceIndex":26,"id":"exchange-011"},{"speaker":"辻副委員長","kind":"意見","question":"ごめんね。ポツポツ聞いて申し訳ない。ここで書いてある、これは一覧にしていただいたんですけど、評価シートとか、それぞれの各課部長の意見とか、そういう評価の書いてある文書みたいなのがあると思うんですね。そういう書類というのは公開の対象になっているの。要するに、詳しく我々が知りたい、見たいとかといった場合に、どうだろう。","respondent":"榎本行財政改革担当課長","answer":"現在、各課への通知を出して、やっと決定した段階ですので、ちょっとまだその部分というのはどういう取り扱いかという形で、どういう形で公表したらいいのかという部分を、これからちょっと検討する段階です。","voiceIndex":28,"id":"exchange-012"},{"speaker":"辻副委員長","kind":"質問・要望","question":"ほんとうに、我々は学校あるいは地域センターを全部かけろかけろと言ったけど、あるいは会合のたびに一生懸命朗読したり、バッと普及して、でも、経営会議でいう普及啓発を継続的に行うという、経営会議で行うということはどういうことを言ってきているのかというような、まさしくこの論議というのは、やっていかなきゃいけないのかなというんで。","respondent":"中尾根企画部長","answer":"それからもう一つの点で、モニタリングも随分出ましたけど、モニタリングも非常に重要だというのを、改めて私ども再認識しております。そこが全くないと、ほんとうに評価って自分勝手な評価だけになっちゃいますので、そこもやっぱりきちんとしたものをやらなくちゃいけないかな。","voiceIndex":30,"id":"exchange-013"},{"speaker":"辻副委員長","kind":"質問","question":"よろしくお願いしたいと思います。だから、そういう短い文章だけに、だから、私さっき言ったように、シートとか、そういう元の、ほんとうの情報公開というものをきちっとやった論議、あるいはけんけんごうごうやっても構わないけど、そういう基本的な一致点で今後決算特別委員会とかというのをやっていかないと、それで、なお、我々ある議員という立場というのはさまざまな人の代表ですから、その見方。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"鶴委員","kind":"意見","question":"詳細に読んでいないんですけれども、よくぞここまでいろいろと検討されたものだなと努力は高く評価したいと思います。そうじゃなくて、やっぱりそれを視野に入れながら取り入れていけるものは入れていくというふうな作業になっていくのかなというふうに昨日ふっとそのことを考えまして、ちょっとお尋ねしておきたいなというふうに思いました。","respondent":"中尾根企画部長","answer":"もちろん一番基本的には国の全部制度の中でやはりやらざるを得ない側面がありますので、そういう点については十分私どももちゃんと見聞きをし、そういうものを視野に入れながら、それでなおかつ全体の方針がそういうものと即応しているのかどうか、常に検証はしていますので。","voiceIndex":33,"id":"exchange-015"},{"speaker":"鶴委員","kind":"意見","question":"区民の皆さんは、いろんな形で区政を見ているもんですけれども、やっぱり皆さんがなぜそれを望んでいるのか、考えているのかということについての把握というのは、いろんな手法があるけれども、今後どういう手法で、こういう行政評価システムの中で住民の評価というのをどう重要な要素として取り入れていく手法を考えていらっしゃるのかということを知らしめていくことも大事だし、また皆さんの意見も。","respondent":"榎本行財政改革担当課長","answer":"要は、同じような意見であれば、それはまとめると。そうすると、そういう１０万の意見のうち、まとまりが幾つかに分かれていくだろうというような形でのシステムも検討しているというような話もございました。","voiceIndex":35,"id":"exchange-016"},{"speaker":"鶴委員","kind":"質問","question":"普通大きな争点がある場合、原子力発電所とか、そういう問題については、住民投票制で皆さんの動向を問う方法もあるじゃないですかね。調理委託だって、例えば学校給食はどうですか。実際、今一保育園で3,０００万円かかっている。今回の業務代行によって、半分の1,５００万円で済んでいるんですよ。おいしいって。しかしながら、民間委託している施設だっていっぱいあるじゃないですか、社会福祉法人。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-017"},{"speaker":"鶴委員","kind":"質問","question":"そういうことについて、皆さんが騒然となるわけですけども、そういうことについての皆さんの意見の吸収というのは、どういう手法で、インターネットのあれで待っているわけですか。","respondent":"中尾根企画部長","answer":"そこで、先ほど課長のほうからＩＴ化とありましたけど、そういう部分も活用しますが、要は、基本的には一つ一つの事業に係わっている人たちのきちんとやっぱりその考えなり評価なりを把握するというところがやっぱり原点だろうということで、できるだけ各事業の中でつかめる。","voiceIndex":39,"id":"exchange-018"},{"speaker":"桜井委員","kind":"確認","question":"今の区民への公表の部分なんですけど、先ほど一応スケジュールだと３月ですよね。だから、評価一覧表という、こちらに出されているんですけど、この２１２の事業を見直したものを全部評価していくという、そういう基本的な考え方でいいのかどうか、そこをもう一度確認したいんですけど。","respondent":"榎本行財政改革担当課長","answer":"公表の方法につきましては、従来からある広報紙で大まかなところ、それからホームページでそれよりもう少し細かい説明、それからさらに、ホームページの中にある程度詳細な事業ごとの方向性なりを示したような形でのページを設けて。","voiceIndex":41,"id":"exchange-019"},{"speaker":"本多委員","kind":"質問・要望","question":"依頼を受けましたとおり、当委員会から海外調査団で調査要望を出したいと思います。内容を３点読み上げます。２、行政評価は、サービスの評価とこれに基づくサービスの転換によって行政改革を進めるとされるが、その改革が市民の期待に沿った方向に進んでいることの確認をどのようにして行っているかについて。このような部分をコスト削減の区分など、財政の視点から調査をしていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-020"},{"speaker":"桜井委員","kind":"意見","question":"言わんとしていることはわからなくはないんですけども、率直に言って、このサニーベール市とか、お話にあったポートランド、オースチン、市の状況もよくわかりませんし、行政評価をどういうふうにしているのかちょっとわかりませんで、私は本多委員が聞きたいというのは、それはそれとして尊重したいと思いますけども、私の率直な気持ちとしたら、よくわからないというのが率直なところで、委員会として。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-021"},{"speaker":"鶴委員","kind":"質問","question":"わからないから調査をするという面があると思いますね。ある程度の、今、本多委員からもご説明がありましたが、やっぱりしっかり委員会として調査団にこういうことを、行かない者にとっても、帰国されてからの報告事項というのは大変参考になるわけですから、やっぱり一つの議長等の各委員会への要請もあると思いますし、海外視察というものを実効たらしめるための手段としてもこういうことは必要だ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-022"},{"speaker":"金高委員","kind":"提案","question":"これも行く方々がしっかりと認識していただき、さらにこれと現地との比較対照が具体的にどうなってくるか、それはさらにこれから１０年、１５年と、こっちのほうが先進国で、なおかつずっとやっているわけですから、先発としてやっている方向づけが見えてきていると思うんですね。ただ、それにつけ加えるようなことも持ってきていただきたいというふうに要望しておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"手続的なことで言いましても、海外調査団の団長、松澤団長から林議長あてにこういう項目で調査したいので、各委員会に調査内容についての調査を依頼されて、それを受けた議長が当塚本行財政改革特別委員長あてにその依頼が来ているということですので、その主義主張云々ではなくて、手続的に議長から委員長への問いかけですから、委員長が委員会を代表されますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-024"},{"speaker":"桜井委員","kind":"意見","question":"私はちょっと意見を申し上げたいのは、この当行財政改革特別委員会で行政視察をしていくという性格がまずないですよね。それはそれとして生かすことは別にいい。ただ、委員会というふうな性格になってくると総意というふうになるので、できれば、それは各委員の皆さんの意見にとどめていただければ、そういうことです。賛否を問うというふうには思っていませんけど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-025"},{"speaker":"辻副委員長","kind":"質問・要望","question":"一番基本的な部分で調査していただきたいというのは前提になるんですけど、要するに市の仕組み、行政の仕組みなんです。要するに、税制はどういう形になるから、あと議員と議会とか、我々のものと違うと思うんだよね。市の仕組み。市政概要じゃないんですよ。それよりもう一歩突っ込んだところ。評価の範囲は金高委員が言ったように、ちょっとそのところは持っていてほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-026"},{"speaker":"鶴委員","kind":"質問・要望","question":"ほかの点は、文教委員会からも出ているのかもしれませんが、これは行革絡みのテーマだけ。今、辻委員が言いましたけど、特にそれぞれの訪れたところで結構ですから、議会の定数、人口と定数というのを。メーン州のポートランド市はたった７名しかいないんですよ。人口６万数千人、僕の記憶によると。それで、今、辻副委員長が言ったように、ちょっと仕組みが違うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5692#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":37389,"voices":77}}]);
